  function submitCancelApplication(event) {
    if (event) event.preventDefault();
    initAdmissions();

    const appId = document.getElementById('cancelTargetAppId')?.value;
    const app = state.admissions.find(a => a.appId === appId);
    if (!app) return;

    const dec = document.getElementById('cancelDecisionType')?.value || 'Rejected';
    const cat = document.getElementById('cancelReasonCategory')?.value || 'Statutory Reason';
    const remarks = (document.getElementById('cancelRemarks')?.value || '').trim();

    if (!remarks) {
      showToast('Please state a detailed reason for cancellation or rejection.', 'warning');
      return;
    }

    const fullReason = `${cat}: ${remarks}`;
    app.status = dec;

    if (!app.decisionHistory) app.decisionHistory = [];
    app.decisionHistory.unshift({
      timestamp: new Date().toLocaleString(),
      actor: (state.currentUser && state.currentUser.name) || 'Executive Principal Smt. Gorle Varalakshmi',
      action: dec,
      remarks: fullReason
    });

    closeModal('cancelApplicationModal');
    filterAdmissions();
    showToast(`Application ${appId} marked as ${dec}. Recorded justification logged to audit trail.`, 'warning');
  }

  function exportAdmissionsCSV() {
    initAdmissions();
    const all = state.admissions || [];
    const dateStr = new Date().toISOString().split('T')[0];
    let csv = 'ApplicationID,ApplicantName,DOB,Gender,ClassApplied,ParentGuardian,Relationship,Phone,Email,Address,SubmissionDate,Channel,DocumentStatus,ApplicationStatus,AssignedOfficer,Score,FeeStatus,FeeAmount\n';
    all.forEach(a => {
      const clean = (val) => String(val || '').replace(/"/g, '""');
      csv += `"${clean(a.appId)}","${clean(a.name || a.studentName)}","${clean(a.dob)}","${clean(a.gender)}","${clean(a.class || a.grade)}","${clean(a.parent)}","${clean(a.guardianRel || 'Father')}","${clean(a.phone)}","${clean(a.email)}","${clean(a.address)}","${clean(a.submissionDate)}","${clean(a.intakeChannel)}","${clean(a.docStatus)}","${clean(a.status)}","${clean(a.assignedOfficer)}","${clean(a.score)}","${clean(a.feeStatus)}","${clean(a.feeAmount || '₹12,500')}"\n`;
    });
    downloadCsvFile(csv, `sri_vidya_admissions_master_register_${dateStr}.csv`);
    showToast(`Admissions Master Register (${all.length} applications) exported to CSV successfully.`, 'success');
  }

