  // Export to CSV utility
  function exportTableToCSV(tableId, filename) {
    const table = document.getElementById(tableId);
    if (!table) return;

    let csv = [];
    const rows = table.querySelectorAll('tr');
    for (let i = 0; i < rows.length; i++) {
      const row = [], cols = rows[i].querySelectorAll('td, th');
      for (let j = 0; j < cols.length - 1; j++) { // Exclude actions column
        let data = cols[j].innerText.replace(/(\r\n|\n|\r)/gm, '').replace(/(\s\s+)/g, ' ');
        data = data.replace(/"/g, '""');
        row.push('"' + data + '"');
      }
      csv.push(row.join(','));
    }

    const csvFile = new Blob([csv.join('\n')], { type: 'text/csv' });
    const downloadLink = document.createElement('a');
    downloadLink.download = filename || 'export.csv';
    downloadLink.href = window.URL.createObjectURL(csvFile);
    downloadLink.style.display = 'none';
    document.body.appendChild(downloadLink);
    downloadLink.click();
    document.body.removeChild(downloadLink);

    showToast(`Exported ${filename} successfully`, 'success');
  }

  // Toast Notification System (Deduplicated & Cleanly Positioned)
  function showToast(message, type = 'info') {
    const container = document.getElementById('toastContainer');
    if (!container) return;

    // Deduplicate: ignore if an identical message is already visible
    const existing = container.querySelectorAll('.portal-toast');
    for (const t of existing) {
      if (t.innerText && t.innerText.includes(message)) {
        return;
      }
    }

    // Limit maximum concurrent toasts to 2
    while (container.children.length >= 2) {
      if (container.firstElementChild && typeof container.firstElementChild.remove === 'function') {
        container.firstElementChild.remove();
      } else if (container.firstChild && typeof container.removeChild === 'function') {
        container.removeChild(container.firstChild);
      } else {
        break;
      }
    }

    const toast = document.createElement('div');
    toast.className = `portal-toast toast-${type}`;
    
    let icon = 'fa-solid fa-circle-info';
    if (type === 'success') icon = 'fa-solid fa-circle-check';
    if (type === 'warning') icon = 'fa-solid fa-triangle-exclamation';
    if (type === 'error') icon = 'fa-solid fa-circle-xmark';

    toast.innerHTML = `
      <i class="${icon} toast-icon"></i>
      <div class="toast-text">${message}</div>
      <button class="toast-close" type="button" onclick="this.closest('.portal-toast').remove()" aria-label="Dismiss">&times;</button>
    `;

    container.appendChild(toast);

    setTimeout(() => {
      toast.style.transition = 'all 0.3s ease';
      toast.style.opacity = '0';
      toast.style.transform = 'translateY(10px)';
      setTimeout(() => { if (toast.remove) toast.remove(); else if (toast.parentNode) toast.parentNode.removeChild(toast); }, 300);
    }, 3500);
  }

  // Discipline Incident Rendering & Management
  function renderDisciplineIncidents(list) {
    const tableBody = document.getElementById('incidentsTableBody');
    const container = document.getElementById('disciplineIncidentsGrid');
    const incidents = list || state.disciplineIncidents || [];

    // Sync badges & stats
    const badgeAll = document.getElementById('tabBadgeDisciplineAll');
    if (badgeAll) badgeAll.textContent = incidents.length;
    const activeBadge = document.getElementById('activeIncidentsBadge');
    const openCount = (state.disciplineIncidents || []).filter(i => i.status !== 'Resolved').length;
    if (activeBadge) activeBadge.textContent = `${openCount} Active Case${openCount === 1 ? '' : 's'}`;
    const activeCasesCount = document.getElementById('activeCasesCount');
    if (activeCasesCount) activeCasesCount.textContent = openCount;

    if (tableBody) {
      if (incidents.length === 0) {
        tableBody.innerHTML = '<tr><td colspan="7" class="text-center p-4 text-muted">No disciplinary incidents match the selected criteria. All students in good standing!</td></tr>';
      } else {
        tableBody.innerHTML = incidents.map(inc => {
          let badgeClass = 'badge-warning';
          if (inc.status === 'Resolved') badgeClass = 'badge-success';
          else if (inc.severity === 'Severe' || inc.severity === 'High') badgeClass = 'badge-danger';

          let sevBadge = 'badge-neutral';
          if (inc.severity === 'Severe' || inc.severity === 'High') sevBadge = 'badge-danger';
          else if (inc.severity === 'Moderate') sevBadge = 'badge-warning';
          else if (inc.severity === 'Minor') sevBadge = 'badge-primary';

          return `
            <tr>
              <td>
                <strong class="text-primary font-mono" style="font-size: 0.88rem;">${inc.id}</strong>
              </td>
              <td>
                <div style="font-weight: 700; color: #1e293b;"><i class="fa-regular fa-calendar text-muted"></i> ${inc.date}</div>
                <small class="text-muted"><i class="fa-regular fa-clock"></i> ${inc.time || '11:15 AM'}</small>
              </td>
              <td>
                <span class="portal-badge ${sevBadge}" style="display: inline-block; margin-bottom: 2px;">${inc.severity} Severity</span>
                <div style="font-size: 0.82rem; font-weight: 600; color: #334155;">${inc.category}</div>
              </td>
              <td>
                <div style="font-weight: 700; color: #0f172a; font-size: 0.9rem;">${inc.student}</div>
                <small class="text-muted"><span class="font-mono">${inc.admNo || 'SV-0042'}</span> &bull; <span class="profile-tag tag-primary">${inc.class}</span></small>
              </td>
              <td>
                <span class="portal-badge ${badgeClass}" style="font-weight: 700;">${inc.status}</span>
              </td>
              <td>
                <div style="font-size: 0.82rem; font-weight: 700; color: #0f172a; line-height: 1.35;">${inc.authorizedAction || inc.action}</div>
                <small class="text-muted" style="display: block; margin-top: 2px;"><i class="fa-solid fa-user-shield text-primary"></i> Authorized: ${inc.authorizedBy || 'Vice Principal Sri Navva Anand'}</small>
              </td>
              <td style="text-align: center; white-space: nowrap;">
                <button class="btn btn-secondary btn-sm" onclick="portalApp.viewIncidentDetails('${inc.id}')" title="View Incident Dossier">
                  <i class="fa-solid fa-eye"></i>
                </button>
                ${inc.status !== 'Resolved' ? `
                  <button class="btn btn-secondary btn-sm" onclick="portalApp.summonParent('${inc.id}', '${inc.student}')" title="Summon Parent">
                    <i class="fa-solid fa-phone text-amber"></i>
                  </button>
                  <button class="btn btn-primary btn-sm" onclick="portalApp.resolveIncident('${inc.id}')" title="Mark Incident Resolved">
                    <i class="fa-solid fa-check"></i>
                  </button>
                ` : ''}
              </td>
            </tr>
          `;
        }).join('');
      }
    }

    if (container) {
      if (incidents.length === 0) {
        container.innerHTML = '<div class="p-4 text-center text-muted">No disciplinary incidents on record. All students in good standing!</div>';
        return;
      }
      container.innerHTML = incidents.map(inc => {
        let badgeClass = 'badge-warning';
        if (inc.severity === 'Severe' || inc.severity === 'High') badgeClass = 'badge-danger';
        return `
          <div class="incident-card" id="inc-card-${inc.id}">
            <div>
              <div class="incident-header">
                <div>
                  <div class="incident-student">${inc.student}</div>
                  <div class="incident-class">${inc.class} &bull; <strong class="text-primary">${inc.id}</strong></div>
                </div>
                <span class="portal-badge ${badgeClass}">${inc.severity} Severity</span>
              </div>
              <div class="incident-reason">
                <strong>Category:</strong> ${inc.category}<br>
                ${inc.description}
              </div>
              <div class="incident-meta-row">
                <span><strong>Action:</strong> ${inc.authorizedAction || inc.action}</span>
                <span><i class="fa-regular fa-clock"></i> ${inc.date} ${inc.time || ''}</span>
              </div>
            </div>
            <div class="incident-actions">
              ${inc.status !== 'Resolved' ? `
                <button class="btn btn-secondary btn-sm" onclick="portalApp.summonParent('${inc.id}', '${inc.student}')">
                  <i class="fa-solid fa-phone"></i> Summon Parent
                </button>
                <button class="btn btn-primary btn-sm" onclick="portalApp.resolveIncident('${inc.id}')">
                  <i class="fa-solid fa-check-double"></i> Mark Resolved
                </button>
              ` : `
                <span class="portal-badge badge-success w-100 text-center"><i class="fa-solid fa-check"></i> Resolved &amp; Diary Signed</span>
              `}
            </div>
          </div>
        `;
      }).join('');
    }
  }

  function filterDisciplineIncidents(sev) {
    if (!state.disciplineIncidents) return;
    if (sev === 'all') {
      renderDisciplineIncidents(state.disciplineIncidents);
    } else {
      const filtered = state.disciplineIncidents.filter(i => {
        if (sev === 'High') return i.severity === 'High' || i.severity === 'Severe';
        if (sev === 'Moderate') return i.severity === 'Moderate';
        if (sev === 'Minor') return i.severity === 'Minor';
        return true;
      });
      renderDisciplineIncidents(filtered);
    }
  }

  function viewIncidentDetails(id) {
    const inc = (state.disciplineIncidents || []).find(i => i.id === id);
    if (!inc) return;
    alert(`SRI VIDYA E.M HIGH SCHOOL - DISCIPLINARY INCIDENT DOSSIER\n------------------------------------------------------------\nIncident ID: ${inc.id}\nStudent: ${inc.student} (${inc.admNo || 'SV-0042'}) - ${inc.class}\nDate & Time: ${inc.date} at ${inc.time || '11:15 AM'}\nCategory: ${inc.category} (Severity: ${inc.severity})\nStatus: ${inc.status}\n\nDetails:\n${inc.description}\n\nAuthorized Action:\n${inc.authorizedAction || inc.action}\nAuthority: ${inc.authorizedBy || 'Vice Principal Sri Navva Anand'}\nEndorsed: Principal Smt. Gorle Varalakshmi`);
  }

  function handleLogIncident(e) {
    e.preventDefault();
    const name = document.getElementById('incStudentName')?.value;
    const cls = document.getElementById('incClass')?.value;
    const cat = document.getElementById('incCategory')?.value;
    const sev = document.getElementById('incSeverity')?.value;
    const desc = document.getElementById('incDescription')?.value;
    const action = document.getElementById('incActionTaken')?.value;

    if (!name || !desc) {
      showToast('Please provide student name and details', 'warning');
      return;
    }

    const newInc = {
      id: `DIS-2026-0${Math.floor(43 + Math.random() * 50)}`,
      student: name,
      class: cls,
      category: cat,
      severity: sev,
      description: desc,
      action: action,
      status: 'Open',
      date: 'Just now'
    };

    state.disciplineIncidents.unshift(newInc);
    renderDisciplineIncidents(state.disciplineIncidents);
    closeModal('logIncidentModal');
    e.target.reset();

    const activeCountEl = document.getElementById('activeCasesCount');
    if (activeCountEl) {
      const openCases = state.disciplineIncidents.filter(i => i.status === 'Open').length;
      activeCountEl.textContent = openCases;
    }

    showToast(`Discipline record ${newInc.id} logged for ${name} under Vice Principal oversight`, 'success');
  }

  function resolveIncident(id) {
    const inc = state.disciplineIncidents.find(i => i.id === id);
    if (inc) {
      inc.status = 'Resolved';
      renderDisciplineIncidents(state.disciplineIncidents);
      const activeCountEl = document.getElementById('activeCasesCount');
      if (activeCountEl) {
        const openCases = state.disciplineIncidents.filter(i => i.status === 'Open').length;
        activeCountEl.textContent = openCases;
      }
      showToast(`Incident ${id} marked as resolved and logged in permanent student register`, 'success');
    }
  }

  function summonParent(id, studentName) {
    showToast(`SMS notice and official conference letter dispatched to parent of ${studentName} for Monday meeting with Vice Principal`, 'warning');
  }

  // Substitution Assignment Handler
  function handleAssignSubstitution(e) {
    e.preventDefault();
    const absent = document.getElementById('subAbsentTeacher')?.value;
    const period = document.getElementById('subClassPeriod')?.value;
    const substitute = document.getElementById('substituteTeacher')?.value;

    closeModal('assignSubstitutionModal');
    e.target.reset();
    showToast(`Substitution allocated: ${substitute} assigned to ${period} in place of ${absent}`, 'success');
  }

  // VP Faculty Leave Review Table Rendering
  // VP Faculty Leave Review Table Rendering
  // User Requirement: Employee, leave type, dates, balance, reason and approval actions
  function renderVPLeaves(list) {
    const tbody = document.getElementById('vpLeaveTableBody');
    if (!tbody) return;

    const data = list || state.facultyLeaves || [];

    if (data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" class="text-center p-4 text-muted"><i class="fa-solid fa-circle-check text-emerald mr-1"></i> All faculty leave applications have been reviewed and processed.</td></tr>';
      return;
    }

    tbody.innerHTML = data.map(item => {
      let badgeCls = 'badge-warning';
      if (item.type.includes('Medical')) badgeCls = 'badge-danger';
      else if (item.type.includes('Duty') || item.type.includes('OD')) badgeCls = 'badge-primary';
      else if (item.type.includes('Earned')) badgeCls = 'badge-warning';

      let appStatusCls = 'badge-warning';
      if (item.approvalStatus === 'Approved') appStatusCls = 'badge-success';
      else if (item.approvalStatus === 'Rejected') appStatusCls = 'badge-danger';
      else if (item.approvalStatus === 'Returned for Correction') appStatusCls = 'badge-danger';

      const initials = (item.name || 'Staff').replace(/^(Sri|Smt.|Mrs.|Mr.)s*/, '').split(' ').map(p => p[0]).join('').slice(0, 2);

      return `
        <tr id="vp-leave-row-${item.id}">
          <td>
            <div style="display: flex; align-items: center; gap: 0.65rem;">
              <div style="width: 36px; height: 36px; border-radius: 50%; background: #e0e7ff; color: #3730a3; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 0.8rem; flex-shrink: 0;">
                ${initials}
              </div>
              <div>
                <strong style="color: #0f172a; font-size: 0.88rem; display: block;">${item.name}</strong>
                <div style="font-size: 0.74rem; color: #64748b; margin-top: 1px;">
                  <span class="font-mono" style="font-weight: 600;">${item.staffId}</span> &bull; ${item.role || 'Faculty'}
                </div>
              </div>
            </div>
          </td>
          <td>
            <span style="font-size: 0.84rem; color: #1e293b; font-weight: 600;">${item.dept}</span>
          </td>
          <td>
            <span class="portal-badge ${badgeCls}" style="font-weight: 700; font-size: 0.75rem;">
              <i class="fa-solid ${item.type.includes('Medical') ? 'fa-hospital' : (item.type.includes('Duty') ? 'fa-medal' : 'fa-calendar-day')} mr-1"></i> ${item.type}
            </span>
          </td>
          <td>
            <strong style="font-size: 0.84rem; color: #1e293b; display: block;">${item.dates}</strong>
          </td>
          <td>
            <span class="portal-badge badge-neutral" style="font-weight: 700; font-size: 0.75rem;">
              <i class="fa-solid fa-clock mr-1"></i> ${item.daysRequested || item.days || (item.daysCount + ' Days')}
            </span>
          </td>
          <td>
            <div style="font-weight: 700; font-size: 0.80rem; color: #0369a1;">
              <i class="fa-solid fa-scale-balanced mr-1"></i> ${item.balance || 'CL: 8/12 Left'}
            </div>
          </td>
          <td>
            <div style="font-size: 0.82rem; color: #334155; line-height: 1.35;">${item.reason}</div>
            <div style="margin-top: 3px; font-size: 0.74rem; color: #059669; font-weight: 700;">
              <i class="fa-solid fa-user-shield mr-1"></i> Cover: ${item.substitute || 'Pending'}
            </div>
          </td>
          <td>
            <span class="portal-badge ${item.supportingDocsStatus && item.supportingDocsStatus.includes('Verified') ? 'badge-success' : 'badge-warning'}" style="font-size: 0.72rem;">
              <i class="fa-solid ${item.supportingDocsStatus && item.supportingDocsStatus.includes('Verified') ? 'fa-file-circle-check' : 'fa-file-lines'} mr-1"></i> ${item.supportingDocsStatus || 'Document Attached'}
            </span>
          </td>
          <td>
            <span class="portal-badge ${appStatusCls}" style="font-weight: 700; font-size: 0.75rem;">
              <i class="fa-solid ${item.approvalStatus === 'Approved' ? 'fa-circle-check' : (item.approvalStatus === 'Returned for Correction' ? 'fa-rotate-left' : 'fa-clock')} mr-1"></i> ${item.approvalStatus || item.status || 'Pending Review'}
            </span>
          </td>
          <td style="text-align: center;">
            <div class="table-action-btns" style="justify-content: center; gap: 0.3rem; display: flex; flex-wrap: wrap;">
              <button class="btn btn-secondary btn-sm" onclick="portalApp.openFacultyLeaveReviewModal('${item.id}')" title="Review Complete Application" style="padding: 0.25rem 0.5rem; font-size: 0.74rem;">
                <i class="fa-solid fa-magnifying-glass mr-1"></i> Review
              </button>
              <button class="btn btn-success btn-sm" onclick="portalApp.approveFacultyLeave('${item.id}')" title="Approve Leave & Confirm Cover" style="padding: 0.25rem 0.5rem; font-size: 0.74rem;">
                <i class="fa-solid fa-check mr-1"></i> Approve
              </button>
              <button class="btn btn-danger btn-sm" onclick="portalApp.openRejectFacultyLeaveModal('${item.id}')" title="Reject Request with Justification" style="padding: 0.25rem 0.5rem; font-size: 0.74rem;">
                <i class="fa-solid fa-xmark mr-1"></i> Reject
              </button>
              <button class="btn btn-warning btn-sm" onclick="portalApp.openReturnFacultyLeaveModal('${item.id}')" title="Return for Correction" style="padding: 0.25rem 0.5rem; font-size: 0.74rem;">
                <i class="fa-solid fa-rotate-left mr-1"></i> Return
              </button>
              <button class="btn btn-primary btn-sm" onclick="portalApp.checkTimetableImpact('${item.id}')" title="Check Timetable Clash & Period Coverage" style="padding: 0.25rem 0.5rem; font-size: 0.74rem;">
                <i class="fa-solid fa-calendar-week mr-1"></i> Impact
              </button>
              <button class="btn btn-secondary btn-sm" onclick="portalApp.openAssignLeaveSubstituteModal('${item.id}')" title="Assign Substitute Faculty" style="padding: 0.25rem 0.5rem; font-size: 0.74rem;">
                <i class="fa-solid fa-user-plus mr-1"></i> Substitute
              </button>
            </div>
          </td>
        </tr>
      `;
    }).join('');

    const badge = document.getElementById('facultyLeaveTabBadge');
    if (badge) badge.textContent = data.length;
    const sideBadge = document.getElementById('sidebarFacultyLeaveBadge');
    if (sideBadge) sideBadge.textContent = data.length + ' Req';
    const statPending = document.getElementById('statVpLeavesPending');
    if (statPending) statPending.textContent = data.length;
  }

  function filterFacultyLeaves(type) {
    const selType = type || (document.getElementById('facultyLeaveTypeFilter')?.value) || 'all';
    if (!state.facultyLeaves) return;
    if (!selType || selType === 'all') {
      renderVPLeaves(state.facultyLeaves);
    } else {
      const filtered = state.facultyLeaves.filter(item => item.type.toLowerCase().includes(selType.toLowerCase()));
      renderVPLeaves(filtered);
    }
  }

