  function renderAnnualCalendar(filterQuery) {
    const tbody = document.getElementById('annualCalendarTableBody');
    if (!tbody) return;

    let items = ANNUAL_CALENDAR_DATA;

    const searchInput = document.getElementById('calendarSearchInput');
    const typeFilter = document.getElementById('calendarTypeFilter');
    const query = (filterQuery !== undefined ? filterQuery : (searchInput ? searchInput.value : '')).toLowerCase().trim();
    const cat = (typeFilter && typeFilter.value) ? typeFilter.value : 'all';

    if (query) {
      items = items.filter(i =>
        i.title.toLowerCase().includes(query) ||
        i.dates.toLowerCase().includes(query) ||
        i.category.toLowerCase().includes(query) ||
        i.cohort.toLowerCase().includes(query) ||
        i.venue.toLowerCase().includes(query)
      );
    }

    if (cat !== 'all') {
      items = items.filter(i => i.category.toLowerCase() === cat.toLowerCase());
    }

    // Update tab badge count
    const badge = document.getElementById('tabBadgeEventsCalendar');
    if (badge) badge.textContent = items.length;

    if (items.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="7" class="text-center p-4 text-muted">
            <i class="fa-solid fa-calendar-xmark text-secondary" style="font-size:2rem; margin-bottom:8px; display:block;"></i>
            No annual calendar events found matching your search criteria.
          </td>
        </tr>
      `;
      return;
    }

    tbody.innerHTML = items.map(item => {
      let statusBadge = '';
      if (item.status === 'Published') {
        statusBadge = '<span class="badge" style="background:#ecfdf5; color:#059669; border:1px solid #a7f3d0;"><i class="fa-solid fa-circle-check mr-1"></i> Published</span>';
      } else if (item.status === 'Approved') {
        statusBadge = '<span class="badge" style="background:#eff6ff; color:#2563eb; border:1px solid #bfdbfe;"><i class="fa-solid fa-stamp mr-1"></i> Approved</span>';
      } else if (item.status === 'Cancelled') {
        statusBadge = '<span class="badge" style="background:#fef2f2; color:#dc2626; border:1px solid #fecaca;"><i class="fa-solid fa-ban mr-1"></i> Cancelled</span>';
      } else {
        statusBadge = '<span class="badge" style="background:#fffbeb; color:#d97706; border:1px solid #fde68a;"><i class="fa-solid fa-clock mr-1"></i> Draft</span>';
      }

      let catBadge = '';
      if (item.category === 'Holiday') catBadge = '<span class="badge" style="background:#fef3c7; color:#92400e;">Holiday</span>';
      else if (item.category === 'Academic') catBadge = '<span class="badge" style="background:#eff6ff; color:#1e40af;">Academic</span>';
      else if (item.category === 'Examination') catBadge = '<span class="badge" style="background:#f3e8ff; color:#6b21a8;">Examination</span>';
      else catBadge = '<span class="badge" style="background:#f0fdf4; color:#166534;">Major Event</span>';

      return `
        <tr>
          <td><strong style="color:#0f172a; font-size:0.86rem;"><i class="fa-regular fa-calendar mr-1 text-primary"></i> ${item.dates}</strong></td>
          <td>
            <div style="font-weight:700; color:#1e293b; font-size:0.9rem;">${item.title}</div>
            <div style="font-size:0.75rem; color:#64748b;"><i class="fa-solid fa-user-shield mr-1"></i> Authorized: ${item.approval}</div>
          </td>
          <td>${catBadge}</td>
          <td><span style="font-size:0.83rem; color:#334155; font-weight:600;"><i class="fa-solid fa-users mr-1 text-muted"></i> ${item.cohort}</span></td>
          <td><span style="font-size:0.83rem; color:#475569;"><i class="fa-solid fa-location-dot mr-1 text-danger"></i> ${item.venue}</span></td>
          <td>${statusBadge}</td>
          <td style="text-align: right; white-space: nowrap;">
            ${item.status === 'Draft' ? `
              <button class="btn btn-outline-secondary btn-sm" onclick="portalApp.openEditCalendarEventModal('${item.id}')" title="Edit Draft" style="padding: 3px 7px;">
                <i class="fa-solid fa-pen-to-square"></i>
              </button>
              <button class="btn btn-outline-primary btn-sm" onclick="portalApp.approveCalendarEvent('${item.id}')" title="Executive Approve" style="padding: 3px 7px;">
                <i class="fa-solid fa-stamp"></i>
              </button>
            ` : ''}
            ${item.status === 'Approved' ? `
              <button class="btn btn-outline-success btn-sm" onclick="portalApp.publishCalendarEvent('${item.id}')" title="Publish to Portal" style="padding: 3px 7px;">
                <i class="fa-solid fa-globe"></i> Publish
              </button>
            ` : ''}
            ${item.status === 'Published' ? `
              <button class="btn btn-outline-primary btn-sm" onclick="portalApp.notifyCalendarAffectedUsers('${item.id}')" title="Notify Affected Students & Faculty" style="padding: 3px 7px;">
                <i class="fa-solid fa-bell"></i> Notify
              </button>
            ` : ''}
            ${item.status !== 'Cancelled' ? `
              <button class="btn btn-outline-danger btn-sm" onclick="portalApp.cancelCalendarEvent('${item.id}')" title="Cancel Event" style="padding: 3px 7px;">
                <i class="fa-solid fa-ban"></i>
              </button>
            ` : ''}
          </td>
        </tr>
      `;
    }).join('');
  }

  function filterAnnualCalendar() {
    renderAnnualCalendar();
  }

  function openCreateCalendarEventModal() {
    const form = document.getElementById('createAnnualEventForm');
    if (form) form.reset();
    openModal('createAnnualEventModal');
  }

  function handleCalendarEventSubmit(event) {
    if (event) event.preventDefault();

    const dateVal = document.getElementById('calEventDate')?.value.trim();
    const titleVal = document.getElementById('calEventTitle')?.value.trim();
    const catVal = document.getElementById('calEventCategory')?.value || 'Academic';
    const classesVal = document.getElementById('calEventClasses')?.value.trim() || 'All Classes';
    const locVal = document.getElementById('calEventLocation')?.value.trim() || 'Campus Wide';
    const statusVal = document.getElementById('calEventStatus')?.value || 'Draft';

    if (!dateVal || !titleVal) {
      showToast('Please provide valid event dates and title.', 'warning');
      return;
    }

    const newId = 'AC-' + String(ANNUAL_CALENDAR_DATA.length + 1).padStart(2, '0');
    ANNUAL_CALENDAR_DATA.unshift({
      id: newId,
      dates: dateVal,
      title: titleVal,
      category: catVal,
      cohort: classesVal,
      venue: locVal,
      status: statusVal,
      approval: statusVal === 'Published' || statusVal === 'Approved' ? 'Principal Smt. Gorle Varalakshmi' : 'Draft Entry',
      notified: false
    });

    closeModal('createAnnualEventModal');
    renderAnnualCalendar();
    showToast(`Annual calendar entry "${titleVal}" created successfully (${statusVal})!`, 'success');
  }

  function openEditCalendarEventModal(id) {
    const item = ANNUAL_CALENDAR_DATA.find(i => i.id === id);
    if (!item) return;

    const idInput = document.getElementById('editCalEventId');
    const dateInput = document.getElementById('editCalEventDate');
    const titleInput = document.getElementById('editCalEventTitle');
    const catInput = document.getElementById('editCalEventCategory');
    const classInput = document.getElementById('editCalEventClasses');
    const locInput = document.getElementById('editCalEventLocation');
    const statusInput = document.getElementById('editCalEventStatus');

    if (idInput) idInput.value = item.id;
    if (dateInput) dateInput.value = item.dates;
    if (titleInput) titleInput.value = item.title;
    if (catInput) catInput.value = item.category;
    if (classInput) classInput.value = item.cohort;
    if (locInput) locInput.value = item.venue;
    if (statusInput) statusInput.value = item.status;

    openModal('editAnnualEventModal');
  }

  function handleEditCalendarEventSubmit(event) {
    if (event) event.preventDefault();

    const id = document.getElementById('editCalEventId')?.value;
    const item = ANNUAL_CALENDAR_DATA.find(i => i.id === id);
    if (!item) return;

    item.dates = document.getElementById('editCalEventDate')?.value.trim() || item.dates;
    item.title = document.getElementById('editCalEventTitle')?.value.trim() || item.title;
    item.category = document.getElementById('editCalEventCategory')?.value || item.category;
    item.cohort = document.getElementById('editCalEventClasses')?.value.trim() || item.cohort;
    item.venue = document.getElementById('editCalEventLocation')?.value.trim() || item.venue;
    item.status = document.getElementById('editCalEventStatus')?.value || item.status;

    closeModal('editAnnualEventModal');
    renderAnnualCalendar();
    showToast(`Calendar event "${item.title}" updated successfully!`, 'success');
  }

  function approveCalendarEvent(id) {
    const item = ANNUAL_CALENDAR_DATA.find(i => i.id === id);
    if (!item) return;

    item.status = 'Approved';
    item.approval = 'Principal Smt. Gorle Varalakshmi & Vice Principal Sri Navva Anand';
    renderAnnualCalendar();
    showToast(`Calendar event "${item.title}" formally approved by Principal!`, 'success');
  }

  function publishCalendarEvent(id) {
    const item = ANNUAL_CALENDAR_DATA.find(i => i.id === id);
    if (!item) return;

    item.status = 'Published';
    renderAnnualCalendar();
    showToast(`Calendar event "${item.title}" is now published on the public portal!`, 'success');
  }

  function cancelCalendarEvent(id) {
    const item = ANNUAL_CALENDAR_DATA.find(i => i.id === id);
    if (!item) return;

    const reason = prompt(`Cancel event "${item.title}". Enter official institutional reason:`, 'Academic schedule adjustment per DEO instructions');
    if (reason === null) return;

    item.status = 'Cancelled';
    item.title += ` (Cancelled: ${reason})`;
    renderAnnualCalendar();
    showToast(`Calendar event "${item.id}" marked as Cancelled.`, 'info');
  }

  function notifyCalendarAffectedUsers(id) {
    const item = ANNUAL_CALENDAR_DATA.find(i => i.id === id);
    if (!item) return;

    item.notified = true;
    showToast(`Official circular dispatched for "${item.title}" to cohort ${item.cohort} via SMS & Portal Notification!`, 'success');
  }

  function exportCalendarPDF() {
    showToast('Generating official AP Board academic calendar PDF document...', 'info');
    setTimeout(() => {
      showToast('Official School Annual Calendar downloaded successfully!', 'success');
    }, 800);
  }

  function exportCalendarICS() {
    showToast('Exporting calendar (.ics) for Google Calendar & Outlook integration...', 'info');
    setTimeout(() => {
      showToast('Calendar (.ics) sync feed downloaded successfully!', 'success');
    }, 800);
  }

