  function openCreateSchoolEventModal() {
    const form = document.getElementById('createSchoolEventForm');
    if (form) form.reset();
    openModal('createSchoolEventModal');
  }

  function handleSchoolEventSubmit(event) {
    if (event) event.preventDefault();

    const name = document.getElementById('eventM13Name')?.value.trim();
    const desc = document.getElementById('eventM13Desc')?.value.trim();
    const organizer = document.getElementById('eventM13Organizer')?.value.trim();
    const coordinator = document.getElementById('eventM13Coordinator')?.value.trim() || 'Assigned by Committee';
    const dateTime = document.getElementById('eventM13DateTime')?.value.trim();
    const venue = document.getElementById('eventM13Venue')?.value.trim();
    const participants = document.getElementById('eventM13Participants')?.value.trim();
    const budget = document.getElementById('eventM13Budget')?.value.trim();
    const permissions = document.getElementById('eventM13Permissions')?.value.trim();
    const safety = document.getElementById('eventM13Safety')?.value.trim();
    const status = document.getElementById('eventM13Status')?.value || 'Draft';

    if (!name || !dateTime || !venue) {
      showToast('Please fill in all mandatory event fields.', 'warning');
      return;
    }

    const newId = 'SE-' + String(SCHOOL_EVENTS_DATA.length + 1).padStart(2, '0');
    SCHOOL_EVENTS_DATA.unshift({
      id: newId,
      name,
      description: desc,
      organizer,
      coordinator,
      dateTime,
      venue,
      expectedParticipants: participants,
      budget,
      requiredPermissions: permissions,
      safetyArrangements: safety,
      status,
      actualAttendance: 0,
      reportStatus: 'Pending',
      actualBudget: 'Pending'
    });

    closeModal('createSchoolEventModal');
    renderSchoolEventsTable();
    showToast(`School Event "${name}" registered successfully!`, 'success');
  }

  function assignEventCoordinator(id) {
    const ev = SCHOOL_EVENTS_DATA.find(e => e.id === id);
    if (!ev) return;

    const newCoord = prompt(`Assign / Change Designated Coordinator for "${ev.name}":`, ev.coordinator || 'Sri Navva Anand (Vice Principal)');
    if (newCoord === null) return;

    ev.coordinator = newCoord.trim();
    renderSchoolEventsTable();
    showToast(`Coordinator for "${ev.name}" updated to: ${ev.coordinator}`, 'success');
  }

  function requestEventApproval(id) {
    const ev = SCHOOL_EVENTS_DATA.find(e => e.id === id);
    if (!ev) return;

    ev.status = 'Approved';
    renderSchoolEventsTable();
    showToast(`Event "${ev.name}" sanctioned and approved by Principal Smt. Gorle Varalakshmi!`, 'success');
  }

  function reserveEventVenue(id) {
    const ev = SCHOOL_EVENTS_DATA.find(e => e.id === id);
    if (!ev) return;

    ev.status = 'Venue Reserved';
    renderSchoolEventsTable();
    showToast(`Venue "${ev.venue}" reserved and blocked in institutional calendar for "${ev.name}"!`, 'success');
  }

  function publishSchoolEvent(id) {
    const ev = SCHOOL_EVENTS_DATA.find(e => e.id === id);
    if (!ev) return;

    ev.status = 'Published';
    renderSchoolEventsTable();
    showToast(`Event "${ev.name}" published to school public board and parent app!`, 'success');
  }

  function openRecordEventAttendanceModal(id) {
    const ev = SCHOOL_EVENTS_DATA.find(e => e.id === id);
    if (!ev) return;

    const idInput = document.getElementById('eventAttId');
    const nameEl = document.getElementById('eventAttNameDisplay');
    const schedEl = document.getElementById('eventAttScheduleDisplay');
    const expInput = document.getElementById('eventAttExpected');
    const actInput = document.getElementById('eventAttActual');
    const supInput = document.getElementById('eventAttSupervisors');

    if (idInput) idInput.value = ev.id;
    if (nameEl) nameEl.textContent = ev.name;
    if (schedEl) schedEl.textContent = `${ev.dateTime} • Venue: ${ev.venue}`;
    if (expInput) expInput.value = ev.expectedParticipants;
    if (actInput) actInput.value = ev.actualAttendance || '';
    if (supInput) supInput.value = ev.coordinator || 'Sri Navva Anand & Supervising Faculty';

    openModal('recordEventAttendanceModal');
  }

  function handleRecordEventAttendanceSubmit(event) {
    if (event) event.preventDefault();

    const id = document.getElementById('eventAttId')?.value;
    const ev = SCHOOL_EVENTS_DATA.find(e => e.id === id);
    if (!ev) return;

    const actual = parseInt(document.getElementById('eventAttActual')?.value || '0', 10);
    const supervisors = document.getElementById('eventAttSupervisors')?.value.trim();

    ev.actualAttendance = actual;
    if (supervisors) ev.coordinator = supervisors;

    closeModal('recordEventAttendanceModal');
    renderSchoolEventsTable();
    showToast(`Verified attendance of ${actual} participants logged for "${ev.name}".`, 'success');
  }

  function openCompleteEventReportModal(id) {
    const ev = SCHOOL_EVENTS_DATA.find(e => e.id === id);
    if (!ev) return;

    const idInput = document.getElementById('eventReportId');
    const nameEl = document.getElementById('eventReportNameDisplay');
    const budEl = document.getElementById('eventReportBudgetDisplay');
    const actBudInput = document.getElementById('eventReportActualBudget');

    if (idInput) idInput.value = ev.id;
    if (nameEl) nameEl.textContent = ev.name;
    if (budEl) budEl.textContent = `Sanctioned Allocation: ${ev.budget} • Headcount: ${ev.actualAttendance || ev.expectedParticipants}`;
    if (actBudInput) actBudInput.value = ev.actualBudget !== 'Pending' ? ev.actualBudget : ev.budget;

    openModal('completeEventReportModal');
  }

  function handleCompleteEventReportSubmit(event) {
    if (event) event.preventDefault();

    const id = document.getElementById('eventReportId')?.value;
    const ev = SCHOOL_EVENTS_DATA.find(e => e.id === id);
    if (!ev) return;

    const actualBudget = document.getElementById('eventReportActualBudget')?.value.trim();
    const outcome = document.getElementById('eventReportOutcome')?.value;

    ev.actualBudget = actualBudget || ev.budget;
    ev.status = 'Completed';
    ev.reportStatus = 'Completed';

    closeModal('completeEventReportModal');
    renderSchoolEventsTable();
    showToast(`Official post-event report for "${ev.name}" archived with status: ${outcome}!`, 'success');
  }

  // =========================================================================
  // 13.3 COMPETITIONS CONTROLLERS
  // =========================================================================

  function renderCompetitionsTable(filterQuery) {
    const tbody = document.getElementById('competitionsTableBody');
    if (!tbody) return;

    let items = COMPETITIONS_DATA;

    const searchInput = document.getElementById('competitionsSearchInput');
    const classFilter = document.getElementById('competitionsClassFilter');
    const query = (filterQuery !== undefined ? filterQuery : (searchInput ? searchInput.value : '')).toLowerCase().trim();
    const cl = (classFilter && classFilter.value) ? classFilter.value : 'all';

    if (query) {
      items = items.filter(c =>
        c.competition.toLowerCase().includes(query) ||
        c.eligibleClasses.toLowerCase().includes(query) ||
        c.coordinator.toLowerCase().includes(query) ||
        c.results.toLowerCase().includes(query)
      );
    }

    if (cl !== 'all') {
      items = items.filter(c => c.eligibleClasses.toLowerCase().includes(cl.toLowerCase()));
    }

    // Update tab badge count
    const badge = document.getElementById('tabBadgeEventsCompetitions');
    if (badge) badge.textContent = items.length;

    if (items.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="7" class="text-center p-4 text-muted">
            <i class="fa-solid fa-trophy text-secondary" style="font-size:2rem; margin-bottom:8px; display:block;"></i>
            No competitive fixtures found matching your search.
          </td>
        </tr>
      `;
      return;
    }

    tbody.innerHTML = items.map(c => {
      let certBadge = '';
      if (c.certificates.includes('Ready') || c.certificates.includes('Generated')) {
        certBadge = `<button class="btn btn-outline-warning btn-sm" onclick="portalApp.generateCompetitionCertificates('${c.id}')" title="Print Certificate" style="padding: 2px 7px; font-size: 0.76rem;">
          <i class="fa-solid fa-certificate text-warning mr-1"></i> Issue Certs
        </button>`;
      } else {
        certBadge = '<span class="text-xs text-muted"><i class="fa-regular fa-clock mr-1"></i> Awaiting Results</span>';
      }

      return `
        <tr>
          <td>
            <div style="font-weight:700; color:#0f172a; font-size:0.9rem;"><i class="fa-solid fa-trophy text-warning mr-1"></i> ${c.competition}</div>
          </td>
          <td><span class="badge" style="background:#eff6ff; color:#1e40af; font-size:0.8rem;">${c.eligibleClasses}</span></td>
          <td>
            <div style="font-size:0.82rem; font-weight:700; color:#dc2626;"><i class="fa-regular fa-calendar-xmark mr-1"></i> ${c.deadline}</div>
            <div style="font-size:0.75rem; color:#64748b;"><i class="fa-solid fa-user-tie mr-1"></i> ${c.coordinator}</div>
          </td>
          <td>
            <button class="btn btn-outline-primary btn-sm" onclick="portalApp.openRegisterCompParticipantsModal('${c.id}')" style="padding: 2px 8px; font-size:0.78rem;">
              <i class="fa-solid fa-users mr-1"></i> ${c.participants} Enrolled
            </button>
          </td>
          <td>
            <div style="font-size:0.82rem; color:#334155; line-height:1.4;">${c.results}</div>
          </td>
          <td>${certBadge}</td>
          <td style="text-align: right; white-space: nowrap;">
            <button class="btn btn-outline-primary btn-sm" onclick="portalApp.openRegisterCompParticipantsModal('${c.id}')" title="Register Candidate" style="padding: 3px 7px;">
              <i class="fa-solid fa-user-plus"></i>
            </button>
            <button class="btn btn-outline-warning btn-sm" onclick="portalApp.openRecordCompResultsModal('${c.id}')" title="Record Results" style="padding: 3px 7px;">
              <i class="fa-solid fa-medal"></i>
            </button>
            ${c.resultStatus === 'Draft' ? `
              <button class="btn btn-outline-success btn-sm" onclick="portalApp.approveCompResults('${c.id}')" title="Approve Standings" style="padding: 3px 7px;">
                <i class="fa-solid fa-check"></i>
              </button>
            ` : ''}
          </td>
        </tr>
      `;
    }).join('');
  }

  function filterCompetitions() {
    renderCompetitionsTable();
  }

  function openCreateCompetitionModal() {
    const form = document.getElementById('createCompetitionForm');
    if (form) form.reset();
    openModal('createCompetitionModal');
  }

  function handleCompetitionSubmit(event) {
    if (event) event.preventDefault();

    const name = document.getElementById('compM13Name')?.value.trim();
    const classes = document.getElementById('compM13Classes')?.value.trim();
    const deadline = document.getElementById('compM13Deadline')?.value.trim();
    const coordinator = document.getElementById('compM13Coordinator')?.value.trim();

    if (!name || !deadline) {
      showToast('Please enter competition name and registration deadline.', 'warning');
      return;
    }

    const newId = 'CMP-' + String(COMPETITIONS_DATA.length + 1).padStart(2, '0');
    COMPETITIONS_DATA.unshift({
      id: newId,
      competition: name,
      eligibleClasses: classes || 'Classes VI - X',
      deadline,
      participants: 0,
      participantList: [],
      coordinator: coordinator || 'Sri Navva Anand (VP)',
      results: 'Registration open. Awaiting tournament heats.',
      resultStatus: 'Draft',
      certificates: 'Pending Results'
    });

    closeModal('createCompetitionModal');
    renderCompetitionsTable();
    showToast(`Competition "${name}" created successfully!`, 'success');
  }

  function openRegisterCompParticipantsModal(id) {
    const targetId = id || (COMPETITIONS_DATA[0] && COMPETITIONS_DATA[0].id);
    const comp = COMPETITIONS_DATA.find(c => c.id === targetId);
    if (!comp) return;

    const idInput = document.getElementById('compRegId');
    const nameEl = document.getElementById('compRegNameDisplay');
    const deadEl = document.getElementById('compRegDeadlineDisplay');
    const classInput = document.getElementById('compRegClass');

    if (idInput) idInput.value = comp.id;
    if (nameEl) nameEl.textContent = comp.competition;
    if (deadEl) deadEl.textContent = `Registration Deadline: ${comp.deadline} • Coordinator: ${comp.coordinator}`;
    if (classInput) classInput.value = comp.eligibleClasses;

    openModal('registerCompParticipantsModal');
  }

  function handleRegisterCompParticipantsSubmit(event) {
    if (event) event.preventDefault();

    const id = document.getElementById('compRegId')?.value;
    const comp = COMPETITIONS_DATA.find(c => c.id === id);
    if (!comp) return;

    const student = document.getElementById('compRegStudent')?.value.trim();
    if (!student) return;

    comp.participants += 1;
    if (!comp.participantList) comp.participantList = [];
    comp.participantList.push(student);

    closeModal('registerCompParticipantsModal');
    renderCompetitionsTable();
    showToast(`Student ${student} successfully registered for "${comp.competition}"!`, 'success');
  }

  function openRecordCompResultsModal(id) {
    const comp = COMPETITIONS_DATA.find(c => c.id === id);
    if (!comp) return;

    const idInput = document.getElementById('compResultsId');
    const nameEl = document.getElementById('compResultsNameDisplay');

    if (idInput) idInput.value = comp.id;
    if (nameEl) nameEl.textContent = comp.competition;

    openModal('recordCompResultsModal');
  }

  function handleRecordCompResultsSubmit(event) {
    if (event) event.preventDefault();

    const id = document.getElementById('compResultsId')?.value;
    const comp = COMPETITIONS_DATA.find(c => c.id === id);
    if (!comp) return;

    const w1 = document.getElementById('compWinner1')?.value.trim();
    const w2 = document.getElementById('compWinner2')?.value.trim();
    const w3 = document.getElementById('compWinner3')?.value.trim();

    let res = `1st: ${w1}`;
    if (w2) res += ` • 2nd: ${w2}`;
    if (w3) res += ` • 3rd: ${w3}`;

    comp.results = res;
    comp.resultStatus = 'Approved';
    comp.certificates = 'Generated & Ready for Distribution';

    closeModal('recordCompResultsModal');
    renderCompetitionsTable();
    showToast(`Competition standings saved and certificates unlocked for "${comp.competition}"!`, 'success');
  }

  function approveCompResults(id) {
    const comp = COMPETITIONS_DATA.find(c => c.id === id);
    if (!comp) return;

    comp.resultStatus = 'Approved';
    comp.certificates = 'Generated & Ready for Distribution';
    renderCompetitionsTable();
    showToast(`Jury results for "${comp.competition}" approved by Principal Smt. Gorle Varalakshmi!`, 'success');
  }

  function generateCompetitionCertificates(id) {
    const comp = COMPETITIONS_DATA.find(c => c.id === id);
    if (!comp) return;

    const titleEl = document.getElementById('certCompTitle');
    const studentEl = document.getElementById('certStudentName');

    if (titleEl) titleEl.textContent = comp.competition;
    if (studentEl && comp.participantList && comp.participantList.length > 0) {
      studentEl.textContent = comp.participantList[0];
    }

    openModal('generateCertificatesModal');
  }

