  function renderClubsSportsTable(filterQuery) {
    const tbody = document.getElementById('clubsSportsTableBody');
    if (!tbody) return;

    let items = CLUBS_SPORTS_DATA;

    const searchInput = document.getElementById('clubsSearchInput');
    const typeFilter = document.getElementById('clubsTypeFilter');
    const query = (filterQuery !== undefined ? filterQuery : (searchInput ? searchInput.value : '')).toLowerCase().trim();
    const tf = (typeFilter && typeFilter.value) ? typeFilter.value : 'all';

    if (query) {
      items = items.filter(c =>
        c.club.toLowerCase().includes(query) ||
        c.coordinator.toLowerCase().includes(query) ||
        c.activities.toLowerCase().includes(query) ||
        c.achievements.toLowerCase().includes(query) ||
        c.venue.toLowerCase().includes(query)
      );
    }

    if (tf !== 'all') {
      items = items.filter(c => c.club.toLowerCase().includes(tf.toLowerCase()));
    }

    // Update tab badge count
    const badge = document.getElementById('tabBadgeEventsClubs');
    if (badge) badge.textContent = items.length;

    if (items.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="8" class="text-center p-4 text-muted">
            <i class="fa-solid fa-person-running text-secondary" style="font-size:2rem; margin-bottom:8px; display:block;"></i>
            No clubs or sports teams found.
          </td>
        </tr>
      `;
      return;
    }

    tbody.innerHTML = items.map(cl => {
      return `
        <tr>
          <td>
            <div style="font-weight:700; color:#0f172a; font-size:0.9rem;"><i class="fa-solid fa-people-group text-primary mr-1"></i> ${cl.club}</div>
          </td>
          <td>
            <div style="font-weight:600; color:#1e293b; font-size:0.83rem;"><i class="fa-solid fa-user-tie text-muted mr-1"></i> ${cl.coordinator}</div>
          </td>
          <td>
            <button class="btn btn-outline-primary btn-sm" onclick="portalApp.openEnrolClubStudentsModal('${cl.id}')" style="padding: 2px 7px; font-size:0.78rem;">
              <i class="fa-solid fa-users mr-1"></i> ${cl.members}
            </button>
          </td>
          <td>
            <div style="font-size:0.82rem; font-weight:600; color:#334155;"><i class="fa-regular fa-clock text-primary mr-1"></i> ${cl.schedule}</div>
            <div style="font-size:0.75rem; color:#64748b;"><i class="fa-solid fa-location-dot text-danger mr-1"></i> ${cl.venue}</div>
          </td>
          <td>
            <span class="badge" style="background:#ecfdf5; color:#059669; border:1px solid #a7f3d0;"><i class="fa-solid fa-chart-line mr-1"></i> ${cl.attendance}</span>
          </td>
          <td>
            <div style="font-size:0.78rem; color:#475569; line-height:1.4;">${cl.activities}</div>
          </td>
          <td>
            <div style="font-size:0.78rem; font-weight:700; color:#b45309; line-height:1.4;"><i class="fa-solid fa-award mr-1"></i> ${cl.achievements}</div>
          </td>
          <td style="text-align: right; white-space: nowrap;">
            <button class="btn btn-outline-primary btn-sm" onclick="portalApp.openEnrolClubStudentsModal('${cl.id}')" title="Enrol Student" style="padding: 3px 7px;">
              <i class="fa-solid fa-user-plus"></i>
            </button>
            <button class="btn btn-outline-secondary btn-sm" onclick="portalApp.assignClubCoordinator('${cl.id}')" title="Assign Coordinator" style="padding: 3px 7px;">
              <i class="fa-solid fa-user-gear"></i>
            </button>
            <button class="btn btn-outline-success btn-sm" onclick="portalApp.openRecordClubParticipationModal('${cl.id}')" title="Record Participation" style="padding: 3px 7px;">
              <i class="fa-solid fa-stopwatch-20"></i>
            </button>
            <button class="btn btn-outline-warning btn-sm" onclick="portalApp.openPublishClubAchievementModal('${cl.id}')" title="Publish Achievement" style="padding: 3px 7px;">
              <i class="fa-solid fa-bullhorn"></i>
            </button>
          </td>
        </tr>
      `;
    }).join('');
  }

