  function handleClubSubmit(event) {
    if (event) event.preventDefault();

    const name = document.getElementById('clubM13Name')?.value.trim();
    const coordinator = document.getElementById('clubM13Coordinator')?.value.trim();
    const schedule = document.getElementById('clubM13Schedule')?.value.trim();
    const venue = document.getElementById('clubM13Venue')?.value.trim();
    const activities = document.getElementById('clubM13Activities')?.value.trim();
    const achievements = document.getElementById('clubM13Achievements')?.value.trim() || 'New squad formed for 2026-27';

    if (!name || !coordinator) {
      showToast('Please fill in club name and designated coordinator.', 'warning');
      return;
    }

    const newId = 'CS-' + String(CLUBS_SPORTS_DATA.length + 1).padStart(2, '0');
    CLUBS_SPORTS_DATA.unshift({
      id: newId,
      club: name,
      coordinator,
      members: 0,
      memberList: [],
      schedule: schedule || 'Weekly Practice Sessions',
      venue: venue || 'Campus Grounds',
      attendance: '100% (New Club)',
      activities: activities || 'Fundamental skill drills and curriculum',
      achievements
    });

    closeModal('createClubModal');
    renderClubsSportsTable();
    showToast(`Club / Sports Squad "${name}" registered successfully!`, 'success');
  }

  function assignClubCoordinator(id) {
    const cl = CLUBS_SPORTS_DATA.find(c => c.id === id);
    if (!cl) return;

    const newCoord = prompt(`Designate Master Coach / Coordinator for "${cl.club}":`, cl.coordinator);
    if (newCoord === null) return;

    cl.coordinator = newCoord.trim();
    renderClubsSportsTable();
    showToast(`Coordinator for "${cl.club}" updated to: ${cl.coordinator}`, 'success');
  }

  function openEnrolClubStudentsModal(id) {
    const cl = CLUBS_SPORTS_DATA.find(c => c.id === id);
    if (!cl) return;

    const idInput = document.getElementById('clubEnrolId');
    const nameEl = document.getElementById('clubEnrolNameDisplay');
    const schedEl = document.getElementById('clubEnrolScheduleDisplay');

    if (idInput) idInput.value = cl.id;
    if (nameEl) nameEl.textContent = cl.club;
    if (schedEl) schedEl.textContent = `${cl.schedule} • Venue: ${cl.venue}`;

    openModal('enrolClubStudentsModal');
  }

  function handleEnrolClubStudentsSubmit(event) {
    if (event) event.preventDefault();

    const id = document.getElementById('clubEnrolId')?.value;
    const cl = CLUBS_SPORTS_DATA.find(c => c.id === id);
    if (!cl) return;

    const student = document.getElementById('clubEnrolStudent')?.value.trim();
    const role = document.getElementById('clubEnrolRole')?.value || 'Cadet Member';

    if (!student) return;

    cl.members += 1;
    if (!cl.memberList) cl.memberList = [];
    cl.memberList.push(`${student} (${role})`);

    closeModal('enrolClubStudentsModal');
    renderClubsSportsTable();
    showToast(`Enrolled ${student} into "${cl.club}" as ${role}!`, 'success');
  }

