  function renderTransportRoutesTable() {
    const tbody = document.getElementById('transportRoutesTableBody');
    if (!tbody) return;
    const typeFilter = (document.getElementById('transportRouteTypeFilter')?.value) || 'all';
    const q = (document.getElementById('transportRouteSearchInput')?.value || '').toLowerCase().trim();

    let list = TRANSPORT_ROUTES_DATA.filter(r => {
      const matchType = typeFilter === 'all' || 
        r.vehicleType.toLowerCase().includes(typeFilter.toLowerCase()) || 
        (r.status && r.status.toLowerCase() === typeFilter.toLowerCase());
      const matchQ = !q || 
        r.routeNo.toLowerCase().includes(q) || 
        r.routeName.toLowerCase().includes(q) ||
        r.driverName.toLowerCase().includes(q) || 
        (r.vehicleReg && r.vehicleReg.toLowerCase().includes(q)) ||
        (r.busNo && r.busNo.toLowerCase().includes(q)) ||
        r.stops.some(s => s.name.toLowerCase().includes(q));
      return matchType && matchQ;
    });

    if (list.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" class="text-center py-4 text-muted"><i class="fa-solid fa-route fa-2x mb-2 d-block"></i>No transport routes match the selected criteria.</td></tr>';
      return;
    }

    tbody.innerHTML = list.map(r => {
      const stopsHtml = r.stops.map((s, idx) => {
        const isEnd = idx === r.stops.length - 1;
        return '<span class="portal-badge badge-neutral" style="font-size: 0.72rem; margin: 1px 2px;" title="' + s.time + ' (' + s.students + ' Commuters)">' +
          (isEnd ? '<i class="fa-solid fa-school text-primary"></i> ' : '<i class="fa-solid fa-location-pin text-amber"></i> ') +
          s.name + ' <small class="text-muted">(' + s.time + ')</small></span>';
      }).join(' ');

      const statusBadge = (r.status === 'Draft') 
        ? '<span class="portal-badge badge-neutral"><i class="fa-solid fa-file-pen mr-1"></i>Draft</span>'
        : (r.status === 'Modified')
        ? '<span class="portal-badge badge-warning"><i class="fa-solid fa-clock-rotate-left mr-1"></i>Modified</span>'
        : '<span class="portal-badge badge-success"><i class="fa-solid fa-circle-check mr-1"></i>' + (r.status || 'Active') + '</span>';

      const pct = Math.min(100, Math.round(((r.assignedStudents || 0) / (r.capacity || 32)) * 100));

      return `
        <tr>
          <td><span class="portal-badge badge-primary font-monospace" style="font-weight:700;">${r.routeNo}</span></td>
          <td>
            <div style="font-weight: 700; color: #1e3a8a;">${r.routeName}</div>
            <div class="text-muted" style="font-size: 0.75rem;"><i class="fa-solid fa-road mr-1"></i>${r.tripDuration || '45 Mins (14.2 km)'}</div>
          </td>
          <td style="max-width: 260px;">${stopsHtml}</td>
          <td>
            <div style="font-size: 0.78rem; font-weight: 600;"><i class="fa-solid fa-sun text-warning mr-1"></i>${r.timingMorning || '07:30 AM - 08:15 AM'}</div>
            <div style="font-size: 0.75rem; color: #64748b;"><i class="fa-solid fa-moon text-indigo mr-1"></i>${r.timingEvening || '04:30 PM - 05:15 PM'}</div>
          </td>
          <td>
            <div style="font-weight: 600;">${r.busNo}</div>
            <div class="text-muted" style="font-size: 0.75rem; font-family: monospace;">${r.vehicleReg}</div>
          </td>
          <td>
            <div style="font-size: 0.8rem; font-weight: 600;"><i class="fa-solid fa-id-badge text-primary mr-1"></i>${r.driverName}</div>
            <div style="font-size: 0.75rem; color: #475569;"><i class="fa-solid fa-user-shield text-success mr-1"></i>${r.attendantName || 'Smt. K. Hymavathi'}</div>
          </td>
          <td>
            <div style="display:flex; align-items:center; gap: 4px; font-size: 0.82rem;">
              <strong>${r.assignedStudents || 0}</strong>
              <span class="text-muted">/</span>
              <span class="text-muted">${r.capacity || 32}</span>
              <span class="text-muted" style="font-size:0.75rem;">(${pct}%)</span>
            </div>
            <div style="background:#e2e8f0; border-radius:4px; height:4px; width:70px; margin-top:3px; overflow:hidden;">
              <div style="background:#2563eb; height:100%; width:${pct}%;"></div>
            </div>
          </td>
          <td>${statusBadge}</td>
          <td style="text-align: right; white-space: nowrap;">
            <div style="display: inline-flex; gap: 4px;">
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Add or edit stops" onclick="portalApp.openEditRouteStopsModal('${r.routeNo}')">
                <i class="fa-solid fa-signs-post"></i> Stops
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Assign vehicle" onclick="portalApp.assignRouteVehicle('${r.routeNo}')">
                <i class="fa-solid fa-bus"></i> Vehicle
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Allocate students" onclick="portalApp.allocateRouteStudents('${r.routeNo}')">
                <i class="fa-solid fa-users"></i> Allocate
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Publish route" onclick="portalApp.publishTransportRoute('${r.routeNo}')">
                <i class="fa-solid fa-bullhorn text-success"></i> Publish
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Record route changes" onclick="portalApp.recordRouteChange('${r.routeNo}')">
                <i class="fa-solid fa-file-pen"></i> Log
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="View itinerary dossier" onclick="portalApp.openTransportDossierModal('${r.routeNo}', 'route')">
                <i class="fa-solid fa-eye text-primary"></i>
              </button>
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

  function filterTransportRoutes() {
    renderTransportRoutesTable();
  }

  function openCreateTransportRouteModal() {
    const form = document.getElementById('createTransportRouteForm');
    if (form) form.reset();
    const nextNum = TRANSPORT_ROUTES_DATA.length + 1;
    const idInput = document.getElementById('routeM14Id');
    if (idInput) idInput.value = 'Route ' + nextNum;
    openModal('createTransportRouteModal');
  }

  function handleCreateTransportRouteSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const routeId = document.getElementById('routeM14Id')?.value || ('Route ' + (TRANSPORT_ROUTES_DATA.length + 1));
    const routeName = document.getElementById('routeM14Name')?.value || 'New Transit Arterial Line';
    const stopsRaw = document.getElementById('routeM14Stops')?.value || 'Campus Gate (08:15 AM)';
    const pickup = document.getElementById('routeM14Pickup')?.value || '07:30 AM - 08:15 AM';
    const drop = document.getElementById('routeM14Drop')?.value || '04:30 PM - 05:15 PM';
    const vehicle = document.getElementById('routeM14Vehicle')?.value || 'Bus #1 (AP-07-TX-1041)';
    const status = document.getElementById('routeM14Status')?.value || 'Active';
    const driver = document.getElementById('routeM14Driver')?.value || 'Sri K. Venkateswarlu';
    const attendant = document.getElementById('routeM14Attendant')?.value || 'Smt. K. Hymavathi';

    const parsedStops = stopsRaw.split(',').map(s => {
      const trimmed = s.trim();
      const timeMatch = trimmed.match(/\((.*?)\)/);
      const name = trimmed.replace(/\(.*?\)/, '').trim();
      return {
        name: name || trimmed,
        time: timeMatch ? timeMatch[1] : '07:45 AM',
        students: 5
      };
    });

    const newRoute = {
      routeNo: routeId,
      routeName: routeName,
      vehicleType: 'School Bus (32-Seater)',
      busNo: vehicle.split(' ')[0] || 'Bus',
      vehicleReg: (vehicle.match(/\((.*?)\)/) || [])[1] || 'AP-07-TX-1041',
      driverName: driver,
      driverPhone: '94401 12233',
      attendantName: attendant,
      stops: parsedStops.length > 0 ? parsedStops : [{ name: 'Campus Gate', time: '08:15 AM', students: 0 }],
      timingMorning: pickup,
      timingEvening: drop,
      tripDuration: '45 Mins (15.0 km)',
      assignedStudents: parsedStops.reduce((acc, x) => acc + (x.students || 0), 0),
      capacity: 32,
      status: status,
      gpsStatus: 'Live GPS: On Schedule',
      gpsCoords: '16.3067° N, 80.4365° E',
      statusClass: 'badge-success'
    };

    TRANSPORT_ROUTES_DATA.push(newRoute);
    closeModal('createTransportRouteModal');
    renderTransportRoutesTable();
    showToast('Transit Route Created', routeId + ': ' + routeName + ' has been registered under MVD safety compliance.', 'success');
  }

  function openEditRouteStopsModal(routeNo) {
    const route = TRANSPORT_ROUTES_DATA.find(r => r.routeNo === routeNo) || TRANSPORT_ROUTES_DATA[0];
    if (!route) return;

    const idInput = document.getElementById('editRouteStopsId');
    if (idInput) idInput.value = route.routeNo;
    const nameDisp = document.getElementById('editRouteStopsNameDisplay');
    if (nameDisp) nameDisp.textContent = route.routeNo + ' - ' + route.routeName;
    const vehDisp = document.getElementById('editRouteStopsVehicleDisplay');
    if (vehDisp) vehDisp.textContent = route.busNo + ' (' + route.vehicleReg + ') • Driver: ' + route.driverName;

    const stopsContent = document.getElementById('editRouteStopsContent');
    if (stopsContent) {
      stopsContent.value = route.stops.map(s => s.name + ' (' + s.time + ' - ' + s.students + ' Students)').join('\n');
    }
    const reasonInput = document.getElementById('editRouteStopsReason');
    if (reasonInput) reasonInput.value = '';

    openModal('editRouteStopsModal');
  }

  function handleEditRouteStopsSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const routeNo = document.getElementById('editRouteStopsId')?.value;
    const content = document.getElementById('editRouteStopsContent')?.value || '';
    const reason = document.getElementById('editRouteStopsReason')?.value || 'Roster alignment';

    const route = TRANSPORT_ROUTES_DATA.find(r => r.routeNo === routeNo);
    if (route) {
      const lines = content.split('\n').filter(l => l.trim().length > 0);
      if (lines.length > 0) {
        route.stops = lines.map(line => {
          const timeMatch = line.match(/\((.*?)\)/);
          const timePart = timeMatch ? timeMatch[1] : '07:45 AM';
          const time = timePart.split('-')[0].trim();
          const stdMatch = timePart.match(/(\d+)\s*Students?/i);
          const students = stdMatch ? parseInt(stdMatch[1], 10) : 5;
          const name = line.replace(/\(.*?\)/, '').trim();
          return { name, time, students };
        });
        route.assignedStudents = route.stops.reduce((acc, x) => acc + x.students, 0);
      }
      route.status = 'Modified';
      showToast('Route Stops Updated', 'Updated stops for ' + routeNo + '. Change audit logged: ' + reason, 'success');
    }
    closeModal('editRouteStopsModal');
    renderTransportRoutesTable();
  }

  function assignRouteVehicle(routeNo, vehicleReg) {
    const route = TRANSPORT_ROUTES_DATA.find(r => r.routeNo === routeNo);
    if (!route) return;

    if (!vehicleReg) {
      const availableVeh = TRANSPORT_VEHICLES_DATA.find(v => v.maintenanceStatus === 'Operational') || TRANSPORT_VEHICLES_DATA[0];
      vehicleReg = availableVeh ? availableVeh.regNo : 'AP-07-TX-1041';
    }

    const veh = TRANSPORT_VEHICLES_DATA.find(v => v.regNo === vehicleReg);
    if (veh) {
      route.vehicleReg = veh.regNo;
      route.busNo = veh.fleetCode ? veh.fleetCode.replace('BUS-0', 'Bus #').replace('VAN-0', 'Van #') : 'Bus #1';
      route.capacity = parseInt(veh.capacity, 10) || route.capacity;
      veh.assignedRoute = route.routeNo + ' - ' + route.routeName;
    }

    renderTransportRoutesTable();
    renderTransportVehiclesTable();
    showToast('Vehicle Assigned', 'Assigned ' + vehicleReg + ' to ' + routeNo + ' under AP MVD transit guidelines.', 'success');
  }

  function allocateRouteStudents(routeNo) {
    const route = TRANSPORT_ROUTES_DATA.find(r => r.routeNo === routeNo);
    openAssignStudentRouteModal();
    const routeSelect = document.getElementById('allocM14Route');
    if (routeSelect && route) {
      routeSelect.value = route.routeNo;
    }
    showToast('Allocate Students', 'Select student and boarding stop to allocate commuters to ' + routeNo + '.', 'info');
  }

  function publishTransportRoute(routeNo) {
    const route = TRANSPORT_ROUTES_DATA.find(r => r.routeNo === routeNo);
    if (route) {
      route.status = 'Published';
      renderTransportRoutesTable();
      showToast('Route Published', routeNo + ' timetable published to Parent Portal, SMS Dispatch & Driver Daily Run-sheet.', 'success');
    }
  }

  function recordRouteChange(routeNo, changeNotes) {
    const route = TRANSPORT_ROUTES_DATA.find(r => r.routeNo === routeNo);
    if (route) {
      route.status = 'Modified';
      renderTransportRoutesTable();
      const note = changeNotes || 'Annual timing revision and boarding stop realignment verified by Sri P. Appa Rao.';
      showToast('Route Change Recorded', 'Modifications for ' + routeNo + ' logged in Statutory Transit Register: ' + note, 'success');
    }
  }

