  // SECTION 14.2: VEHICLES CONTROLLERS
  // =========================================================================

  function renderTransportVehiclesTable() {
    const tbody = document.getElementById('transportVehiclesTableBody');
    if (!tbody) return;
    const statusFilter = (document.getElementById('transportVehicleStatusFilter')?.value) || 'all';
    const q = (document.getElementById('transportVehicleSearchInput')?.value || '').toLowerCase().trim();

    let list = TRANSPORT_VEHICLES_DATA.filter(v => {
      const matchStatus = statusFilter === 'all' || 
        v.maintenanceStatus.toLowerCase() === statusFilter.toLowerCase();
      const matchQ = !q || 
        v.regNo.toLowerCase().includes(q) || 
        v.fleetCode.toLowerCase().includes(q) ||
        v.vehicleType.toLowerCase().includes(q) || 
        v.makeModel.toLowerCase().includes(q) ||
        v.assignedRoute.toLowerCase().includes(q) || 
        v.driverInCharge.toLowerCase().includes(q);
      return matchStatus && matchQ;
    });

    if (list.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" class="text-center py-4 text-muted"><i class="fa-solid fa-bus fa-2x mb-2 d-block"></i>No fleet vehicles match the selected criteria.</td></tr>';
      return;
    }

    tbody.innerHTML = list.map(v => {
      const statusBadge = (v.maintenanceStatus === 'Under Maintenance')
        ? '<span class="portal-badge badge-danger"><i class="fa-solid fa-wrench mr-1"></i>Under Maintenance</span>'
        : (v.maintenanceStatus === 'Service Due' || v.maintenanceStatus === 'Unavailable')
        ? '<span class="portal-badge badge-warning"><i class="fa-solid fa-triangle-exclamation mr-1"></i>' + v.maintenanceStatus + '</span>'
        : '<span class="portal-badge badge-success"><i class="fa-solid fa-circle-check mr-1"></i>' + (v.maintenanceStatus || 'Operational') + '</span>';

      return `
        <tr>
          <td>
            <span class="portal-badge badge-primary font-monospace" style="font-weight:700;">${v.regNo}</span>
            <div class="text-muted" style="font-size: 0.72rem; margin-top:2px;">${v.fleetCode || 'BUS-01'} • ${v.year || '2022'}</div>
          </td>
          <td>
            <div style="font-weight:600;">${v.vehicleType}</div>
            <div class="text-muted" style="font-size: 0.75rem;">${v.makeModel || ''}</div>
          </td>
          <td>
            <div style="font-weight:700; color:#1e3a8a;">${v.capacity}</div>
            <div class="text-muted" style="font-size: 0.72rem;">${v.allocatedCount || 0} Allocated</div>
          </td>
          <td>
            <div style="font-size: 0.8rem; font-weight:600;">${v.assignedRoute || 'Standby'}</div>
            <div class="text-muted" style="font-size: 0.72rem;"><i class="fa-solid fa-user mr-1"></i>${v.driverInCharge || 'Unassigned'}</div>
          </td>
          <td>
            <div style="font-size: 0.78rem; font-weight: 600;">${v.insuranceExpiry}</div>
            <div class="text-muted" style="font-size: 0.72rem;">${v.insuranceCompany || 'United India'}</div>
          </td>
          <td>
            <div style="font-size: 0.78rem; font-weight: 600;">${v.permitExpiry || v.fitnessExpiry || '31 Dec 2027'}</div>
            <div class="text-muted" style="font-size: 0.72rem;">AP Special Permit</div>
          </td>
          <td>
            <div style="font-size: 0.78rem; font-weight: 600;">${v.inspectionDate || v.lastServiceDate || '12 Oct 2026'}</div>
            <div class="text-success" style="font-size: 0.72rem;"><i class="fa-solid fa-certificate"></i> AMVI Cleared</div>
          </td>
          <td>${statusBadge}</td>
          <td style="text-align: right; white-space: nowrap;">
            <div style="display: inline-flex; gap: 4px;">
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Upload documents" onclick="portalApp.openUploadVehicleDocsModal('${v.regNo}')">
                <i class="fa-solid fa-upload"></i> Docs
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Assign route" onclick="portalApp.assignVehicleRoute('${v.regNo}')">
                <i class="fa-solid fa-route"></i> Route
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Record maintenance" onclick="portalApp.openRecordVehicleMaintenanceModal('${v.regNo}')">
                <i class="fa-solid fa-wrench"></i> Maintain
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Mark unavailable" onclick="portalApp.markVehicleUnavailable('${v.regNo}')">
                <i class="fa-solid fa-ban text-danger"></i>
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="View vehicle history" onclick="portalApp.viewVehicleHistory('${v.regNo}')">
                <i class="fa-solid fa-clock-rotate-left text-primary"></i>
              </button>
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

  function filterTransportVehicles() {
    renderTransportVehiclesTable();
  }

  function openAddVehicleModal() {
    const form = document.getElementById('addVehicleForm');
    if (form) form.reset();
    openModal('addVehicleModal');
  }

  function handleAddVehicleSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const reg = document.getElementById('vehM14Reg')?.value || 'AP-07-TX-9999';
    const type = document.getElementById('vehM14Type')?.value || 'School Bus';
    const cap = document.getElementById('vehM14Capacity')?.value || '32 Seats';
    const route = document.getElementById('vehM14Route')?.value || 'Route 1 - RTC Complex Line';
    const insurance = document.getElementById('vehM14Insurance')?.value || '31 Mar 2027';
    const permit = document.getElementById('vehM14Permit')?.value || '31 Dec 2027';
    const inspection = document.getElementById('vehM14Inspection')?.value || '28 Oct 2026';
    const status = document.getElementById('vehM14Status')?.value || 'Operational';

    const newVeh = {
      regNo: reg,
      fleetCode: 'BUS-0' + (TRANSPORT_VEHICLES_DATA.length + 1),
      makeModel: 'Tata Starbus Ultra (BS-VI)',
      vehicleType: type,
      year: '2023',
      capacity: cap,
      allocatedCount: 0,
      freeSeats: parseInt(cap, 10) || 32,
      occupancyPct: '0.0%',
      insuranceCompany: 'United India Insurance Co.',
      insurancePolicy: 'UIIC-2026-990000',
      insuranceExpiry: insurance,
      insuranceType: 'Comprehensive Commercial',
      insuranceStatus: 'Active',
      rtaFitnessCert: 'FC-AP07-NEW',
      fitnessExpiry: permit,
      permitExpiry: permit,
      inspectionDate: inspection,
      speedGovernorCert: 'SG-MVD-NEW (40 km/h Capped)',
      pucCert: 'PUC-2026-NEW (Valid)',
      permits: 'AP State School Transport Special Permit',
      maintenanceStatus: status,
      lastServiceDate: inspection,
      nextServiceDue: '28 Jan 2027',
      assignedRoute: route,
      driverInCharge: 'Sri K. Venkateswarlu'
    };

    TRANSPORT_VEHICLES_DATA.push(newVeh);
    closeModal('addVehicleModal');
    renderTransportVehiclesTable();
    showToast('Vehicle Added', reg + ' successfully registered into Sri Vidya institutional fleet.', 'success');
  }

  function openUploadVehicleDocsModal(regNo) {
    const v = TRANSPORT_VEHICLES_DATA.find(x => x.regNo === regNo) || TRANSPORT_VEHICLES_DATA[0];
    const idInput = document.getElementById('uploadVehRegId');
    if (idInput) idInput.value = v ? v.regNo : '';
    const disp = document.getElementById('uploadVehRegDisplay');
    if (disp) disp.textContent = v ? (v.regNo + ' (' + v.fleetCode + ') • ' + v.makeModel) : '';
    openModal('uploadVehicleDocsModal');
  }

  function handleUploadVehicleDocsSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const regNo = document.getElementById('uploadVehRegId')?.value;
    const docType = document.getElementById('uploadVehDocType')?.value || 'Insurance Certificate';
    const docRef = document.getElementById('uploadVehDocRef')?.value || 'DOC-2026-999';
    const expiry = document.getElementById('uploadVehDocExpiry')?.value || '31 Dec 2027';

    const veh = TRANSPORT_VEHICLES_DATA.find(x => x.regNo === regNo);
    if (veh) {
      if (docType.includes('Insurance')) {
        veh.insurancePolicy = docRef;
        veh.insuranceExpiry = expiry;
      } else if (docType.includes('Permit') || docType.includes('Fitness')) {
        veh.permitExpiry = expiry;
        veh.fitnessExpiry = expiry;
      } else if (docType.includes('Inspection')) {
        veh.inspectionDate = expiry;
      }
      showToast('Document Uploaded', docType + ' [' + docRef + '] verified and attached to ' + regNo + '.', 'success');
    }
    closeModal('uploadVehicleDocsModal');
    renderTransportVehiclesTable();
  }

  function assignVehicleRoute(regNo, routeNo) {
    const veh = TRANSPORT_VEHICLES_DATA.find(x => x.regNo === regNo);
    if (!veh) return;

    if (!routeNo) {
      const nextRoute = TRANSPORT_ROUTES_DATA.find(r => !r.vehicleReg || r.vehicleReg === regNo) || TRANSPORT_ROUTES_DATA[0];
      routeNo = nextRoute ? nextRoute.routeNo : 'Route 1';
    }

    veh.assignedRoute = routeNo;
    const r = TRANSPORT_ROUTES_DATA.find(x => x.routeNo === routeNo);
    if (r) {
      r.vehicleReg = veh.regNo;
      r.busNo = veh.fleetCode ? veh.fleetCode.replace('BUS-0', 'Bus #').replace('VAN-0', 'Van #') : 'Bus #1';
    }

    renderTransportVehiclesTable();
    renderTransportRoutesTable();
    showToast('Route Assigned', 'Assigned ' + veh.regNo + ' to ' + routeNo + '.', 'success');
  }

  function openRecordVehicleMaintenanceModal(regNo) {
    openReportFaultModal();
    const assetInput = document.getElementById('faultM14Asset');
    if (assetInput && regNo) {
      const veh = TRANSPORT_VEHICLES_DATA.find(v => v.regNo === regNo);
      assetInput.value = veh ? (veh.fleetCode + ' (' + veh.regNo + ')') : regNo;
    }
  }

  function markVehicleUnavailable(regNo, reason) {
    const veh = TRANSPORT_VEHICLES_DATA.find(x => x.regNo === regNo);
    if (veh) {
      veh.maintenanceStatus = 'Unavailable';
      renderTransportVehiclesTable();
      const r = reason || 'Statutory servicing and preventive overhaul';
      showToast('Vehicle Unavailable', veh.regNo + ' marked unavailable: ' + r + '. Spare fleet activated.', 'warning');
    }
  }

  function viewVehicleHistory(regNo) {
    openTransportDossierModal(regNo, 'vehicle');
  }

  // =========================================================================
  // SECTION 14.3: DRIVERS & ATTENDANTS CONTROLLERS
  // =========================================================================

  function renderTransportDriversTable() {
    const tbody = document.getElementById('transportDriversTableBody');
    if (!tbody) return;
    const roleFilter = (document.getElementById('transportDriverRoleFilter')?.value) || 'all';
    const q = (document.getElementById('transportDriverSearchInput')?.value || '').toLowerCase().trim();

    let list = TRANSPORT_DRIVERS_DATA.filter(d => {
      const matchRole = roleFilter === 'all' || 
        d.role.toLowerCase() === roleFilter.toLowerCase();
      const matchQ = !q || 
        d.name.toLowerCase().includes(q) || 
        d.id.toLowerCase().includes(q) ||
        d.licenseNo.toLowerCase().includes(q) || 
        d.assignedVehicle.toLowerCase().includes(q) ||
        d.assignedRoute.toLowerCase().includes(q);
      return matchRole && matchQ;
    });

    if (list.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" class="text-center py-4 text-muted"><i class="fa-solid fa-users-gear fa-2x mb-2 d-block"></i>No transport personnel match the selected criteria.</td></tr>';
      return;
    }

    tbody.innerHTML = list.map(d => {
      const dutyBadge = (d.dutyStatus === 'On Duty')
        ? '<span class="portal-badge badge-success"><i class="fa-solid fa-circle-check mr-1"></i>On Duty</span>'
        : (d.dutyStatus === 'Suspended')
        ? '<span class="portal-badge badge-danger"><i class="fa-solid fa-ban mr-1"></i>Suspended</span>'
        : '<span class="portal-badge badge-neutral"><i class="fa-solid fa-clock mr-1"></i>' + (d.dutyStatus || 'Standby') + '</span>';

      return `
        <tr>
          <td>
            <div style="font-weight:700; color:#1e3a8a;">${d.name}</div>
            <div class="text-muted" style="font-size: 0.72rem;">${d.id} • ${d.roleTitle}</div>
            <div class="text-muted" style="font-size: 0.72rem;"><i class="fa-solid fa-phone mr-1"></i>${d.phone}</div>
          </td>
          <td>
            <div style="font-size: 0.78rem; font-family: monospace; font-weight:600;">${d.licenseNo}</div>
            <div class="text-success" style="font-size: 0.72rem;"><i class="fa-solid fa-shield-check mr-1"></i>${d.licenseVerification || d.policeVerification}</div>
          </td>
          <td>
            <span class="portal-badge badge-neutral" style="font-size: 0.75rem;">${d.assignedVehicle || 'Unassigned'}</span>
          </td>
          <td>
            <div style="font-size: 0.8rem; font-weight:600;">${d.assignedRoute || 'Standby Pool'}</div>
            <div class="text-muted" style="font-size: 0.72rem;">${d.shift || '07:00 AM - 05:00 PM'}</div>
          </td>
          <td>${dutyBadge}</td>
          <td>
            <div style="font-size: 0.78rem; font-weight:600;">${d.documentExpiry || 'DL: 15 Aug 2028 • Med: Fit'}</div>
            <div class="text-muted" style="font-size: 0.72rem;">Annual RTA Compliance</div>
          </td>
          <td style="text-align: right; white-space: nowrap;">
            <div style="display: inline-flex; gap: 4px;">
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Assign duties" onclick="portalApp.openAssignDriverDutiesModal('${d.id}')">
                <i class="fa-solid fa-user-gear"></i> Duties
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Verify statutory documents" onclick="portalApp.verifyDriverDocuments('${d.id}')">
                <i class="fa-solid fa-certificate text-success"></i> Verify
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Record changes" onclick="portalApp.recordDriverChanges('${d.id}')">
                <i class="fa-solid fa-pen"></i> Log
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Suspend assignment" onclick="portalApp.suspendDriverAssignment('${d.id}')">
                <i class="fa-solid fa-user-slash text-danger"></i>
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="View duty history" onclick="portalApp.viewDriverDutyHistory('${d.id}')">
                <i class="fa-solid fa-history text-primary"></i>
              </button>
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

  function filterTransportDrivers() {
    renderTransportDriversTable();
  }

  function openAssignDriverDutiesModal(empId) {
    const d = (empId ? TRANSPORT_DRIVERS_DATA.find(x => x.id === empId) : null) || TRANSPORT_DRIVERS_DATA[0];
    const form = document.getElementById('assignDriverDutiesForm');
    if (form) form.reset();

    const idInput = document.getElementById('driverM14EmpId');
    if (idInput) idInput.value = d ? d.id : '';
    const nameInput = document.getElementById('driverM14Name');
    if (nameInput) nameInput.value = d ? (d.name + ' (' + d.id + ')') : '';
    const roleSelect = document.getElementById('driverM14Role');
    if (roleSelect && d) roleSelect.value = d.role;
    const vehInput = document.getElementById('driverM14Vehicle');
    if (vehInput && d) vehInput.value = d.assignedVehicle;
    const routeInput = document.getElementById('driverM14Route');
    if (routeInput && d) routeInput.value = d.assignedRoute;
    const dutySelect = document.getElementById('driverM14Duty');
    if (dutySelect && d) dutySelect.value = d.dutyStatus;
    const expInput = document.getElementById('driverM14Expiry');
    if (expInput && d) expInput.value = d.documentExpiry;

    openModal('assignDriverDutiesModal');
  }

  function handleAssignDriverDutiesSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const empId = document.getElementById('driverM14EmpId')?.value;
    const role = document.getElementById('driverM14Role')?.value || 'Driver';
    const veh = document.getElementById('driverM14Vehicle')?.value || 'AP-07-TX-1041';
    const route = document.getElementById('driverM14Route')?.value || 'Route 1';
    const duty = document.getElementById('driverM14Duty')?.value || 'On Duty';
    const expiry = document.getElementById('driverM14Expiry')?.value || 'DL: 15 Aug 2028 • Medical: Fit';

    const d = TRANSPORT_DRIVERS_DATA.find(x => x.id === empId);
    if (d) {
      d.role = role;
      d.assignedVehicle = veh;
      d.assignedRoute = route;
      d.dutyStatus = duty;
      d.documentExpiry = expiry;
      showToast('Duties Assigned', 'Roster and duty schedule updated for ' + d.name + ' (' + d.id + ').', 'success');
    }
    closeModal('assignDriverDutiesModal');
    renderTransportDriversTable();
  }

  function verifyDriverDocuments(empId) {
    const d = TRANSPORT_DRIVERS_DATA.find(x => x.id === empId);
    if (d) {
      d.licenseVerification = 'HMV Commercial • Verified by RTA & AMVI Guntur';
      d.policeVerification = 'Cleared (PVR #AP-PVR-2026-Verified)';
      renderTransportDriversTable();
      showToast('Statutory Credentials Verified', 'Mandatory HMV licence, medical fitness, and police verification clearance stamped for ' + d.name + '.', 'success');
    }
  }

  function recordDriverChanges(empId, changes) {
    const d = TRANSPORT_DRIVERS_DATA.find(x => x.id === empId);
    if (d) {
      const note = changes || 'Shift change and medical recertification logged under Sri P. Appa Rao.';
      showToast('Driver Change Logged', note + ' recorded for ' + d.name + '.', 'success');
    }
  }

  function suspendDriverAssignment(empId, reason) {
    const d = TRANSPORT_DRIVERS_DATA.find(x => x.id === empId);
    if (d) {
      d.dutyStatus = 'Suspended';
      renderTransportDriversTable();
      const r = reason || 'Medical re-examination or administrative enquiry';
      showToast('Assignment Suspended', d.name + ' (' + d.id + ') suspended from duty: ' + r + '. Standby driver assigned.', 'warning');
    }
  }

