  function openReportFaultModal() {
    const form = document.getElementById('reportFaultForm');
    if (form) form.reset();
    openModal('reportFaultModal');
  }

  function handleReportFaultSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const asset = document.getElementById('faultM14Asset')?.value || 'School Bus AP-07-TX-1041';
    const prio = document.getElementById('faultM14Priority')?.value || 'High';
    const desc = document.getElementById('faultM14Desc')?.value || 'Reported mechanical anomaly';
    const vendor = document.getElementById('faultM14Vendor')?.value || 'Sri Lakshmi Commercial Auto Works';
    const checklist = document.getElementById('faultM14Checklist')?.value || 'Brakes, Tyres, Speed Governor, GPS, Emergency Door';

    const newTicketId = 'MNT-2026-0' + (TRANSPORT_MAINTENANCE_DATA.length + 81);
    const newTicket = {
      ticketId: newTicketId,
      category: asset.toLowerCase().includes('bus') || asset.toLowerCase().includes('van') ? 'Fleet Vehicle' : 'Campus Facility',
      assetName: asset,
      reportedIssue: desc,
      severity: prio,
      dateReported: new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }),
      reportedBy: 'Driver / Staff (Verified by Sri P. Appa Rao)',
      assignedVendor: vendor,
      technicianContact: 'Sri P. Koteswara Rao (98481 44551)',
      estimatedCost: '₹5,000',
      actualCost: '₹5,000',
      resolution: 'Work order generated; assigned to service partner.',
      checklist: checklist,
      evidence: 'Under Evaluation',
      status: 'In Progress',
      completedDate: 'Pending Verification',
      statusClass: 'badge-primary'
    };

    TRANSPORT_MAINTENANCE_DATA.unshift(newTicket);
    closeModal('reportFaultModal');
    renderTransportMaintenanceTable();
    showToast('Fault Reported', 'Job card ' + newTicketId + ' registered for ' + asset + ' with ' + prio + ' priority.', 'success');
  }

  function assignRepairTechnician(ticketId, vendor) {
    const m = TRANSPORT_MAINTENANCE_DATA.find(x => x.ticketId === ticketId);
    if (m) {
      m.assignedVendor = vendor || 'Sri Lakshmi Commercial Auto Works, Autonagar, Guntur';
      m.status = 'In Progress';
      renderTransportMaintenanceTable();
      showToast('Repair Assigned', 'Ticket ' + ticketId + ' assigned to authorized vendor ' + m.assignedVendor + '.', 'success');
    }
  }

  function openRecordMaintenanceWorkModal(ticketId) {
    const m = (ticketId ? TRANSPORT_MAINTENANCE_DATA.find(x => x.ticketId === ticketId) : null) || TRANSPORT_MAINTENANCE_DATA[0];
    const form = document.getElementById('recordMaintenanceWorkForm');
    if (form) form.reset();

    const idInput = document.getElementById('workM14TicketId');
    if (idInput) idInput.value = m ? m.ticketId : '';
    const assetDisp = document.getElementById('workM14AssetDisplay');
    if (assetDisp) assetDisp.textContent = m ? (m.ticketId + ' • ' + m.assetName) : '';
    const probDisp = document.getElementById('workM14ProblemDisplay');
    if (probDisp) probDisp.textContent = m ? m.reportedIssue : '';

    openModal('recordMaintenanceWorkModal');
  }

  function handleRecordMaintenanceWorkSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const ticketId = document.getElementById('workM14TicketId')?.value;
    const status = document.getElementById('workM14Status')?.value || 'Resolved';
    const evidence = document.getElementById('workM14Evidence')?.value || 'OEM Invoice & RTA Fitness Verified';
    const summary = document.getElementById('workM14Summary')?.value || 'Overhaul completed successfully.';
    const checklist = document.getElementById('workM14ChecklistVerified')?.value || 'Brakes [OK] • Tyres [OK] • GPS [Online]';

    const m = TRANSPORT_MAINTENANCE_DATA.find(x => x.ticketId === ticketId);
    if (m) {
      m.status = status;
      m.evidence = evidence;
      m.resolution = summary;
      m.checklist = checklist;
      m.completedDate = new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
      showToast('Work Order Recorded', 'Maintenance completion recorded for ' + ticketId + ' with verified checklist.', 'success');
    }
    closeModal('recordMaintenanceWorkModal');
    renderTransportMaintenanceTable();
  }

  function approveMaintenanceCompletion(ticketId) {
    const m = TRANSPORT_MAINTENANCE_DATA.find(x => x.ticketId === ticketId);
    if (m) {
      m.status = 'Approved';
      m.evidence = m.evidence + ' • Sanctioned by Principal Smt. Gorle Varalakshmi';
      renderTransportMaintenanceTable();
      showToast('Maintenance Approved', 'Executive sign-off granted by Principal for ' + ticketId + '. Fitness verified.', 'success');
    }
  }

  function openScheduleInspectionModal(assetName) {
    const form = document.getElementById('scheduleInspectionForm');
    if (form) form.reset();

    const assetInput = document.getElementById('inspM14Asset');
    if (assetInput && assetName) {
      assetInput.value = assetName;
    }
    openModal('scheduleInspectionModal');
  }

  function handleScheduleInspectionSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const asset = document.getElementById('inspM14Asset')?.value || 'School Bus AP-07-TX-1041';
    const date = document.getElementById('inspM14Date')?.value || '2026-11-15';
    const inspector = document.getElementById('inspM14Inspector')?.value || 'Assistant Motor Vehicle Inspector (AMVI), RTA Guntur';
    const checklist = document.getElementById('inspM14Checklist')?.value || 'Speed governor, emergency exits, CCTV, first aid box';

    const newInsp = {
      inspectionId: 'INSP-2026-0' + (TRANSPORT_SAFETY_DATA.length + 42),
      date: date,
      inspectionTitle: 'Statutory Safety & Compliance Audit for ' + asset,
      category: 'Fleet & Institutional Safety',
      inspector: inspector,
      complianceRef: 'AMVI/GNT/INSP/2026/' + Math.floor(100 + Math.random() * 900),
      validTill: '31 Oct 2027',
      status: 'Scheduled',
      passedPoints: 'Mandatory Norms Checklist Initialized',
      findings: checklist,
      correctiveActions: 'Awaiting scheduled inspection on ' + date + ' by ' + inspector + '.'
    };

    TRANSPORT_SAFETY_DATA.unshift(newInsp);
    closeModal('scheduleInspectionModal');
    renderTransportSafetyTable();
    showToast('Inspection Scheduled', 'Official safety inspection booked for ' + asset + ' on ' + date + ' with ' + inspector + '.', 'success');
  }

  // =========================================================================
  // SECTION 14.6: SAFETY AUDIT CONTROLLERS & SHARED SUITE UTILITIES
  // =========================================================================

  function renderTransportSafetyTable() {
    const tbody = document.getElementById('transportSafetyTableBody');
    if (!tbody) return;
    const catFilter = (document.getElementById('transportSafetyCategoryFilter')?.value) || 'all';
    const q = (document.getElementById('transportSafetySearchInput')?.value || '').toLowerCase().trim();

    let list = TRANSPORT_SAFETY_DATA.filter(s => {
      const matchCat = catFilter === 'all' || s.category.toLowerCase().includes(catFilter.toLowerCase());
      const matchQ = !q || s.inspectionId.toLowerCase().includes(q) || s.inspectionTitle.toLowerCase().includes(q) ||
        s.inspector.toLowerCase().includes(q) || s.complianceRef.toLowerCase().includes(q);
      return matchCat && matchQ;
    });

    if (list.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" class="text-center py-4 text-muted"><i class="fa-solid fa-shield-halved fa-2x mb-2 d-block"></i>No safety audit records match criteria.</td></tr>';
      return;
    }

    tbody.innerHTML = list.map(s => `
      <tr>
        <td><strong>${s.inspectionId}</strong><div class="text-muted" style="font-size: 0.72rem;">${s.date}</div></td>
        <td><div style="font-weight: 600;">${s.inspectionTitle}</div><div class="text-muted" style="font-size: 0.72rem;">${s.category}</div></td>
        <td><div style="font-size: 0.8rem;">${s.inspector}</div><div class="text-muted" style="font-size: 0.72rem;">Ref: ${s.complianceRef}</div></td>
        <td><span class="portal-badge badge-neutral" style="font-size: 0.75rem;">${s.validTill}</span></td>
        <td><span class="portal-badge ${s.status === 'Passed' ? 'badge-success' : 'badge-warning'}">${s.status}</span></td>
        <td style="font-size: 0.75rem; color: #475569;">${s.passedPoints}</td>
        <td style="text-align: right;">
          <button class="btn btn-outline" style="padding: 3px 8px; font-size: 0.75rem;" onclick="portalApp.openTransportDossierModal('${s.inspectionId}', 'safety')">
            <i class="fa-solid fa-file-shield text-primary mr-1"></i> Certificate
          </button>
        </td>
      </tr>
    `).join('');
  }

  function filterTransportSafety() {
    renderTransportSafetyTable();
  }

