  function openNewTransportModal(category) {
    if (category === 'route') {
      openCreateTransportRouteModal();
    } else if (category === 'vehicle') {
      openAddVehicleModal();
    } else if (category === 'driver') {
      openAssignDriverDutiesModal();
    } else if (category === 'allocation') {
      openAssignStudentRouteModal();
    } else if (category === 'maintenance') {
      openReportFaultModal();
    } else {
      openCreateTransportRouteModal();
    }
  }

