  function renderInventoryAssetsTable() {
    const tbody = document.getElementById('inventoryAssetsTableBody');
    if (!tbody) return;
    const catFilter = (document.getElementById('inventoryAssetCategoryFilter')?.value) || 'all';
    const q = (document.getElementById('inventoryAssetSearchInput')?.value || '').toLowerCase().trim();

    let list = INVENTORY_ASSETS_DATA.filter(a => {
      const matchCat = catFilter === 'all' || 
        a.category.toLowerCase().includes(catFilter.toLowerCase()) || 
        (a.status && a.status.toLowerCase() === catFilter.toLowerCase());
      const matchQ = !q || 
        a.assetId.toLowerCase().includes(q) || 
        a.name.toLowerCase().includes(q) ||
        a.location.toLowerCase().includes(q) || 
        (a.serialNo && a.serialNo.toLowerCase().includes(q)) ||
        (a.assignedDepartment && a.assignedDepartment.toLowerCase().includes(q));
      return matchCat && matchQ;
    });

    if (list.length === 0) {
      tbody.innerHTML = '<tr><td colspan="12" class="text-center py-4 text-muted"><i class="fa-solid fa-barcode fa-2x mb-2 d-block"></i>No capital assets match the selected criteria.</td></tr>';
      return;
    }

    tbody.innerHTML = list.map(a => {
      const condBadge = (a.condition === 'Excellent' || a.condition === 'Good')
        ? '<span class="portal-badge badge-success">' + a.condition + '</span>'
        : (a.condition === 'Fair')
        ? '<span class="portal-badge badge-warning">' + a.condition + '</span>'
        : '<span class="portal-badge badge-danger">' + a.condition + '</span>';

      const statusBadge = (a.status === 'Disposed')
        ? '<span class="portal-badge badge-danger"><i class="fa-solid fa-ban mr-1"></i>Disposed</span>'
        : (a.status === 'Under Maintenance')
        ? '<span class="portal-badge badge-warning"><i class="fa-solid fa-wrench mr-1"></i>Maintenance</span>'
        : '<span class="portal-badge badge-success"><i class="fa-solid fa-circle-check mr-1"></i>' + (a.status || 'In Service') + '</span>';

      return `
        <tr>
          <td><span class="portal-badge badge-primary font-monospace" style="font-weight:700;">${a.assetId}</span></td>
          <td>
            <div style="font-weight: 700; color: #1e3a8a;">${a.name}</div>
            <div class="text-muted" style="font-size: 0.72rem;"><i class="fa-solid fa-user-shield mr-1"></i>${a.custodian || 'Store In-charge'}</div>
          </td>
          <td><span class="portal-badge badge-neutral" style="font-size: 0.75rem;">${a.category}</span></td>
          <td><span class="font-monospace small">${a.serialNo || 'N/A'}</span></td>
          <td><span class="small">${a.purchaseDate}</span></td>
          <td><span class="fw-bold" style="color:#0f172a;">${a.purchaseValue || a.value}</span></td>
          <td>
            <div style="font-size: 0.8rem; font-weight: 600;">${a.location}</div>
          </td>
          <td>
            <div style="font-size: 0.78rem; color: #475569;">${a.assignedDepartment || 'General Admin'}</div>
          </td>
          <td>${condBadge}</td>
          <td>
            <div class="text-muted" style="font-size: 0.72rem; max-width: 130px; line-height: 1.25;">${a.warranty}</div>
          </td>
          <td>${statusBadge}</td>
          <td style="text-align: right; white-space: nowrap;">
            <div style="display: inline-flex; gap: 4px;">
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Assign location / Transfer" onclick="portalApp.openTransferAssetModal('${a.assetId}')">
                <i class="fa-solid fa-location-dot"></i> Move
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Record maintenance" onclick="portalApp.openRecordAssetMaintenanceModal('${a.assetId}')">
                <i class="fa-solid fa-wrench"></i> Maintain
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Mark disposed with authorization" onclick="portalApp.openDisposeAssetModal('${a.assetId}')">
                <i class="fa-solid fa-ban text-danger"></i> Dispose
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="View asset history dossier" onclick="portalApp.viewAssetHistory('${a.assetId}')">
                <i class="fa-solid fa-clock-rotate-left text-primary"></i> Dossier
              </button>
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

