    const id = document.getElementById('disposeAssetId')?.value;
    const reason = document.getElementById('disposeAssetReason')?.value || 'Condemned';
    const scrapVal = document.getElementById('disposeAssetScrapValue')?.value || '₹0';
    const authBy = document.getElementById('disposeAssetAuthBy')?.value || 'Principal Smt. Gorle Varalakshmi';
    const sanctionRef = document.getElementById('disposeAssetSanctionRef')?.value || 'SV/DISP/2026/01';

    markAssetDisposed(id, reason + ' (Scrap: ' + scrapVal + ', Ref: ' + sanctionRef + ')', authBy);
    closeModal('disposeAssetModal');
