  function renderInventoryStockTable() {
    const tbody = document.getElementById('inventoryStockTableBody');
    if (!tbody) return;
    const levelFilter = (document.getElementById('inventoryStockLevelFilter')?.value) || 'all';
    const q = (document.getElementById('inventoryStockSearchInput')?.value || '').toLowerCase().trim();

    let list = INVENTORY_STOCK_DATA.filter(s => {
      const matchLevel = levelFilter === 'all' || 
        s.stockLevel.toLowerCase().includes(levelFilter.toLowerCase());
      const matchQ = !q || 
        s.item.toLowerCase().includes(q) || 
        (s.itemCode && s.itemCode.toLowerCase().includes(q)) ||
        (s.stockId && s.stockId.toLowerCase().includes(q)) ||
        s.storageLocation.toLowerCase().includes(q) ||
        s.category.toLowerCase().includes(q);
      return matchLevel && matchQ;
    });

    if (list.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" class="text-center py-4 text-muted"><i class="fa-solid fa-boxes-stacked fa-2x mb-2 d-block"></i>No stock consumables match the selected criteria.</td></tr>';
      return;
    }

    tbody.innerHTML = list.map(s => {
      const currentQty = s.quantityAvailable !== undefined ? s.quantityAvailable : s.quantity;
      const threshold = s.reorderThreshold !== undefined ? s.reorderThreshold : s.threshold;
      const isLow = currentQty <= threshold;

      const qtyDisplay = isLow
        ? '<span class="fw-bold fs-6 text-danger"><i class="fa-solid fa-triangle-exclamation mr-1"></i>' + currentQty + '</span>'
        : '<span class="fw-bold fs-6 text-primary">' + currentQty + '</span>';

      return `
        <tr>
          <td>
            <div style="font-weight: 700; color: #1e3a8a;">${s.item}</div>
            <div class="text-muted" style="font-size: 0.72rem;">${s.category} • Rate: ${s.unitPrice || '₹250'}</div>
          </td>
          <td><span class="portal-badge badge-primary font-monospace">${s.itemCode || s.stockId}</span></td>
          <td>${qtyDisplay}</td>
          <td><span class="portal-badge badge-neutral">${threshold}</span></td>
          <td>
            <div style="font-size: 0.8rem; font-weight:600;"><i class="fa-solid fa-warehouse text-amber mr-1"></i>${s.storageLocation}</div>
          </td>
          <td><span class="small text-muted">${s.unit}</span></td>
          <td>
            <div style="font-size: 0.78rem;">${s.lastMovement || s.lastRestocked || 'Verified in audit'}</div>
          </td>
          <td style="text-align: right; white-space: nowrap;">
            <div style="display: inline-flex; gap: 4px;">
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Receive stock" onclick="portalApp.openReceiveStockModal('${s.itemCode || s.stockId}')">
                <i class="fa-solid fa-arrow-down text-success"></i> Receive
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Issue stock" onclick="portalApp.openIssueStockModal('${s.itemCode || s.stockId}')">
                <i class="fa-solid fa-arrow-up text-warning"></i> Issue
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Return stock" onclick="portalApp.openReturnStockModal('${s.itemCode || s.stockId}')">
                <i class="fa-solid fa-rotate-left"></i> Return
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Adjust inventory with reason" onclick="portalApp.openAdjustStockModal('${s.itemCode || s.stockId}')">
                <i class="fa-solid fa-sliders"></i> Adjust
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Request replenishment indent" onclick="portalApp.requestStockReplenishment('${s.itemCode || s.stockId}')">
                <i class="fa-solid fa-cart-shopping text-primary"></i> Indent
              </button>
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

  function filterInventoryStock() {
    renderInventoryStockTable();
  }

  function openReceiveStockModal(itemCode) {
    const s = (itemCode ? INVENTORY_STOCK_DATA.find(x => x.itemCode === itemCode || x.stockId === itemCode) : null) || INVENTORY_STOCK_DATA[0];
    const form = document.getElementById('receiveStockForm');
    if (form) form.reset();

    const codeInput = document.getElementById('recStockCode');
    if (codeInput) codeInput.value = s ? (s.itemCode || s.stockId) : '';
    const itemDisp = document.getElementById('recStockItemDisplay');
    if (itemDisp) itemDisp.textContent = s ? ((s.itemCode || s.stockId) + ': ' + s.item + ' [Current: ' + (s.quantityAvailable || s.quantity) + ' ' + s.unit + ']') : '';
    const locInput = document.getElementById('recStockLocation');
    if (locInput && s) locInput.value = s.storageLocation;

    openModal('receiveStockModal');
  }

  function handleReceiveStockSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const code = document.getElementById('recStockCode')?.value;
    const qty = parseInt(document.getElementById('recStockQty')?.value, 10) || 0;
    const vendor = document.getElementById('recStockVendor')?.value || 'Registered Vendor';
    const challan = document.getElementById('recStockChallan')?.value || 'DC-NEW';

    const s = INVENTORY_STOCK_DATA.find(x => x.itemCode === code || x.stockId === code);
    if (s) {
      const prev = s.quantityAvailable !== undefined ? s.quantityAvailable : s.quantity;
      const updated = prev + qty;
      s.quantityAvailable = updated;
      s.quantity = updated;
      s.lastMovement = new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }) + ' (+' + qty + ' Received via ' + challan + ')';
      s.stockLevel = updated <= (s.reorderThreshold || s.threshold) ? 'Low Stock' : 'Optimal';
      showToast('Stock Received', 'Added +' + qty + ' ' + s.unit + ' to ' + s.item + ' from ' + vendor + '. New Stock: ' + updated, 'success');
    }
    closeModal('receiveStockModal');
    renderInventoryStockTable();
  }

  function openIssueStockModal(itemCode) {
    const s = (itemCode ? INVENTORY_STOCK_DATA.find(x => x.itemCode === itemCode || x.stockId === itemCode) : null) || INVENTORY_STOCK_DATA[0];
    const form = document.getElementById('issueStockForm');
    if (form) form.reset();

    const codeInput = document.getElementById('issueStockCode');
    if (codeInput) codeInput.value = s ? (s.itemCode || s.stockId) : '';
    const itemDisp = document.getElementById('issueStockItemDisplay');
    if (itemDisp) itemDisp.textContent = s ? ((s.itemCode || s.stockId) + ': ' + s.item + ' [Available: ' + (s.quantityAvailable || s.quantity) + ' ' + s.unit + ']') : '';

    openModal('issueStockModal');
  }

  function handleIssueStockSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const code = document.getElementById('issueStockCode')?.value;
    const recipient = document.getElementById('issueStockRecipient')?.value || 'Faculty';
    const dept = document.getElementById('issueStockDept')?.value || 'Academic Dept';
    const qty = parseInt(document.getElementById('issueStockQty')?.value, 10) || 0;
    const purpose = document.getElementById('issueStockPurpose')?.value || 'Academic Requisition';

    const s = INVENTORY_STOCK_DATA.find(x => x.itemCode === code || x.stockId === code);
    if (s) {
      const prev = s.quantityAvailable !== undefined ? s.quantityAvailable : s.quantity;
      if (qty > prev) {
        showToast('Insufficient Stock', 'Cannot issue ' + qty + ' units. Available stock is only ' + prev + '.', 'danger');
        return;
      }
      const updated = prev - qty;
      s.quantityAvailable = updated;
      s.quantity = updated;
      s.lastMovement = new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }) + ' (-' + qty + ' Issued to ' + recipient + ')';
      s.stockLevel = updated <= (s.reorderThreshold || s.threshold) ? 'Low Stock' : 'Optimal';
      showToast('Stock Issued', 'Issued ' + qty + ' ' + s.unit + ' of ' + s.item + ' to ' + recipient + ' (' + dept + '). Purpose: ' + purpose, 'success');
    }
    closeModal('issueStockModal');
    renderInventoryStockTable();
  }

  function openReturnStockModal(itemCode) {
    const s = (itemCode ? INVENTORY_STOCK_DATA.find(x => x.itemCode === itemCode || x.stockId === itemCode) : null) || INVENTORY_STOCK_DATA[0];
    const form = document.getElementById('returnStockForm');
    if (form) form.reset();

    const codeInput = document.getElementById('returnStockCode');
    if (codeInput) codeInput.value = s ? (s.itemCode || s.stockId) : '';
    const itemDisp = document.getElementById('returnStockItemDisplay');
    if (itemDisp) itemDisp.textContent = s ? ((s.itemCode || s.stockId) + ': ' + s.item) : '';

    openModal('returnStockModal');
  }

  function handleReturnStockSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const code = document.getElementById('returnStockCode')?.value;
    const recipient = document.getElementById('returnStockRecipient')?.value || 'Staff';
    const qty = parseInt(document.getElementById('returnStockQty')?.value, 10) || 0;
    const cond = document.getElementById('returnStockCondition')?.value || 'Good';
    const reason = document.getElementById('returnStockReason')?.value || 'Surplus stock';

    const s = INVENTORY_STOCK_DATA.find(x => x.itemCode === code || x.stockId === code);
    if (s) {
      const prev = s.quantityAvailable !== undefined ? s.quantityAvailable : s.quantity;
      const updated = prev + qty;
      s.quantityAvailable = updated;
      s.quantity = updated;
      s.lastMovement = new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }) + ' (+' + qty + ' Returned by ' + recipient + ')';
      showToast('Stock Returned', 'Accepted ' + qty + ' ' + s.unit + ' of ' + s.item + ' back into store from ' + recipient + '. Reason: ' + reason, 'success');
    }
    closeModal('returnStockModal');
    renderInventoryStockTable();
  }

  function openAdjustStockModal(itemCode) {
    const s = (itemCode ? INVENTORY_STOCK_DATA.find(x => x.itemCode === itemCode || x.stockId === itemCode) : null) || INVENTORY_STOCK_DATA[0];
    const form = document.getElementById('adjustStockForm');
    if (form) form.reset();

    const codeInput = document.getElementById('adjustStockCode');
    if (codeInput) codeInput.value = s ? (s.itemCode || s.stockId) : '';
    const itemDisp = document.getElementById('adjustStockItemDisplay');
    if (itemDisp) itemDisp.textContent = s ? ((s.itemCode || s.stockId) + ': ' + s.item) : '';
    const curQty = document.getElementById('adjustStockCurrentQty');
    if (curQty) curQty.textContent = s ? ((s.quantityAvailable || s.quantity) + ' ' + s.unit) : '';

    openModal('adjustStockModal');
  }

  function handleAdjustStockSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const code = document.getElementById('adjustStockCode')?.value;
    const newQty = parseInt(document.getElementById('adjustStockNewQty')?.value, 10) || 0;
    const reason = document.getElementById('adjustStockReason')?.value || 'Audit adjustment';

    const s = INVENTORY_STOCK_DATA.find(x => x.itemCode === code || x.stockId === code);
    if (s) {
      const prev = s.quantityAvailable !== undefined ? s.quantityAvailable : s.quantity;
      s.quantityAvailable = newQty;
      s.quantity = newQty;
      s.lastMovement = new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }) + ' (Adjusted from ' + prev + ' to ' + newQty + ')';
      s.stockLevel = newQty <= (s.reorderThreshold || s.threshold) ? 'Low Stock' : 'Optimal';
      showToast('Stock Adjusted', s.item + ' count reconciled to ' + newQty + ' ' + s.unit + '. Statutory audit note: ' + reason, 'warning');
    }
    closeModal('adjustStockModal');
    renderInventoryStockTable();
  }

  function requestStockReplenishment(itemCode) {
    const s = INVENTORY_STOCK_DATA.find(x => x.itemCode === itemCode || x.stockId === itemCode);
    if (!s) return;

    const reqId = 'PR-2026-0' + (INVENTORY_PURCHASES_DATA.length + 61);
    const newReq = {
      reqId: reqId,
      requester: 'Store In-charge Sri P. Appa Rao',
      department: 'Central Store & Logistics',
      items: 'Replenishment for ' + s.item + ' (' + s.unit + ')',
      quantity: 'Reorder Batch (est. 100 ' + s.unit + ')',
      estimatedCost: '₹12,500',
      justification: 'Stock level touched threshold (' + (s.quantityAvailable || s.quantity) + ' units remaining). Immediate indent required for campus continuity.',
      vendor: 'Sri Krishna Book Depot & Stationers',
      vendorRecommended: 'Sri Krishna Book Depot & Stationers',
      approvalStatus: 'Submitted',
      statusClass: 'badge-primary',
      poNumber: 'Pending PO',
      grnNumber: 'Pending GRN',
      invoiceNumber: 'Pending',
      date: new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }),
      priority: 'High'
    };

    INVENTORY_PURCHASES_DATA.unshift(newReq);
    renderInventoryPurchasesTable();
    showToast('Replenishment Indent Created', 'Generated purchase requisition ' + reqId + ' for ' + s.item + '.', 'success');
  }

  function exportStockReportCSV() {
    let csv = 'Item Code,Item Name,Category,Quantity Available,Reorder Threshold,Unit,Storage Location,Last Movement,Unit Price\n';
    INVENTORY_STOCK_DATA.forEach(s => {
      csv += `"${s.itemCode || s.stockId}","${s.item}","${s.category}",${s.quantityAvailable !== undefined ? s.quantityAvailable : s.quantity},${s.reorderThreshold || s.threshold},"${s.unit}","${s.storageLocation}","${s.lastMovement || s.lastRestocked}","${s.unitPrice || 'N/A'}"\n`;
    });
    downloadCSV(csv, 'SriVidya_Consumable_Stock_Report_' + new Date().toISOString().slice(0, 10) + '.csv');
    showToast('Stock Report Exported', 'Exported stock inventory report to CSV.', 'success');
  }

