  function renderInventoryPurchasesTable() {
    const tbody = document.getElementById('inventoryPurchasesTableBody');
    if (!tbody) return;
    const statFilter = (document.getElementById('inventoryPurchasesStatusFilter')?.value) || 'all';
    const q = (document.getElementById('inventoryPurchasesSearchInput')?.value || '').toLowerCase().trim();

    let list = INVENTORY_PURCHASES_DATA.filter(p => {
      const matchStat = statFilter === 'all' || 
        p.approvalStatus.toLowerCase().includes(statFilter.toLowerCase());
      const matchQ = !q || 
        p.reqId.toLowerCase().includes(q) || 
        p.requester.toLowerCase().includes(q) ||
        p.department.toLowerCase().includes(q) || 
        p.items.toLowerCase().includes(q) ||
        (p.vendor && p.vendor.toLowerCase().includes(q)) ||
        (p.vendorRecommended && p.vendorRecommended.toLowerCase().includes(q));
      return matchStat && matchQ;
    });

    if (list.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" class="text-center py-4 text-muted"><i class="fa-solid fa-cart-shopping fa-2x mb-2 d-block"></i>No purchase requests match the selected criteria.</td></tr>';
      return;
    }

    tbody.innerHTML = list.map(p => {
      const statusBadge = (p.approvalStatus.includes('Approved') || p.approvalStatus.includes('Matched') || p.approvalStatus.includes('Goods Received'))
        ? '<span class="portal-badge badge-success"><i class="fa-solid fa-circle-check mr-1"></i>' + p.approvalStatus + '</span>'
        : (p.approvalStatus.includes('Rejected'))
        ? '<span class="portal-badge badge-danger"><i class="fa-solid fa-ban mr-1"></i>' + p.approvalStatus + '</span>'
        : (p.approvalStatus.includes('PO Issued') || p.approvalStatus.includes('Submitted'))
        ? '<span class="portal-badge badge-primary"><i class="fa-solid fa-clock mr-1"></i>' + p.approvalStatus + '</span>'
        : '<span class="portal-badge badge-warning"><i class="fa-solid fa-hourglass-half mr-1"></i>' + p.approvalStatus + '</span>';

      return `
        <tr>
          <td><span class="portal-badge badge-primary font-monospace" style="font-weight:700;">${p.reqId}</span></td>
          <td>
            <div style="font-weight: 700; color: #1e3a8a;">${p.requester}</div>
            <div class="text-muted" style="font-size: 0.72rem;">${p.date || 'Today'}</div>
          </td>
          <td><span class="portal-badge badge-neutral" style="font-size: 0.75rem;">${p.department}</span></td>
          <td style="max-width: 220px;">
            <div style="font-size: 0.8rem; font-weight: 600; line-height: 1.35; color: #1e293b;">${p.items}</div>
          </td>
          <td><span class="small">${p.quantity || 'Standard lot'}</span></td>
          <td><span class="fw-bold" style="color:#0f172a;">${p.estimatedCost}</span></td>
          <td style="max-width: 200px;">
            <div class="text-muted" style="font-size: 0.72rem; line-height: 1.3;">${p.justification || 'Academic syllabus requisition'}</div>
          </td>
          <td>
            <div style="font-size: 0.78rem; font-weight: 600;">${p.vendor || p.vendorRecommended || 'Under Quotation'}</div>
            <div class="text-muted" style="font-size: 0.72rem;">${p.poNumber ? 'PO: ' + p.poNumber : ''}</div>
          </td>
          <td>${statusBadge}</td>
          <td style="text-align: right; white-space: nowrap;">
            <div style="display: inline-flex; gap: 4px;">
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Submit indent" onclick="portalApp.submitPurchaseRequest('${p.reqId}')">
                <i class="fa-solid fa-paper-plane"></i> Submit
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Approve purchase" onclick="portalApp.approvePurchaseRequest('${p.reqId}')">
                <i class="fa-solid fa-check text-success"></i> Approve
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Reject purchase" onclick="portalApp.rejectPurchaseRequest('${p.reqId}')">
                <i class="fa-solid fa-xmark text-danger"></i> Reject
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Request vendor quotations" onclick="portalApp.requestPurchaseQuotations('${p.reqId}')">
                <i class="fa-solid fa-comments-dollar text-primary"></i> Quotes
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Generate Purchase Order" onclick="portalApp.recordPurchaseOrder('${p.reqId}')">
                <i class="fa-solid fa-file-invoice"></i> PO
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Record receipt of goods" onclick="portalApp.recordReceiptOfGoods('${p.reqId}')">
                <i class="fa-solid fa-boxes-packing"></i> GRN
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Match invoice and receipt" onclick="portalApp.openMatchInvoiceReceiptModal('${p.reqId}')">
                <i class="fa-solid fa-receipt text-indigo"></i> Match
              </button>
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

