  function handleCreatePurchaseRequestSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const id = document.getElementById('prM15Id')?.value || ('PR-2026-' + Math.floor(100 + Math.random() * 900));
    const dept = document.getElementById('prM15Dept')?.value || 'Academic Dept';
    const requester = document.getElementById('prM15Requester')?.value || 'Faculty Member';
    const cost = document.getElementById('prM15Cost')?.value || '₹10,000';
    const items = document.getElementById('prM15Items')?.value || 'Requisitioned Materials';
    const qty = document.getElementById('prM15Quantity')?.value || 'Standard Lot';
    const vendor = document.getElementById('prM15Vendor')?.value || 'Registered Partner';
    const justification = document.getElementById('prM15Justification')?.value || 'Syllabus requirement';

    const newReq = {
      reqId: id,
      requester: requester,
      department: dept,
      items: items,
      quantity: qty,
      estimatedCost: cost,
      justification: justification,
      vendor: vendor,
      vendorRecommended: vendor,
      approvalStatus: 'Submitted',
      statusClass: 'badge-primary',
      poNumber: 'Pending PO',
      grnNumber: 'Pending Receipt',
      invoiceNumber: 'Pending',
      date: new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }),
      priority: 'High'
    };

    INVENTORY_PURCHASES_DATA.unshift(newReq);
    closeModal('createPurchaseRequestModal');
    renderInventoryPurchasesTable();
    showToast('Purchase Indent Created', id + ' submitted for Principal administrative review.', 'success');
  }

  function submitPurchaseRequest(reqId) {
    const p = INVENTORY_PURCHASES_DATA.find(x => x.reqId === reqId);
    if (p) {
      p.approvalStatus = 'Submitted';
      renderInventoryPurchasesTable();
      showToast('Indent Submitted', reqId + ' forwarded to Principal Smt. Gorle Varalakshmi for financial sanction.', 'info');
    }
  }

  function approvePurchaseRequest(reqId) {
    const p = INVENTORY_PURCHASES_DATA.find(x => x.reqId === reqId);
    if (p) {
      p.approvalStatus = 'Approved by Principal';
      renderInventoryPurchasesTable();
      showToast('Purchase Approved', reqId + ' approved by Principal. Authorized to issue purchase order.', 'success');
    }
  }

  function rejectPurchaseRequest(reqId, reason) {
    const p = INVENTORY_PURCHASES_DATA.find(x => x.reqId === reqId);
    if (p) {
      p.approvalStatus = 'Rejected';
      renderInventoryPurchasesTable();
      const r = reason || 'Budget ceiling exceeded or duplicate store stock available';
      showToast('Purchase Rejected', reqId + ' rejected: ' + r, 'danger');
    }
  }

  function requestPurchaseQuotations(reqId) {
    const p = INVENTORY_PURCHASES_DATA.find(x => x.reqId === reqId);
    if (p) {
      p.approvalStatus = 'Quotations Requested';
      renderInventoryPurchasesTable();
      showToast('Quotations Requested', 'Formal Request for Quotation (RFQ) dispatched to 3 empanelled vendors for ' + reqId + '.', 'success');
    }
  }

  function recordPurchaseOrder(reqId, poNumber) {
    const p = INVENTORY_PURCHASES_DATA.find(x => x.reqId === reqId);
    if (p) {
      const po = poNumber || ('PO-2026-0' + Math.floor(10 + Math.random() * 90));
      p.poNumber = po;
      p.approvalStatus = 'PO Issued (' + po + ')';
      renderInventoryPurchasesTable();
      showToast('Purchase Order Generated', 'Issued purchase order ' + po + ' for indent ' + reqId + ' to ' + (p.vendor || 'empaneled vendor') + '.', 'success');
    }
  }

  function recordReceiptOfGoods(reqId, grnNumber) {
    const p = INVENTORY_PURCHASES_DATA.find(x => x.reqId === reqId);
    if (p) {
      const grn = grnNumber || ('GRN-2026-1' + Math.floor(10 + Math.random() * 90));
      p.grnNumber = grn;
      p.approvalStatus = 'Goods Received (' + grn + ')';
      renderInventoryPurchasesTable();
      showToast('Goods Received Note Logged', grn + ' generated. Physical goods verified by Store In-charge Sri P. Appa Rao.', 'success');
    }
  }

  function openMatchInvoiceReceiptModal(reqId) {
    const p = (reqId ? INVENTORY_PURCHASES_DATA.find(x => x.reqId === reqId) : null) || INVENTORY_PURCHASES_DATA[0];
    const form = document.getElementById('matchInvoiceReceiptForm');
    if (form) form.reset();

    const idInput = document.getElementById('matchReqId');
    if (idInput) idInput.value = p ? p.reqId : '';
    const poDisp = document.getElementById('matchPoDisplay');
    if (poDisp) poDisp.textContent = p ? (p.poNumber || 'PO-2026-081') : '';
    const grnDisp = document.getElementById('matchGrnDisplay');
    if (grnDisp) grnDisp.textContent = p ? (p.grnNumber || 'GRN-2026-104') : '';
    const amtInput = document.getElementById('matchInvoiceAmount');
    if (amtInput && p) amtInput.value = p.estimatedCost;

    openModal('matchInvoiceReceiptModal');
  }

  function handleMatchInvoiceReceiptSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const id = document.getElementById('matchReqId')?.value;
    const invNo = document.getElementById('matchInvoiceNo')?.value || 'INV-2026-881';
    const amount = document.getElementById('matchInvoiceAmount')?.value || '₹14,200';

    matchInvoiceAndReceipt(id, invNo, amount);
    closeModal('matchInvoiceReceiptModal');
  }

  function matchInvoiceAndReceipt(reqId, invoiceNo, amount) {
    const p = INVENTORY_PURCHASES_DATA.find(x => x.reqId === reqId);
    if (p) {
      p.invoiceNumber = invoiceNo;
      p.approvalStatus = 'Invoice Matched (' + invoiceNo + ')';
      renderInventoryPurchasesTable();
      showToast('3-Way Match Verified', 'Matched PO (' + (p.poNumber || 'PO') + '), GRN (' + (p.grnNumber || 'GRN') + '), and Invoice ' + invoiceNo + ' for ' + amount + '. Cleared for accounts disbursement.', 'success');
    }
  }

  function exportInventoryPurchasesCSV() {
    let csv = 'Request ID,Requester,Department,Items,Quantity,Estimated Cost,Vendor,PO Number,GRN Number,Invoice Number,Status\n';
    INVENTORY_PURCHASES_DATA.forEach(p => {
      csv += `"${p.reqId}","${p.requester}","${p.department}","${p.items.replace(/"/g, '""')}","${p.quantity || 'N/A'}","${p.estimatedCost}","${p.vendor || p.vendorRecommended}","${p.poNumber || 'N/A'}","${p.grnNumber || 'N/A'}","${p.invoiceNumber || 'N/A'}","${p.approvalStatus}"\n`;
    });
    downloadCSV(csv, 'SriVidya_Purchase_Indents_' + new Date().toISOString().slice(0, 10) + '.csv');
    showToast('Purchase Indents Exported', 'Exported purchase requisitions and procurement log to CSV.', 'success');
  }

