  function renderInventoryVendorsTable() {
    const tbody = document.getElementById('inventoryVendorsTableBody');
    if (!tbody) return;
    const ratingFilter = (document.getElementById('inventoryVendorsRatingFilter')?.value) || 'all';
    const q = (document.getElementById('inventoryVendorsSearchInput')?.value || '').toLowerCase().trim();

    let list = INVENTORY_VENDORS_DATA.filter(v => {
      const matchRating = ratingFilter === 'all' || 
        (v.reviewStatus && v.reviewStatus.toLowerCase().includes(ratingFilter.toLowerCase())) ||
        (v.contractStatus && v.contractStatus.toLowerCase().includes(ratingFilter.toLowerCase()));
      const matchQ = !q || 
        v.name.toLowerCase().includes(q) || 
        v.vendorId.toLowerCase().includes(q) ||
        v.products.toLowerCase().includes(q) || 
        (v.contactPerson && v.contactPerson.toLowerCase().includes(q)) ||
        (v.gstin && v.gstin.toLowerCase().includes(q));
      return matchRating && matchQ;
    });

    if (list.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" class="text-center py-4 text-muted"><i class="fa-solid fa-truck-field fa-2x mb-2 d-block"></i>No empaneled vendors match the selected criteria.</td></tr>';
      return;
    }

    tbody.innerHTML = list.map(v => {
      const contractBadge = (v.contractStatus && v.contractStatus.includes('Active'))
        ? '<span class="portal-badge badge-success"><i class="fa-solid fa-file-contract mr-1"></i>Active</span>'
        : (v.contractStatus && v.contractStatus.includes('Deactivated'))
        ? '<span class="portal-badge badge-danger"><i class="fa-solid fa-ban mr-1"></i>Deactivated</span>'
        : '<span class="portal-badge badge-warning"><i class="fa-solid fa-clock mr-1"></i>' + (v.contractStatus || 'Under Review') + '</span>';

      return `
        <tr>
          <td>
            <div style="font-weight: 700; color: #1e3a8a;">${v.name}</div>
            <div class="text-muted font-monospace" style="font-size: 0.72rem;">${v.vendorId}</div>
          </td>
          <td>
            <div style="font-size: 0.8rem; font-weight: 600;">${v.contactPerson || ''}</div>
            <div class="text-muted" style="font-size: 0.72rem;"><i class="fa-solid fa-phone mr-1"></i>${v.phone || ''}</div>
            <div class="text-muted" style="font-size: 0.72rem;"><i class="fa-solid fa-envelope mr-1"></i>${v.email || ''}</div>
          </td>
          <td style="max-width: 220px;">
            <div style="font-size: 0.78rem; line-height: 1.35; color: #1e293b;">${v.products}</div>
          </td>
          <td>
            ${contractBadge}
            <div class="text-muted" style="font-size: 0.72rem; margin-top: 2px;">${v.contracts || ''}</div>
          </td>
          <td>
            <div class="font-monospace small">${v.taxDetails || ('GSTIN: ' + v.gstin)}</div>
          </td>
          <td><span class="small">${v.paymentTerms}</span></td>
          <td>
            <span class="portal-badge badge-success" style="font-size: 0.75rem;">${v.reviewStatus || v.rating || 'Approved'}</span>
          </td>
          <td style="text-align: right; white-space: nowrap;">
            <div style="display: inline-flex; gap: 4px;">
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Verify statutory details" onclick="portalApp.verifyVendorDetails('${v.vendorId}')">
                <i class="fa-solid fa-certificate text-success"></i> Verify
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Update contract &amp; SLA" onclick="portalApp.openUpdateVendorContractModal('${v.vendorId}')">
                <i class="fa-solid fa-file-signature"></i> Contract
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Record performance rating" onclick="portalApp.openRecordVendorPerformanceModal('${v.vendorId}')">
                <i class="fa-solid fa-star text-warning"></i> Score
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Deactivate vendor" onclick="portalApp.deactivateVendor('${v.vendorId}')">
                <i class="fa-solid fa-user-xmark text-danger"></i> Deactivate
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="View vendor dossier" onclick="portalApp.openInventoryDossierModal('${v.vendorId}', 'vendor')">
                <i class="fa-solid fa-eye text-primary"></i>
              </button>
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

