  function renderInventoryIssueReturnTable() {
    const tbody = document.getElementById('inventoryIssueReturnTableBody');
    if (!tbody) return;
    const statusFilter = (document.getElementById('inventoryIssueStatusFilter')?.value) || 'all';
    const q = (document.getElementById('inventoryIssueSearchInput')?.value || '').toLowerCase().trim();

    let list = INVENTORY_ISSUE_RETURN_DATA.filter(i => {
      const matchStatus = statusFilter === 'all' || 
        i.returnStatus.toLowerCase().includes(statusFilter.toLowerCase());
      const matchQ = !q || 
        i.item.toLowerCase().includes(q) || 
        (i.issuedTo && i.issuedTo.toLowerCase().includes(q)) ||
        (i.recipient && i.recipient.toLowerCase().includes(q)) ||
        (i.logId && i.logId.toLowerCase().includes(q)) ||
        (i.issueId && i.issueId.toLowerCase().includes(q));
      return matchStatus && matchQ;
    });

    if (list.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" class="text-center py-4 text-muted"><i class="fa-solid fa-hand-holding-hand fa-2x mb-2 d-block"></i>No equipment handover logs match the selected criteria.</td></tr>';
      return;
    }

    tbody.innerHTML = list.map(i => {
      const statusBadge = (i.returnStatus.includes('Returned'))
        ? '<span class="portal-badge badge-success"><i class="fa-solid fa-circle-check mr-1"></i>Returned</span>'
        : (i.returnStatus.includes('Damage'))
        ? '<span class="portal-badge badge-danger"><i class="fa-solid fa-triangle-exclamation mr-1"></i>Damaged</span>'
        : (i.returnStatus.includes('Repair'))
        ? '<span class="portal-badge badge-warning" style="background:#fef3c7; color:#b45309;"><i class="fa-solid fa-wrench mr-1"></i>Under Repair</span>'
        : '<span class="portal-badge badge-primary"><i class="fa-solid fa-clock mr-1"></i>In Use</span>';

      return `
        <tr>
          <td>
            <div style="font-weight: 700; color: #1e3a8a;">${i.item}</div>
            <div class="text-muted font-monospace" style="font-size: 0.72rem;">${i.logId || i.issueId}</div>
          </td>
          <td>
            <div style="font-weight: 600; font-size: 0.82rem;">${i.issuedTo || i.recipient}</div>
            <div class="text-muted" style="font-size: 0.72rem;">${i.department || 'Academic Faculty'}</div>
          </td>
          <td><span class="small font-monospace">${i.issueDate}</span></td>
          <td><span class="small font-monospace text-primary">${i.expectedReturnDate || i.dueDate}</span></td>
          <td>
            <span class="small font-monospace ${i.actualReturnDate && i.actualReturnDate !== 'Pending' ? 'text-success fw-bold' : 'text-muted'}">${i.actualReturnDate || 'Pending'}</span>
          </td>
          <td>
            <span class="portal-badge ${i.condition && (i.condition.includes('Excellent') || i.condition.includes('Good')) ? 'badge-success' : i.condition && i.condition.includes('Broken') ? 'badge-danger' : 'badge-warning'}">${i.condition || 'Good'}</span>
          </td>
          <td style="max-width: 200px;">
            <div class="text-muted" style="font-size: 0.72rem; line-height: 1.3;">${i.maintenanceHistory || i.remarks || 'Standard audit clean.'}</div>
          </td>
          <td style="text-align: right; white-space: nowrap;">
            <div style="display: inline-flex; gap: 4px;">
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Issue equipment" onclick="portalApp.openIssueItemModal()">
                <i class="fa-solid fa-hand-holding"></i> Issue
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Record return" onclick="portalApp.openRecordItemReturnModal('${i.logId || i.issueId}')">
                <i class="fa-solid fa-inbox text-success"></i> Return
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Record damage / defect" onclick="portalApp.openRecordItemDamageModal('${i.logId || i.issueId}')">
                <i class="fa-solid fa-triangle-exclamation text-danger"></i> Damage
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Request repair" onclick="portalApp.requestItemRepair('${i.logId || i.issueId}')">
                <i class="fa-solid fa-wrench text-warning"></i> Repair
              </button>
              <button class="btn btn-outline" style="padding: 3px 7px; font-size: 0.72rem;" title="Close maintenance request" onclick="portalApp.closeItemMaintenanceRequest('${i.logId || i.issueId}')">
                <i class="fa-solid fa-check-circle text-primary"></i> Close
              </button>
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

