  function handleIssueItemSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const item = document.getElementById('issueM15AssetOrItem')?.value || 'Classroom Equipment';
    const recipient = document.getElementById('issueM15IssuedTo')?.value || 'Faculty Member';
    const dept = document.getElementById('issueM15Dept')?.value || 'Academic Department';
    const iDate = document.getElementById('issueM15IssueDate')?.value || '2026-11-01';
    const rDate = document.getElementById('issueM15ExpectedReturn')?.value || '2026-11-15';
    const cond = document.getElementById('issueM15Condition')?.value || 'Good Condition';
    const remarks = document.getElementById('issueM15Remarks')?.value || 'Academic instruction checkout';

    const logId = 'ISS-2026-0' + (INVENTORY_ISSUE_RETURN_DATA.length + 107);
    const newLog = {
      logId: logId,
      issueId: logId,
      item: item,
      issuedTo: recipient,
      recipient: recipient,
      department: dept,
      quantity: '1 Unit',
      issueDate: iDate,
      expectedReturnDate: rDate,
      dueDate: rDate,
      actualReturnDate: 'Pending',
      condition: cond,
      maintenanceHistory: 'Checked out in ' + cond,
      returnStatus: 'In Use / Active',
      statusClass: 'badge-primary',
      issuedBy: 'Store In-charge Sri P. Appa Rao',
      remarks: remarks
    };

    INVENTORY_ISSUE_RETURN_DATA.unshift(newLog);
    closeModal('issueItemModal');
    renderInventoryIssueReturnTable();
    showToast('Equipment Issued', logId + ': ' + item + ' issued to ' + recipient + ' till ' + rDate + '.', 'success');
  }

  function openRecordItemReturnModal(logId) {
    const i = (logId ? INVENTORY_ISSUE_RETURN_DATA.find(x => x.logId === logId || x.issueId === logId) : null) || INVENTORY_ISSUE_RETURN_DATA[0];
    const form = document.getElementById('recordItemReturnForm');
    if (form) form.reset();

    const idInput = document.getElementById('returnM15LogId');
    if (idInput) idInput.value = i ? (i.logId || i.issueId) : '';
    const itemDisp = document.getElementById('returnM15ItemDisplay');
    if (itemDisp) itemDisp.textContent = i ? ((i.logId || i.issueId) + ': ' + i.item + ' [Issued to ' + (i.issuedTo || i.recipient) + ']') : '';

    openModal('recordItemReturnModal');
  }

  function handleRecordItemReturnSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const id = document.getElementById('returnM15LogId')?.value;
    const date = document.getElementById('returnM15ActualDate')?.value || new Date().toISOString().slice(0, 10);
    const cond = document.getElementById('returnM15Condition')?.value || 'Good Condition';
    const notes = document.getElementById('returnM15Notes')?.value || 'Returned and verified';

    const i = INVENTORY_ISSUE_RETURN_DATA.find(x => x.logId === id || x.issueId === id);
    if (i) {
      i.actualReturnDate = date;
      i.condition = cond;
      i.returnStatus = 'Returned in ' + cond;
      i.maintenanceHistory = 'Returned on ' + date + ' (' + cond + '). Notes: ' + notes;
      showToast('Return Recorded', 'Accepted return for ' + i.item + ' from ' + (i.issuedTo || i.recipient) + '. Status cleared.', 'success');
    }
    closeModal('recordItemReturnModal');
    renderInventoryIssueReturnTable();
  }

