  function closeItemMaintenanceRequest(logId) {
    const i = INVENTORY_ISSUE_RETURN_DATA.find(x => x.logId === logId || x.issueId === logId);
    if (i) {
      i.returnStatus = 'Maintenance Closed / Restored';
      i.condition = 'Good Condition (Restored)';
      i.maintenanceHistory = i.maintenanceHistory + ' • Maintenance closed; fitness certified by Store In-charge.';
      renderInventoryIssueReturnTable();
      showToast('Maintenance Closed', 'Repairs completed and verified for ' + i.item + '. Returned to active inventory pool.', 'success');
    }
  }

  function openNewInventoryModal(category) {
    if (category === 'asset') {
      openAddAssetModal();
    } else if (category === 'stock') {
      openReceiveStockModal();
    } else if (category === 'purchase') {
      openCreatePurchaseRequestModal();
    } else if (category === 'vendor') {
      openAddVendorModal();
    } else if (category === 'issue') {
      openIssueItemModal();
    } else if (category === 'maintenance') {
      openRecordAssetMaintenanceModal();
    } else {
      openAddAssetModal();
    }
  }

  
