  function exportInventoryAssetsCSV() {
    let csv = 'Asset ID,Asset Name,Category,Serial Number,Purchase Date,Purchase Value,Location,Assigned Department,Condition,Warranty,Status\n';
    INVENTORY_ASSETS_DATA.forEach(a => {
      csv += `"${a.assetId}","${a.name}","${a.category}","${a.serialNo || 'N/A'}","${a.purchaseDate}","${a.purchaseValue || a.value}","${a.location}","${a.assignedDepartment || 'General'}","${a.condition}","${a.warranty}","${a.status || 'In Service'}"\n`;
    });
    downloadCSV(csv, 'SriVidya_Capital_Asset_Register_' + new Date().toISOString().slice(0, 10) + '.csv');
    showToast('Asset Register Exported', 'Exported capital assets register to CSV.', 'success');
  }

