  // Student Leave Requests Rendering
  // User Requirement: Student, class, guardian, dates, reason and approval status
  function renderStudentLeaves(data) {
    const list = data || STUDENT_LEAVES_DATA;
    const tbody = document.getElementById('studentLeavesTableBody');
    if (!tbody) return;

    if (list.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" class="text-center p-4 text-muted"><i class="fa-solid fa-circle-info mr-1"></i> No student leave requests match the selected criteria.</td></tr>';
      return;
    }

    tbody.innerHTML = list.map(item => {
      let badgeCls = 'badge-primary';
      if ((item.ground || '').includes('Medical')) badgeCls = 'badge-danger';
      else if ((item.ground || '').includes('Sick')) badgeCls = 'badge-warning';
      else if ((item.ground || '').includes('Sports')) badgeCls = 'badge-success';
      else if ((item.ground || '').includes('Gate Pass')) badgeCls = 'badge-info';

      const isApproved = item.status === 'Approved' || (item.status || '').includes('Issued');
      const isRejected = item.status === 'Rejected';
      let statusBadgeCls = 'badge-warning';
      let statusIcon = 'fa-clock';
      if (isApproved) {
        statusBadgeCls = 'badge-success';
        statusIcon = 'fa-circle-check';
      } else if (isRejected) {
        statusBadgeCls = 'badge-danger';
        statusIcon = 'fa-circle-xmark';
      } else if (item.status === 'Parent Verified') {
        statusBadgeCls = 'badge-primary';
        statusIcon = 'fa-user-check';
      }

      const sourceTag = item.source || 'Parent Portal (Online)';

      return `
        <tr id="student-leave-row-${item.slipId}">
          <td>
            <strong style="color: #0f172a; font-size: 0.88rem; display: block;">${item.name}</strong>
            <div style="font-size: 0.74rem; color: #64748b; margin-top: 2px;">
              Adm: <span class="font-mono" style="font-weight: 700;">${item.admNo}</span> &bull; Roll: <span style="font-weight: 700;">${item.roll}</span>
            </div>
          </td>
          <td>
            <span class="portal-badge badge-neutral" style="font-weight: 800; font-size: 0.78rem;">
              ${item.class}
            </span>
          </td>
          <td>
            <strong style="color: #1e293b; font-size: 0.84rem; display: block;">${item.parent || item.guardian}</strong>
            <div style="margin-top: 3px;">
              <a href="tel:${item.phone}" class="text-primary font-weight-bold" style="text-decoration:none; font-size: 0.77rem; display: inline-flex; align-items: center; gap: 4px;">
                <i class="fa-solid fa-phone"></i> ${item.phone}
              </a>
            </div>
          </td>
          <td>
            <strong style="font-size: 0.84rem; color: #0f172a; display: block;">${item.dates}</strong>
            <div style="font-size: 0.73rem; color: #64748b; margin-top: 2px;">
              <i class="fa-solid fa-calendar-day mr-1"></i> ${item.daysRequested || 'Authorized Slip'}
            </div>
          </td>
          <td>
            <span class="portal-badge ${badgeCls}" style="font-size: 0.72rem; margin-bottom: 3px; display: inline-block; font-weight: 700;">
              ${item.ground || 'General'}
            </span>
            <div style="font-size: 0.82rem; color: #334155; line-height: 1.35;">
              ${item.reason}
            </div>
          </td>
          <td>
            <div style="font-size: 0.82rem; color: #1e293b; font-weight: 600;">${item.requestDate || '2026-09-24'}</div>
            <span class="portal-badge badge-neutral" style="font-size: 0.68rem; margin-top: 3px; display: inline-block;">
              <i class="fa-solid fa-database mr-1"></i> ${sourceTag}
            </span>
          </td>
          <td>
            <span class="portal-badge ${item.supportingDocs && item.supportingDocs.includes('Verified') ? 'badge-success' : 'badge-warning'}" style="font-size: 0.72rem;">
              <i class="fa-solid ${item.supportingDocs && item.supportingDocs.includes('Verified') ? 'fa-file-shield' : 'fa-paperclip'} mr-1"></i> ${item.supportingDocs || 'Parent Signed Slip'}
            </span>
          </td>
          <td>
            <span class="portal-badge ${statusBadgeCls}" style="font-weight: 800; font-size: 0.75rem; display: inline-block;">
              <i class="fa-solid ${statusIcon} mr-1"></i> ${item.status}
            </span>
          </td>
          <td style="text-align: center;">
            <div class="table-action-btns" style="justify-content: center; gap: 0.25rem; display: flex; flex-wrap: wrap;">
              ${item.status !== 'Parent Verified' && item.status !== 'Approved' ? `
                <button class="btn btn-secondary btn-sm" onclick="portalApp.verifyStudentLeaveRequest('${item.slipId}')" title="Verify Guardian Contact / Written Note" style="padding: 0.25rem 0.45rem; font-size: 0.72rem;">
                  <i class="fa-solid fa-phone-volume mr-1"></i> Verify
                </button>
              ` : ''}
              ${!isApproved ? `
                <button class="btn btn-success btn-sm" onclick="portalApp.approveStudentLeave('${item.slipId}')" title="Approve Leave" style="padding: 0.25rem 0.45rem; font-size: 0.72rem;">
                  <i class="fa-solid fa-check mr-1"></i> Approve
                </button>
              ` : ''}
              ${!isRejected ? `
                <button class="btn btn-danger btn-sm" onclick="portalApp.rejectStudentLeave('${item.slipId}')" title="Reject Request" style="padding: 0.25rem 0.45rem; font-size: 0.72rem;">
                  <i class="fa-solid fa-xmark mr-1"></i> Reject
                </button>
              ` : ''}
              <button class="btn btn-primary btn-sm" onclick="portalApp.notifyStudentGuardian('${item.slipId}')" title="Send SMS/WhatsApp notification to guardian" style="padding: 0.25rem 0.45rem; font-size: 0.72rem;">
                <i class="fa-solid fa-bell mr-1"></i> Notify
              </button>
              <button class="btn btn-secondary btn-sm" onclick="portalApp.viewStudentLeaveHistory('${item.admNo}', '${item.name}')" title="View Student Leave History" style="padding: 0.25rem 0.45rem; font-size: 0.72rem;">
                <i class="fa-solid fa-history mr-1"></i> History
              </button>
              <button class="btn btn-secondary btn-sm" onclick="portalApp.printStudentSlip('${item.slipId}')" title="Print Authorized Leave Slip" style="padding: 0.25rem 0.45rem; font-size: 0.72rem;">
                <i class="fa-solid fa-print mr-1"></i> Slip
              </button>
            </div>
          </td>
        </tr>
      `;
    }).join('');

    const badge = document.getElementById('studentLeaveTabBadge');
    if (badge) badge.textContent = list.length;
    const sideBadge = document.getElementById('sidebarStudentLeaveBadge');
    if (sideBadge) sideBadge.textContent = list.length;
    const statBadge = document.getElementById('statStudentSlipsCount');
    if (statBadge) statBadge.textContent = list.length;
  }

