  function handleSubmitWalkInParentLeave(e) {
    e.preventDefault();
    const rawStudent = document.getElementById('walkInStudentSelect').value;
    if (!rawStudent) {
      showToast('Please select a student', 'warning');
      return;
    }
    const [admNo, name, className, roll] = rawStudent.split('|');
    const guardian = document.getElementById('walkInGuardianName').value.trim();
    const phone = document.getElementById('walkInGuardianPhone').value.trim();
    const dates = document.getElementById('walkInLeaveDates').value.trim();
    const leaveType = document.getElementById('walkInLeaveType').value;
    const reason = document.getElementById('walkInReason').value.trim();
    const docs = document.getElementById('walkInDocs').value;

    const nextSeq = (typeof STUDENT_LEAVES_DATA !== 'undefined' ? STUDENT_LEAVES_DATA.length : 14) + 1;
    const slipId = `SLP-2026-${String(nextSeq).padStart(3, '0')}`;
    const todayStr = new Date().toISOString().split('T')[0];

    const newSlip = {
      slipId: slipId,
      admNo: admNo,
      name: name,
      class: className,
      roll: roll,
      guardian: guardian,
      parent: guardian,
      phone: phone,
      dates: dates,
      daysRequested: 'Per Request Slip',
      ground: leaveType,
      reason: reason,
      requestDate: todayStr,
      supportingDocs: docs,
      status: 'Parent Verified',
      source: 'Office / Walk-In Parent'
    };

    STUDENT_LEAVES_DATA.unshift(newSlip);
    renderStudentLeaves();
    closeModal('submitWalkInParentLeaveModal');
    showToast(`Walk-in leave request lodged on behalf of ${guardian} for student ${name}. Unified record created.`, 'success');
  }

  function openRecordOfflineStudentLeaveModal() {
    const sel = document.getElementById('offlineStudentSelect');
    if (sel) {
      sel.innerHTML = `
        <option value="">-- Select Student from Register --</option>
        <option value="SV-0082|P. Kiran Kumar|Class X-A|#1004">P. Kiran Kumar (Class X-A • #1004 • Adm: SV-0082)</option>
        <option value="SV-0012|G. Sai Teja|Class X-A|#1001">G. Sai Teja (Class X-A • #1001 • Adm: SV-0012)</option>
        <option value="SV-0105|K. Sai Tharun|Class IX-A|#904">K. Sai Tharun (Class IX-A • #904 • Adm: SV-0105)</option>
        <option value="SV-0091|M. Sravanthi|Class IX-A|#901">M. Sravanthi (Class IX-A • #901 • Adm: SV-0091)</option>
        <option value="SV-0144|CH. Karthik|Class VIII-A|#803">CH. Karthik (Class VIII-A • #803 • Adm: SV-0144)</option>
        <option value="SV-0201|B. Tarun Reddy|Class VIII-A|#808">B. Tarun Reddy (Class VIII-A • #808 • Adm: SV-0201)</option>
        <option value="SV-0255|S. Bhavana|Class VII-A|#701">S. Bhavana (Class VII-A • #701 • Adm: SV-0255)</option>
      `;
    }
    openModal('recordOfflineStudentLeaveModal');
  }

  function handleRecordOfflineStudentLeave(e) {
    e.preventDefault();
    const rawStudent = document.getElementById('offlineStudentSelect').value;
    if (!rawStudent) {
      showToast('Please select a student', 'warning');
      return;
    }
    const [admNo, name, className, roll] = rawStudent.split('|');
    const slipRef = document.getElementById('offlineSlipRef').value.trim();
    const dates = document.getElementById('offlineLeaveDates').value.trim();
    const reason = document.getElementById('offlineReason').value.trim();
    const guardianVerified = document.getElementById('offlineGuardianVerified').checked;

    const nextSeq = (typeof STUDENT_LEAVES_DATA !== 'undefined' ? STUDENT_LEAVES_DATA.length : 14) + 1;
    const slipId = slipRef || `SLP-2026-${String(nextSeq).padStart(3, '0')}`;
    const todayStr = new Date().toISOString().split('T')[0];

    const newSlip = {
      slipId: slipId,
      admNo: admNo,
      name: name,
      class: className,
      roll: roll,
      guardian: 'Parent Written Slip Filed',
      parent: 'Parent Written Slip Filed',
      phone: 'Verified from School Records',
      dates: dates,
      daysRequested: '1 Day',
      ground: 'Offline Physical Slip',
      reason: reason,
      requestDate: todayStr,
      supportingDocs: 'Physical Paper Slip Filed in Office',
      status: guardianVerified ? 'Parent Verified' : 'Pending Verification',
      source: 'Offline Physical Slip'
    };

    STUDENT_LEAVES_DATA.unshift(newSlip);
    renderStudentLeaves();
    closeModal('recordOfflineStudentLeaveModal');
    showToast(`Offline paper slip ${slipId} recorded into authoritative leave register.`, 'success');
  }

  function verifyStudentLeaveRequest(slipId) {
    const slip = (typeof STUDENT_LEAVES_DATA !== 'undefined' ? STUDENT_LEAVES_DATA : []).find(s => s.slipId === slipId);
    if (!slip) return;
    slip.status = 'Parent Verified';
    renderStudentLeaves();
    showToast(`Leave request ${slipId} for ${slip.name} verified with guardian contact (${slip.phone}).`, 'success');
  }

  function approveStudentLeave(slipId) {
    const slip = (typeof STUDENT_LEAVES_DATA !== 'undefined' ? STUDENT_LEAVES_DATA : []).find(s => s.slipId === slipId);
    if (!slip) return;
    slip.status = 'Approved';

    if (!state.leaveHistory) state.leaveHistory = [];
    const todayStr = new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
    state.leaveHistory.unshift({
      id: `LEV-${slip.slipId}`,
      date: todayStr,
      applicant: slip.name,
      role: 'Student',
      deptOrClass: `${slip.class} • ${slip.roll}`,
      category: 'Student',
      type: slip.ground || 'Student Leave',
      dates: slip.dates,
      duration: slip.daysRequested || '1 Day',
      reason: slip.reason,
      approver: 'Vice Principal Sri Navva Anand',
      decision: 'Approved',
      status: 'Approved',
      recordedDate: todayStr,
      correctionHistory: []
    });

    renderStudentLeaves();
    renderLeaveHistoryRegister();
    showToast(`Student leave slip ${slipId} for ${slip.name} approved by Vice Principal Sri Navva Anand. Attendance updated.`, 'success');
  }

  function rejectStudentLeave(slipId) {
    const slip = (typeof STUDENT_LEAVES_DATA !== 'undefined' ? STUDENT_LEAVES_DATA : []).find(s => s.slipId === slipId);
    if (!slip) return;
    slip.status = 'Rejected';

    if (!state.leaveHistory) state.leaveHistory = [];
    const todayStr = new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
    state.leaveHistory.unshift({
      id: `LEV-${slip.slipId}`,
      date: todayStr,
      applicant: slip.name,
      role: 'Student',
      deptOrClass: `${slip.class} • ${slip.roll}`,
      category: 'Student',
      type: slip.ground || 'Student Leave',
      dates: slip.dates,
      duration: slip.daysRequested || '1 Day',
      reason: slip.reason + ' [Rejected by Vice Principal]',
      approver: 'Vice Principal Sri Navva Anand',
      decision: 'Rejected',
      status: 'Rejected',
      recordedDate: todayStr,
      correctionHistory: []
    });

    renderStudentLeaves();
    renderLeaveHistoryRegister();
    showToast(`Student leave slip ${slipId} marked Rejected.`, 'warning');
  }

  function notifyStudentGuardian(slipId) {
    const slip = (typeof STUDENT_LEAVES_DATA !== 'undefined' ? STUDENT_LEAVES_DATA : []).find(s => s.slipId === slipId);
    if (!slip) return;
    const guardian = slip.guardian || slip.parent || 'Guardian';
    showToast(`Notification SMS dispatched to ${guardian} (${slip.phone}): "Leave status for ${slip.name} is ${slip.status}. Sri Vidya High School"`, 'info');
  }

  function viewStudentLeaveHistory(admNo, name) {
    switchSubTab('history');
    const searchInput = document.getElementById('leaveHistorySearchInput');
    const catFilter = document.getElementById('leaveHistoryCategoryFilter');
    if (searchInput) searchInput.value = name || admNo;
    if (catFilter) catFilter.value = 'Student';
    setHistoryStatusFilter('all');
    renderLeaveHistoryRegister();
    showToast(`Showing leave history for ${name} (${admNo})`, 'info');
  }

  function filterStudentLeaveSlips() {
    const searchVal = (document.getElementById('studentLeaveSearch')?.value || '').toLowerCase().trim();
    const classVal = document.getElementById('studentLeaveClassFilter')?.value || 'all';

    let filtered = STUDENT_LEAVES_DATA;
    if (classVal !== 'all') {
      filtered = filtered.filter(item => item.class === classVal);
    }
    if (searchVal) {
      filtered = filtered.filter(item =>
        item.name.toLowerCase().includes(searchVal) ||
        item.admNo.toLowerCase().includes(searchVal) ||
        item.slipId.toLowerCase().includes(searchVal) ||
        ((item.parent || item.guardian) && (item.parent || item.guardian).toLowerCase().includes(searchVal)) ||
        item.reason.toLowerCase().includes(searchVal)
      );
    }
    renderStudentLeaves(filtered);
  }

  function printStudentLeaveRegister() {
    window.print();
  }

  var currentHistoryStatusFilter = 'all';

  function setHistoryStatusFilter(status) {
    currentHistoryStatusFilter = status;
    const buttons = ['btnHistFilterAll', 'btnHistFilterApproved', 'btnHistFilterRejected', 'btnHistFilterCancelled', 'btnHistFilterPending'];
    buttons.forEach(bId => {
      const btn = document.getElementById(bId);
      if (btn) {
        if ((status === 'all' && bId === 'btnHistFilterAll') ||
            (status === 'Approved' && bId === 'btnHistFilterApproved') ||
            (status === 'Rejected' && bId === 'btnHistFilterRejected') ||
            (status === 'Cancelled' && bId === 'btnHistFilterCancelled') ||
            (status === 'Pending' && bId === 'btnHistFilterPending')) {
          btn.classList.add('active');
        } else {
          btn.classList.remove('active');
        }
      }
    });
    renderLeaveHistoryRegister();
  }

  function filterLeaveHistory() {
    renderLeaveHistoryRegister();
  }

  function renderLeaveHistoryRegister() {
    const tbody = document.getElementById('leaveHistoryTableBody');
    if (!tbody) return;

    const data = state.leaveHistory || [];

    const allCount = data.length;
    const appCount = data.filter(d => (d.decision || d.status) === 'Approved').length;
    const rejCount = data.filter(d => (d.decision || d.status) === 'Rejected').length;
    const canCount = data.filter(d => (d.decision || d.status) === 'Cancelled').length;
    const penCount = data.filter(d => (d.decision || d.status) === 'Pending').length;

    const elAll = document.getElementById('histCountAll');
    if (elAll) elAll.textContent = allCount;
    const elApp = document.getElementById('histCountApproved');
    if (elApp) elApp.textContent = appCount;
    const elRej = document.getElementById('histCountRejected');
    if (elRej) elRej.textContent = rejCount;
    const elCan = document.getElementById('histCountCancelled');
    if (elCan) elCan.textContent = canCount;
    const elPen = document.getElementById('histCountPending');
    if (elPen) elPen.textContent = penCount;
    const tabBadge = document.getElementById('historyLeaveTabBadge');
    if (tabBadge) tabBadge.textContent = allCount;
    const statLedger = document.getElementById('statHistoryLedgerCount');
    if (statLedger) statLedger.textContent = allCount;

    const searchVal = (document.getElementById('leaveHistorySearchInput')?.value || '').toLowerCase().trim();
    const catVal = document.getElementById('leaveHistoryCategoryFilter')?.value || 'all';

    let filtered = data;
    if (currentHistoryStatusFilter !== 'all') {
      filtered = filtered.filter(item => (item.decision || item.status || '').toLowerCase() === currentHistoryStatusFilter.toLowerCase());
    }
    if (catVal !== 'all') {
      filtered = filtered.filter(item => (item.category || '').toLowerCase() === catVal.toLowerCase());
    }
    if (searchVal) {
      filtered = filtered.filter(item =>
        (item.id || '').toLowerCase().includes(searchVal) ||
        (item.applicant || '').toLowerCase().includes(searchVal) ||
        (item.deptOrClass || '').toLowerCase().includes(searchVal) ||
        (item.reason || '').toLowerCase().includes(searchVal)
      );
    }

    if (filtered.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" class="text-center p-4 text-muted"><i class="fa-solid fa-circle-info mr-1"></i> No leave history records match the selected filter.</td></tr>';
      return;
    }

    tbody.innerHTML = filtered.map(h => {
      const decision = h.decision || h.status || 'Approved';
      let statusBadge = 'badge-success';
      let statusIcon = 'fa-circle-check';
      if (decision === 'Rejected') {
        statusBadge = 'badge-danger';
        statusIcon = 'fa-circle-xmark';
      } else if (decision === 'Cancelled') {
        statusBadge = 'badge-neutral';
        statusIcon = 'fa-ban';
      } else if (decision === 'Pending') {
        statusBadge = 'badge-warning';
        statusIcon = 'fa-clock';
      }

      const hasCorrections = h.correctionHistory && Array.isArray(h.correctionHistory) && h.correctionHistory.length > 0;
      const correctionCount = hasCorrections ? h.correctionHistory.length : 0;
      const latestCorrection = hasCorrections ? h.correctionHistory[h.correctionHistory.length - 1] : null;

      return `
        <tr id="leave-history-row-${h.id}">
          <td>
            <div style="display: flex; align-items: center; gap: 0.5rem;">
              <span class="portal-badge ${h.category === 'Faculty' ? 'badge-primary' : 'badge-neutral'}" style="font-size: 0.68rem; padding: 2px 5px;">
                ${h.category}
              </span>
              <div>
                <strong style="color: #0f172a; font-size: 0.85rem; display: block;">${h.applicant}</strong>
                <div style="font-size: 0.72rem; color: #64748b;">${h.deptOrClass} &bull; <span class="font-mono">${h.id}</span></div>
              </div>
            </div>
          </td>
          <td>
            <span class="portal-badge badge-neutral" style="font-weight: 700; font-size: 0.75rem;">
              ${h.type}
            </span>
          </td>
          <td>
            <strong style="font-size: 0.82rem; color: #1e293b; display: block;">${h.dates}</strong>
            <small class="text-muted"><i class="fa-solid fa-clock mr-1"></i>${h.duration || '1 Day'}</small>
          </td>
          <td>
            <span class="portal-badge ${statusBadge}" style="font-weight: 800; font-size: 0.75rem;">
              <i class="fa-solid ${statusIcon} mr-1"></i> ${decision}
            </span>
          </td>
          <td>
            <div style="font-size: 0.80rem; font-weight: 600; color: #1e40af;">
              <i class="fa-solid fa-signature mr-1"></i> ${h.approver}
            </div>
          </td>
          <td>
            <span style="font-size: 0.80rem; color: #334155; font-weight: 500;">${h.recordedDate || h.date}</span>
          </td>
          <td>
            ${hasCorrections ? `
              <div style="font-size: 0.75rem;">
                <span class="portal-badge badge-warning" style="font-weight: 700; font-size: 0.68rem; margin-bottom: 2px; display: inline-block;">
                  <i class="fa-solid fa-pen-to-square mr-1"></i> ${correctionCount} Revision(s)
                </span>
                <div style="color: #475569; line-height: 1.25; font-size: 0.72rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 220px;" title="${latestCorrection.auditNote}">
                  &ldquo;${latestCorrection.auditNote}&rdquo;
                </div>
              </div>
            ` : `
              <span class="portal-badge badge-neutral" style="font-size: 0.72rem; color: #64748b;">
                <i class="fa-solid fa-shield-check mr-1 text-emerald"></i> Original (0 Corrections)
              </span>
            `}
          </td>
          <td style="text-align: center;">
            <div class="table-action-btns" style="justify-content: center; gap: 0.3rem; display: flex; flex-wrap: nowrap;">
              <button class="btn btn-secondary btn-sm" onclick="portalApp.viewLeaveHistoryDetails('${h.id}')" title="View Full Authorized Memo" style="padding: 0.25rem 0.5rem; font-size: 0.74rem;">
                <i class="fa-solid fa-eye mr-1"></i> Details
              </button>
              <button class="btn btn-warning btn-sm" onclick="portalApp.openCorrectLeaveHistoryModal('${h.id}')" title="Designated Correction Workflow" style="padding: 0.25rem 0.5rem; font-size: 0.74rem;">
                <i class="fa-solid fa-file-pen mr-1"></i> Correct
              </button>
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

  function viewLeaveHistoryDetails(id) {
    const h = (state.leaveHistory || []).find(x => String(x.id) === String(id));
    if (!h) {
      showToast('Leave record not found in archive: ' + id, 'warning');
      return;
    }
    const body = document.getElementById('leaveHistoryDetailsBody');
    if (!body) return;

    const decision = h.decision || h.status || 'Approved';
    let badgeCls = 'badge-success';
    if (decision === 'Rejected') badgeCls = 'badge-danger';
    else if (decision === 'Cancelled') badgeCls = 'badge-neutral';
    else if (decision === 'Pending') badgeCls = 'badge-warning';

    const corrections = h.correctionHistory || [];

    body.innerHTML = `
      <div style="background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 8px; padding: 1.25rem; margin-bottom: 1.25rem;">
        <div style="display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 1rem;">
          <div>
            <span class="portal-badge ${h.category === 'Faculty' ? 'badge-primary' : 'badge-neutral'}" style="font-size: 0.75rem; margin-bottom: 0.35rem; display: inline-block;">
              ${h.category} Record &bull; ${h.id}
            </span>
            <h3 style="margin: 0; font-size: 1.2rem; color: #0f172a; font-weight: 800;">${h.applicant}</h3>
            <p style="margin: 0.2rem 0 0 0; color: #64748b; font-size: 0.85rem;">
              ${h.deptOrClass} &bull; Recorded on <strong>${h.recordedDate || h.date}</strong>
            </p>
          </div>
          <div style="text-align: right;">
            <span class="portal-badge ${badgeCls}" style="font-size: 0.85rem; padding: 0.35rem 0.75rem; font-weight: 800;">
              ${decision}
            </span>
          </div>
        </div>

        <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 1rem; border-top: 1px solid #e2e8f0; padding-top: 1rem;">
          <div>
            <small class="text-muted" style="text-transform: uppercase; font-size: 0.7rem; font-weight: 700; letter-spacing: 0.5px;">Leave Classification</small>
            <div style="font-weight: 700; color: #0f172a; font-size: 0.92rem;">${h.type}</div>
          </div>
          <div>
            <small class="text-muted" style="text-transform: uppercase; font-size: 0.7rem; font-weight: 700; letter-spacing: 0.5px;">Sanctioned Dates</small>
            <div style="font-weight: 700; color: #0f172a; font-size: 0.92rem;">${h.dates} (${h.duration || '1 Day'})</div>
          </div>
          <div>
            <small class="text-muted" style="text-transform: uppercase; font-size: 0.7rem; font-weight: 700; letter-spacing: 0.5px;">Authorizing Officer</small>
            <div style="font-weight: 700; color: #1e40af; font-size: 0.92rem;">${h.approver}</div>
          </div>
        </div>

        <div style="margin-top: 1rem; padding-top: 1rem; border-top: 1px solid #e2e8f0;">
          <small class="text-muted" style="text-transform: uppercase; font-size: 0.7rem; font-weight: 700; letter-spacing: 0.5px;">Reason & Justification</small>
          <div style="background: #fff; padding: 0.75rem; border-radius: 6px; border: 1px solid #e2e8f0; margin-top: 0.35rem; font-size: 0.88rem; color: #334155;">
            ${h.reason}
          </div>
        </div>
      </div>

      <div>
        <h4 style="font-size: 0.95rem; font-weight: 800; color: #0f172a; margin-bottom: 0.75rem; display: flex; align-items: center; justify-content: space-between;">
          <span><i class="fa-solid fa-clock-rotate-left mr-1 text-primary"></i> Designated Correction Audit Trail</span>
          <span class="portal-badge badge-neutral" style="font-size: 0.72rem;">${corrections.length} Correction(s)</span>
        </h4>
        ${corrections.length === 0 ? `
          <div style="background: #f0fdf4; border: 1px solid #bbf7d0; border-radius: 6px; padding: 0.85rem; color: #166534; font-size: 0.82rem;">
            <i class="fa-solid fa-shield-check mr-1"></i> Original determination remains intact. No post-facto corrections or modifications have been filed for this entry.
          </div>
        ` : `
          <div style="display: flex; flex-direction: column; gap: 0.75rem;">
            ${corrections.map((c, idx) => `
              <div style="background: #fff; border: 1px solid #e2e8f0; border-left: 4px solid #f59e0b; border-radius: 6px; padding: 0.85rem; font-size: 0.82rem;">
                <div style="display: flex; justify-content: space-between; margin-bottom: 0.4rem;">
                  <strong style="color: #b45309;"><i class="fa-solid fa-pen-nib mr-1"></i> Correction #${idx + 1} (${c.correctionId || 'AUD-MOD'})</strong>
                  <span class="text-muted">${c.date} &bull; ${c.modifiedBy}</span>
                </div>
                <div style="margin-bottom: 0.4rem; color: #334155;">
                  <strong>Audit Note:</strong> ${c.auditNote}
                </div>
                <div style="background: #f8fafc; padding: 0.45rem 0.65rem; border-radius: 4px; font-size: 0.75rem; color: #64748b; font-family: monospace;">
                  Previous: [Type: ${c.oldValues?.type}, Dates: ${c.oldValues?.dates}, Decision: ${c.oldValues?.decision}] &rarr;
                  Updated: [Type: ${c.newValues?.type}, Dates: ${c.newValues?.dates}, Decision: ${c.newValues?.decision}]
                </div>
              </div>
            `).join('')}
          </div>
        `}
      </div>
    `;

    openModal('viewLeaveHistoryDetailsModal');
  }

  function openCorrectLeaveHistoryModal(id) {
    const h = (state.leaveHistory || []).find(x => String(x.id) === String(id));
    if (!h) {
      showToast('Record not found: ' + id, 'warning');
      return;
    }
    document.getElementById('corrHistId').value = h.id;
    document.getElementById('corrHistRecordDisplay').textContent = `${h.id} • ${h.applicant} (${h.category} - ${h.deptOrClass})`;
    document.getElementById('corrHistLeaveType').value = h.type;
    document.getElementById('corrHistDates').value = h.dates;
    document.getElementById('corrHistDecision').value = h.decision || h.status || 'Approved';
    document.getElementById('corrHistAuditNote').value = '';
    openModal('correctLeaveHistoryModal');
  }

  function handleCorrectLeaveHistorySubmit(e) {
    e.preventDefault();
    const id = document.getElementById('corrHistId').value;
    const newType = document.getElementById('corrHistLeaveType').value;
    const newDates = document.getElementById('corrHistDates').value;
    const newDecision = document.getElementById('corrHistDecision').value;
    const auditNote = document.getElementById('corrHistAuditNote').value.trim();

    const h = (state.leaveHistory || []).find(x => String(x.id) === String(id));
    if (!h) {
      showToast('Record not found', 'danger');
      return;
    }

    if (!h.correctionHistory) h.correctionHistory = [];

    const oldValues = {
      type: h.type,
      dates: h.dates,
      decision: h.decision || h.status
    };

    h.correctionHistory.push({
      correctionId: 'CORR-' + Date.now().toString().slice(-4),
      date: new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }),
      modifiedBy: 'Principal Smt. Gorle Varalakshmi',
      oldValues: oldValues,
      newValues: {
        type: newType,
        dates: newDates,
        decision: newDecision
      },
      auditNote: auditNote
    });

    h.type = newType;
    h.dates = newDates;
    h.decision = newDecision;
    h.status = newDecision;

    renderLeaveHistoryRegister();
    closeModal('correctLeaveHistoryModal');
    showToast(`Official correction recorded in statutory audit ledger for ${id}.`, 'success');
  }

  function exportLeaveHistoryCSV() {
    const data = state.leaveHistory || [];
    if (data.length === 0) {
      showToast('No leave history available to export', 'warning');
      return;
    }
    const headers = ['Record ID', 'Applicant', 'Category', 'Role or Class', 'Leave Type', 'Dates', 'Duration', 'Decision', 'Approver', 'Recorded Date', 'Corrections Count', 'Reason'];
    const rows = data.map(h => [
      `"${h.id}"`,
      `"${(h.applicant || '').replace(/"/g, '""')}"`,
      `"${h.category || ''}"`,
      `"${(h.deptOrClass || '').replace(/"/g, '""')}"`,
      `"${h.type || ''}"`,
      `"${h.dates || ''}"`,
      `"${h.duration || ''}"`,
      `"${h.decision || h.status || ''}"`,
      `"${(h.approver || '').replace(/"/g, '""')}"`,
      `"${h.recordedDate || h.date || ''}"`,
      `"${(h.correctionHistory && h.correctionHistory.length) || 0}"`,
      `"${(h.reason || '').replace(/"/g, '""')}"`
    ]);
    const csvContent = 'data:text/csv;charset=utf-8,' + [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement('a');
    link.setAttribute('href', encodedUri);
    link.setAttribute('download', `SriVidya_Leave_History_Register_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    showToast('Official Leave History Register exported as CSV.', 'success');
  }

