  // -------------------------------------------------------------------------
  // 1. RENDER EXAM SCHEDULE TABLE
  // -------------------------------------------------------------------------
  function renderExamScheduleTable() {
    const tbody = document.getElementById('examScheduleTableBody');
    if (!tbody) return;

    const termFilter = document.getElementById('examScheduleTermFilter')?.value || 'all';
    const classFilter = document.getElementById('examScheduleClassFilter')?.value || 'all';
    const statusFilter = document.getElementById('examScheduleStatusFilter')?.value || 'all';
    const searchVal = (document.getElementById('examScheduleSearchInput')?.value || '').toLowerCase().trim();

    const filtered = EXAM_SCHEDULE_PAPERS.filter(ex => {
      const matchTerm = termFilter === 'all' || ex.examName.toLowerCase().includes(termFilter.toLowerCase());
      const matchClass = classFilter === 'all' || ex.class.toLowerCase().includes(classFilter.toLowerCase()) || ex.class.toLowerCase().includes('all');
      const matchStatus = statusFilter === 'all' || ex.status.toLowerCase() === statusFilter.toLowerCase();
      const matchSearch = !searchVal ||
        ex.id.toLowerCase().includes(searchVal) ||
        ex.examName.toLowerCase().includes(searchVal) ||
        ex.academicYear.toLowerCase().includes(searchVal) ||
        ex.class.toLowerCase().includes(searchVal) ||
        ex.subject.toLowerCase().includes(searchVal) ||
        ex.paperCode.toLowerCase().includes(searchVal) ||
        ex.room.toLowerCase().includes(searchVal) ||
        ex.invigilators.toLowerCase().includes(searchVal);

      return matchTerm && matchClass && matchStatus && matchSearch;
    });

    // Update KPI count
    const kpiCount = document.getElementById('kpiScheduledPapersCount');
    if (kpiCount) kpiCount.innerText = filtered.length + ' Major Papers';

    if (filtered.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" class="text-center py-4 text-muted">No examination schedule records match your filter criteria.</td></tr>';
      return;
    }

    tbody.innerHTML = filtered.map(ex => {
      let statusBadge = 'badge-primary';
      if (ex.status === 'Published') statusBadge = 'badge-success';
      if (ex.status === 'Draft') statusBadge = 'badge-warning';
      if (ex.status === 'Completed') statusBadge = 'badge-secondary';

      return `
        <tr>
          <td>
            <div style="display:flex; flex-direction:column; gap:0.2rem;">
              <strong style="font-family:monospace; color:#2563eb; font-size:0.85rem;">${ex.id}</strong>
              <small style="color:#0f172a; font-weight:700; font-size:0.8rem;">${ex.examName}</small>
            </div>
          </td>
          <td>
            <div style="display:flex; flex-direction:column; gap:0.2rem;">
              <span class="profile-tag tag-primary" style="font-weight:700; font-size:0.75rem;">${ex.class}</span>
              <small class="text-muted" style="font-size:0.72rem;">AY ${ex.academicYear}</small>
            </div>
          </td>
          <td>
            <div style="display:flex; flex-direction:column; gap:0.2rem;">
              <strong style="color:#1e293b; font-size:0.86rem;">${ex.subject}</strong>
              <span class="portal-badge badge-neutral" style="font-family:monospace; font-size:0.7rem; align-self:flex-start;">${ex.paperCode}</span>
            </div>
          </td>
          <td>
            <div style="display:flex; flex-direction:column; gap:0.2rem;">
              <strong style="color:#0f172a; font-size:0.84rem;">${ex.date}</strong>
              <small class="text-muted"><i class="fa-regular fa-calendar-check"></i> ${ex.day}</small>
            </div>
          </td>
          <td>
            <div style="display:flex; flex-direction:column; gap:0.2rem;">
              <strong style="color:#0f172a; font-size:0.82rem;">${ex.startTime} – ${ex.endTime}</strong>
              <small style="color:#2563eb; font-size:0.72rem; font-weight:600;">${ex.session} (${ex.duration})</small>
            </div>
          </td>
          <td>
            <div style="font-size:0.82rem; color:#334155;">
              <i class="fa-solid fa-door-open text-amber mr-1"></i>
              <strong>${ex.room}</strong>
            </div>
          </td>
          <td style="text-align:center;">
            <div style="display:inline-flex; flex-direction:column; align-items:center;">
              <strong class="text-emerald" style="font-size:0.9rem;">${ex.maxMarks} Marks</strong>
              <small style="font-size:0.7rem; color:#475569;" title="${ex.passingCriteria}">${ex.passingCriteria.substring(0, 24)}...</small>
            </div>
          </td>
          <td>
            <div style="font-size:0.82rem; color:#1e293b;">
              <i class="fa-solid fa-user-shield text-primary mr-1"></i>
              <strong>${ex.invigilators}</strong>
            </div>
          </td>
          <td style="text-align:center;">
            <span class="portal-badge ${statusBadge}" style="font-size:0.72rem; font-weight:700;">${ex.status}</span>
          </td>
          <td style="text-align:center;">
            <div style="display:inline-flex; align-items:center; gap:0.3rem; justify-content:center;">
              <button type="button" class="btn btn-secondary btn-sm" style="padding:0.25rem 0.5rem; font-size:0.75rem;"
                onclick="portalApp.openEditExamSubjectModal('${ex.id}')" title="Edit Paper Details">
                <i class="fa-solid fa-pen-to-square"></i>
              </button>
              <button type="button" class="btn btn-danger btn-sm" style="padding:0.25rem 0.45rem; font-size:0.75rem;"
                onclick="portalApp.deleteExamPaper('${ex.id}')" title="Delete Paper">
                <i class="fa-solid fa-trash"></i>
              </button>
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

