  function handleCreateExaminationSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();

    const name = document.getElementById('newExamSeriesName')?.value || 'Term Examination';
    const year = document.getElementById('newExamAcademicYear')?.value || '2026–2027';
    const type = document.getElementById('newExamAssessmentType')?.value || 'Summative Assessment';
    const term = document.getElementById('newExamTerm')?.value || 'Term 1';
    const start = document.getElementById('newExamStartDate')?.value || '2026-10-24';
    const end = document.getElementById('newExamEndDate')?.value || '2026-10-31';
    const chief = document.getElementById('newExamChiefSuperintendent')?.value || 'Sri Navva Anand';
    const grading = document.getElementById('newExamGradingStandard')?.value || 'AP SCERT 8-Point Scale';
    const statusRadio = document.querySelector('input[name="newExamStatus"]:checked');
    const status = statusRadio ? statusRadio.value : 'Published';

    const newSeries = {
      id: 'SERIES-0' + (EXAM_SERIES_LIST.length + 1),
      name: name,
      academicYear: year,
      term: term,
      type: type,
      startDate: start,
      endDate: end,
      chiefSuperintendent: chief,
      gradingStandard: grading,
      status: status
    };

    EXAM_SERIES_LIST.push(newSeries);

    // Update Series Dropdown
    const seriesSelect = document.getElementById('examScheduleTermFilter');
    if (seriesSelect) {
      const opt = document.createElement('option');
      opt.value = name;
      opt.text = name;
      opt.selected = true;
      seriesSelect.appendChild(opt);
    }
    const seExamTitle = document.getElementById('seExamTitle');
    if (seExamTitle) {
      const opt2 = document.createElement('option');
      opt2.value = name;
      opt2.text = name;
      seExamTitle.appendChild(opt2);
    }

    // Update KPI
    const kpiTerm = document.getElementById('kpiAcademicTermDisplay');
    if (kpiTerm) kpiTerm.innerText = year + ' • ' + term;

    showToast('Examination Series Created: ' + name + ' (' + year + ')', 'success');
    closeModal('createExaminationModal');
    renderExamScheduleTable();
  }

