  function openEditExamSubjectModal(paperId) {
    const paper = EXAM_SCHEDULE_PAPERS.find(p => p.id === paperId);
    if (!paper) {
      showToast('Paper not found: ' + paperId, 'error');
      return;
    }

    const editId = document.getElementById('editExamPaperId');
    const seId = document.getElementById('seExamId');
    const seTitle = document.getElementById('seExamTitle');
    const seYear = document.getElementById('seAcademicYear');
    const seClass = document.getElementById('seClass');
    const seSubject = document.getElementById('seSubject');
    const seDate = document.getElementById('seExamDate');
    const seStart = document.getElementById('seStartTime');
    const seEnd = document.getElementById('seEndTime');
    const seRoom = document.getElementById('seRoom');
    const seMarks = document.getElementById('seMaxMarks');
    const sePass = document.getElementById('sePassingCriteria');
    const seInvig = document.getElementById('seInvigilator');
    const seStatus = document.getElementById('seStatus');

    if (editId) editId.value = paper.id;
    if (seId) seId.value = paper.id;
    if (seTitle) seTitle.value = paper.examName;
    if (seYear) seYear.value = paper.academicYear;
    if (seClass) seClass.value = paper.class;
    if (seSubject) seSubject.value = paper.subject + ' (' + paper.paperCode + ')';
    if (seDate) seDate.value = paper.date;
    if (seStart) seStart.value = paper.startTime.includes('09:30') ? '09:30' : '01:30';
    if (seEnd) seEnd.value = paper.endTime.includes('12:30') ? '12:30' : '04:30';
    if (seRoom) seRoom.value = paper.room;
    if (seMarks) seMarks.value = paper.maxMarks;
    if (sePass) sePass.value = paper.passingCriteria;
    if (seInvig) seInvig.value = paper.invigilators;
    if (seStatus) seStatus.value = paper.status;

    const delBtn = document.getElementById('btnDeleteExamPaper');
    if (delBtn) delBtn.style.display = 'inline-block';

    const banner = document.getElementById('examFormConflictBanner');
    if (banner) banner.style.display = 'none';

    openModal('scheduleExamModal');
  }

  function checkLivePaperConflict() {
    const date = document.getElementById('seExamDate')?.value;
    const room = document.getElementById('seRoom')?.value;
    const invigilator = document.getElementById('seInvigilator')?.value;
    const currentId = document.getElementById('editExamPaperId')?.value;

    const banner = document.getElementById('examFormConflictBanner');
    const bannerText = document.getElementById('examFormConflictBannerText');

    if (!date || !room) return;

    // Check room conflict
    const roomClash = EXAM_SCHEDULE_PAPERS.find(p => p.id !== currentId && p.date === date && p.room === room);
    if (roomClash) {
      if (banner && bannerText) {
        banner.style.display = 'block';
        bannerText.innerHTML = '<strong>Room Conflict Warning:</strong> ' + room + ' is already allocated to ' + roomClash.class + ' (' + roomClash.subject + ') on ' + date + '!';
      }
      return;
    }

    // Check invigilator clash
    if (invigilator) {
      const invigClash = EXAM_SCHEDULE_PAPERS.find(p => p.id !== currentId && p.date === date && p.invigilators === invigilator && p.room !== room);
      if (invigClash) {
        if (banner && bannerText) {
          banner.style.display = 'block';
          bannerText.innerHTML = '<strong>Invigilator Double-Booking:</strong> ' + invigilator + ' is already assigned to ' + invigClash.room + ' on ' + date + '!';
        }
        return;
      }
    }

    if (banner) banner.style.display = 'none';
  }

  function handleScheduleExamSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();

    const editId = document.getElementById('editExamPaperId')?.value;
    const examId = document.getElementById('seExamId')?.value || ('EX-2026-SA1-0' + (EXAM_SCHEDULE_PAPERS.length + 1));
    const examName = document.getElementById('seExamTitle')?.value || 'Summative Assessment 1 (SA-1)';
    const academicYear = document.getElementById('seAcademicYear')?.value || '2026–2027';
    const targetClass = document.getElementById('seClass')?.value || 'Class X-A';
    const subjectRaw = document.getElementById('seSubject')?.value || 'Mathematics (SSC-MTH-01)';
    const examDate = document.getElementById('seExamDate')?.value || '2026-10-24';
    const startTimeRaw = document.getElementById('seStartTime')?.value || '09:30';
    const endTimeRaw = document.getElementById('seEndTime')?.value || '12:30';
    const room = document.getElementById('seRoom')?.value || 'Main Hall 1 (Rooms 101-102)';
    const maxMarks = parseInt(document.getElementById('seMaxMarks')?.value || '100', 10);
    const passingCriteria = document.getElementById('sePassingCriteria')?.value || '35% (Min 35 Marks) / Grade D1';
    const invigilators = document.getElementById('seInvigilator')?.value || 'Sri Navva Anand & Smt. M. Sunitha';
    const status = document.getElementById('seStatus')?.value || 'Published';

    // Parse subject and code
    let subjectName = subjectRaw;
    let paperCode = 'SSC-GEN';
    const codeMatch = subjectRaw.match(/(.+?)s*\((.+?)\)/);
    if (codeMatch) {
      subjectName = codeMatch[1].trim();
      paperCode = codeMatch[2].trim();
    }

    // Format Day of Week
    const dObj = new Date(examDate + 'T00:00:00');
    const dayName = isNaN(dObj.getTime()) ? 'Friday' : dObj.toLocaleDateString('en-US', { weekday: 'long' });

    // Format Start & End AM/PM
    const formatTime = (tStr) => {
      if (!tStr) return '09:30 AM';
      const [h, m] = tStr.split(':');
      let hour = parseInt(h, 10);
      const ampm = hour >= 12 ? 'PM' : 'AM';
      if (hour > 12) hour -= 12;
      if (hour === 0) hour = 12;
      return (hour.toString().padStart(2, '0') + ':' + m + ' ' + ampm);
    };

    const startTimeFormatted = formatTime(startTimeRaw);
    const endTimeFormatted = formatTime(endTimeRaw);

    if (editId) {
      // Update existing paper
      const p = EXAM_SCHEDULE_PAPERS.find(item => item.id === editId);
      if (p) {
        p.examName = examName;
        p.academicYear = academicYear;
        p.class = targetClass;
        p.subject = subjectName;
        p.paperCode = paperCode;
        p.date = examDate;
        p.day = dayName;
        p.startTime = startTimeFormatted;
        p.endTime = endTimeFormatted;
        p.room = room;
        p.maxMarks = maxMarks;
        p.passingCriteria = passingCriteria;
        p.invigilators = invigilators;
        p.status = status;
        showToast('Examination Paper Updated: ' + p.id + ' (' + p.subject + ')', 'success');
      }
    } else {
      // Add new paper
      const newPaper = {
        id: examId,
        examName: examName,
        academicYear: academicYear,
        class: targetClass,
        subject: subjectName,
        paperCode: paperCode,
        date: examDate,
        day: dayName,
        startTime: startTimeFormatted,
        endTime: endTimeFormatted,
        session: startTimeRaw.startsWith('09') || startTimeRaw.startsWith('10') ? 'Forenoon (FN)' : 'Afternoon (AN)',
        duration: '3.0 Hrs',
        room: room,
        maxMarks: maxMarks,
        passingCriteria: passingCriteria,
        invigilators: invigilators,
        status: status
      };
      EXAM_SCHEDULE_PAPERS.push(newPaper);
      showToast('New Subject Paper Added: ' + newPaper.subject + ' for ' + targetClass, 'success');
    }

    closeModal('scheduleExamModal');
    renderExamScheduleTable();
  }

  function deleteExamPaper(paperId) {
    if (!paperId) return;
    if (confirm('Are you sure you want to remove examination paper (' + paperId + ') from the schedule?')) {
      EXAM_SCHEDULE_PAPERS = EXAM_SCHEDULE_PAPERS.filter(p => p.id !== paperId);
      showToast('Examination paper removed from schedule.', 'info');
      closeModal('scheduleExamModal');
      renderExamScheduleTable();
    }
  }

