  // -------------------------------------------------------------------------
  // ACTION 4: CHECK CONFLICTS
  // -------------------------------------------------------------------------
  function checkExamScheduleConflicts() {
    const conflicts = [];

    // 1. Check for Room Overlaps (same room + same date)
    for (let i = 0; i < EXAM_SCHEDULE_PAPERS.length; i++) {
      for (let j = i + 1; j < EXAM_SCHEDULE_PAPERS.length; j++) {
        const p1 = EXAM_SCHEDULE_PAPERS[i];
        const p2 = EXAM_SCHEDULE_PAPERS[j];
        if (p1.date === p2.date && p1.room === p2.room && p1.class !== p2.class) {
          conflicts.push({
            type: 'Room Capacity Overlap',
            detail: p1.class + ' (' + p1.subject + ') and ' + p2.class + ' (' + p2.subject + ') both booked in ' + p1.room + ' on ' + p1.date,
            severity: 'Review Recommended'
          });
        }
      }
    }

    // 2. Check for Student Double-Booking (same class with 2 papers on same date)
    const classDateMap = {};
    EXAM_SCHEDULE_PAPERS.forEach(p => {
      const key = p.class + '|' + p.date;
      if (!classDateMap[key]) classDateMap[key] = [];
      classDateMap[key].push(p);
    });

    Object.keys(classDateMap).forEach(k => {
      if (classDateMap[k].length > 1) {
        const papers = classDateMap[k];
        conflicts.push({
          type: 'Student Multiple Paper Day',
          detail: papers[0].class + ' has ' + papers.length + ' papers scheduled on ' + papers[0].date + ': ' + papers.map(x => x.subject).join(', '),
          severity: 'Moderate Stress'
        });
      }
    });

    // 3. Check for Invigilator Double-Booking (same invigilator in 2 rooms on same date)
    for (let i = 0; i < EXAM_SCHEDULE_PAPERS.length; i++) {
      for (let j = i + 1; j < EXAM_SCHEDULE_PAPERS.length; j++) {
        const p1 = EXAM_SCHEDULE_PAPERS[i];
        const p2 = EXAM_SCHEDULE_PAPERS[j];
        if (p1.date === p2.date && p1.invigilators === p2.invigilators && p1.room !== p2.room) {
          conflicts.push({
            type: 'Invigilator Double-Booking',
            detail: p1.invigilators + ' assigned to both ' + p1.room + ' and ' + p2.room + ' on ' + p1.date,
            severity: 'Severe Clash'
          });
        }
      }
    }

    // Populate modal counters
    const totalEl = document.getElementById('conflictAuditTotalPapers');
    const studentEl = document.getElementById('conflictAuditStudentClashes');
    const roomEl = document.getElementById('conflictAuditRoomClashes');
    const teacherEl = document.getElementById('conflictAuditTeacherClashes');
    const container = document.getElementById('examConflictReportContainer');

    if (totalEl) totalEl.innerText = EXAM_SCHEDULE_PAPERS.length + ' Papers';
    if (studentEl) studentEl.innerText = conflicts.filter(c => c.type.includes('Student')).length + ' Clashes';
    if (roomEl) roomEl.innerText = conflicts.filter(c => c.type.includes('Room')).length + ' Overlaps';
    if (teacherEl) teacherEl.innerText = conflicts.filter(c => c.type.includes('Invigilator')).length + ' Clashes';

    if (container) {
      if (conflicts.length === 0) {
        container.innerHTML = `
          <div style="background:#ecfdf5; border:1px solid #a7f3d0; border-radius:10px; padding:1.75rem; text-align:center;">
            <div style="font-size:2.5rem; color:#10b981; margin-bottom:0.5rem;"><i class="fa-solid fa-circle-check"></i></div>
            <h4 style="color:#065f46; font-size:1.15rem; font-weight:800; margin:0 0 0.5rem;">0 Conflicts Detected Across Datesheet</h4>
            <p style="color:#047857; font-size:0.875rem; margin:0 auto; max-width:550px;">
              Every examination paper is isolated. Class bell schedules, hall capacities (1 student per desk), and invigilator rosters are 100% verified with zero timetable overlaps.
            </p>
          </div>
        `;
      } else {
        container.innerHTML = `
          <div style="display:flex; flex-direction:column; gap:0.75rem;">
            ${conflicts.map(c => `
              <div style="background:#fff1f2; border:1px solid #fecdd3; border-left:4px solid #ef4444; border-radius:6px; padding:0.75rem 1rem;">
                <div style="display:flex; justify-content:space-between; align-items:center;">
                  <strong style="color:#991b1b; font-size:0.9rem;"><i class="fa-solid fa-triangle-exclamation mr-1"></i> ${c.type}</strong>
                  <span class="portal-badge badge-danger">${c.severity}</span>
                </div>
                <div style="color:#7f1d1d; font-size:0.8125rem; margin-top:0.35rem;">${c.detail}</div>
              </div>
            `).join('')}
          </div>
        `;
      }
    }

    openModal('examConflictAuditModal');
  }

