  function exportExamScheduleCSV() {
    let csv = 'Exam ID,Examination Name,Academic Year,Class,Subject,Paper Code,Exam Date,Day,Start Time,End Time,Session,Room/Hall,Max Marks,Passing Criteria,Assigned Invigilators,Status\r\n';
    EXAM_SCHEDULE_PAPERS.forEach(p => {
      const cleanSub = (p.subject || '').replace(/"/g, '""');
      const cleanRoom = (p.room || '').replace(/"/g, '""');
      const cleanInvig = (p.invigilators || '').replace(/"/g, '""');
      const cleanPass = (p.passingCriteria || '').replace(/"/g, '""');
      csv += `"${p.id}","${p.examName}","${p.academicYear}","${p.class}","${cleanSub}","${p.paperCode}","${p.date}","${p.day}","${p.startTime}","${p.endTime}","${p.session}","${cleanRoom}","${p.maxMarks}","${cleanPass}","${cleanInvig}","${p.status}"\r\n`;
    });

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.setAttribute('download', 'SriVidya_Exam_Schedule_Datesheet_2026_2027.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    showToast('Examination schedule CSV downloaded successfully!', 'success');
  }


