  function updateInvigilationKPIs() {
    ensureInvigilationDutiesData();
    const duties = window.INVIGILATION_DUTIES_DATA;

    // 1. Invigilators Deployed
    const kpiInvigilators = document.getElementById('kpiInvigilatorsDeployed');
    if (kpiInvigilators) kpiInvigilators.textContent = duties.length;

    // 2. Active Examination Halls
    const uniqueHalls = new Set(duties.map(d => d.hall));
    const kpiHalls = document.getElementById('kpiActiveExamHalls');
    if (kpiHalls) kpiHalls.textContent = uniqueHalls.size;

    // 3. Conflict Surveillance
    const conflicts = detectInvigilationClashes();
    const kpiConflicts = document.getElementById('kpiInvigilationConflicts');
    if (kpiConflicts) {
      kpiConflicts.textContent = conflicts.length === 0 ? '0 (Clean)' : `${conflicts.length} Clashes`;
      kpiConflicts.style.color = conflicts.length === 0 ? '#10b981' : '#ef4444';
    }

    // 4. Superintendent Status
    const kpiSuper = document.getElementById('kpiSuperintendentStatus');
    if (kpiSuper) kpiSuper.textContent = 'Active On Duty';
  }

  function detectInvigilationClashes() {
    ensureInvigilationDutiesData();
    const duties = window.INVIGILATION_DUTIES_DATA;
    const clashes = [];

    // Check 1: Same staff double-booked at the same date and session
    for (let i = 0; i < duties.length; i++) {
      for (let j = i + 1; j < duties.length; j++) {
        const d1 = duties[i];
        const d2 = duties[j];
        if (d1.date === d2.date && d1.session === d2.session) {
          if (d1.invigilator === d2.invigilator) {
            clashes.push({
              type: 'Double Booking',
              severity: 'High',
              staff: d1.invigilator,
              session: d1.examSession,
              description: `${d1.invigilator} is assigned simultaneously to ${d1.hall} and ${d2.hall} on ${d1.date} (${d1.session}).`
            });
          }
        }
      }
    }

    // Check 2: Assigned students > capacity
    duties.forEach(d => {
      if (d.assignedStudents > d.capacity) {
        clashes.push({
          type: 'Capacity Overload',
          severity: 'Critical',
          staff: d.invigilator,
          session: d.examSession,
          description: `Hall ${d.hall} has ${d.assignedStudents} students assigned exceeding maximum capacity of ${d.capacity} desks.`
        });
      }
    });

    return clashes;
  }

  // 2. INVIGILATION DUTY TABLE RENDERER
  function renderInvigilationDutyTable() {
    ensureInvigilationDutiesData();
    updateInvigilationKPIs();

    const tbody = document.getElementById('invigilationDutyTableBody');
    if (!tbody) return;

    const sessionFilter = document.getElementById('invigilationSessionFilter')?.value || 'all';
    const hallFilter = document.getElementById('invigilationHallFilter')?.value || 'all';
    const statusFilter = document.getElementById('invigilationStatusFilter')?.value || 'all';
    const searchVal = (document.getElementById('invigilationSearchInput')?.value || '').toLowerCase().trim();

    let filtered = window.INVIGILATION_DUTIES_DATA;
    if (sessionFilter !== 'all') {
      filtered = filtered.filter(d => (d.session && d.session.includes(sessionFilter)) || (d.examSession && d.examSession.toLowerCase().includes(sessionFilter.toLowerCase())));
    }
    if (hallFilter !== 'all') {
      filtered = filtered.filter(d => d.hall && d.hall.toLowerCase().includes(hallFilter.toLowerCase()));
    }
    if (statusFilter !== 'all') {
      filtered = filtered.filter(d => d.status && d.status.toLowerCase().includes(statusFilter.toLowerCase()));
    }
    if (searchVal) {
      filtered = filtered.filter(d => 
        (d.invigilator && d.invigilator.toLowerCase().includes(searchVal)) ||
        (d.hall && d.hall.toLowerCase().includes(searchVal)) ||
        (d.room && d.room.toLowerCase().includes(searchVal)) ||
        (d.empCode && d.empCode.toLowerCase().includes(searchVal)) ||
        (d.dept && d.dept.toLowerCase().includes(searchVal)) ||
        (d.relief && d.relief.toLowerCase().includes(searchVal)) ||
        (d.examSession && d.examSession.toLowerCase().includes(searchVal)) ||
        (d.classes && d.classes.toLowerCase().includes(searchVal))
      );
    }

    if (filtered.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="7" style="text-align:center; padding:2.5rem 1rem; color:#64748b;">
            <i class="fa-solid fa-clipboard-user" style="font-size:2.4rem; color:#94a3b8; margin-bottom:0.75rem; display:block;"></i>
            <strong>No Invigilation Duties Found</strong>
            <p class="text-xs mb-0">No active duty allocations match the selected filters. Use "Assign Duty" to deploy invigilators.</p>
          </td>
        </tr>
      `;
      return;
    }

    tbody.innerHTML = filtered.map(d => {
      const isFn = d.session && d.session.includes('FN');
      const shiftBadgeClass = isFn ? 'badge-primary' : 'badge-warning';
      const utilPercent = Math.min(100, Math.round((d.assignedStudents / (d.capacity || 1)) * 100));
      const barColor = utilPercent > 95 ? '#ef4444' : (utilPercent > 80 ? '#f59e0b' : '#10b981');

      let statusBadgeClass = 'badge-neutral';
      let statusIcon = 'fa-circle-question';
      if (d.status === 'Confirmed & Acknowledged' || d.status === 'Assigned & Confirmed') {
        statusBadgeClass = 'badge-success';
        statusIcon = 'fa-circle-check';
      } else if (d.status === 'Reporting Confirmed') {
        statusBadgeClass = 'badge-info';
        statusIcon = 'fa-user-check';
      } else if (d.status === 'Active In-Hall') {
        statusBadgeClass = 'badge-primary';
        statusIcon = 'fa-person-chalkboard fa-fade';
      } else if (d.status === 'Pending Acceptance') {
        statusBadgeClass = 'badge-warning';
        statusIcon = 'fa-clock';
      } else if (d.status === 'Relieved / Completed') {
        statusBadgeClass = 'badge-neutral';
        statusIcon = 'fa-circle-check';
      }

      return `
        <tr data-duty-id="${d.id}">
          <!-- 1. Examination Session -->
          <td>
            <div style="display:flex; flex-direction:column; gap:0.25rem;">
              <span class="portal-badge ${shiftBadgeClass}" style="font-size:0.72rem; width:fit-content;">
                <i class="fa-solid fa-calendar-day mr-1"></i> ${d.session || 'FN'}
              </span>
              <strong style="color:#0f172a; font-size:0.86rem; line-height:1.25;">${d.examSession || d.examName || 'SA-1 Examination'}</strong>
              <div style="font-size:0.75rem; color:#475569; display:flex; align-items:center; gap:0.4rem;">
                <i class="fa-solid fa-clock text-muted"></i> ${d.date} (${d.day || 'Duty Day'})
              </div>
              ${d.subject ? `<span style="font-size:0.74rem; color:#6366f1; font-weight:600;"><i class="fa-solid fa-book-open mr-1"></i> ${d.subject}</span>` : ''}
            </div>
          </td>

          <!-- 2. Room -->
          <td>
            <div style="display:flex; flex-direction:column; gap:0.2rem;">
              <div style="font-size:0.86rem; color:#1e293b; font-weight:700;">
                <i class="fa-solid fa-door-open text-amber mr-1"></i> ${d.hall || d.room}
              </div>
              <small class="text-muted" style="font-size:0.74rem;">
                <i class="fa-solid fa-location-dot mr-1 text-slate-400"></i> ${d.roomLocation || 'Ground Floor'}
              </small>
              <div style="display:inline-flex; align-items:center; gap:0.35rem; margin-top:0.2rem;">
                <span class="badge" style="background:#e0f2fe; color:#0369a1; font-size:0.68rem; font-weight:700; border-radius:4px; padding:2px 6px;">
                  Desks: ${d.capacity || 80}
                </span>
                <span class="badge" style="background:#f1f5f9; color:#475569; font-size:0.68rem; font-weight:600; border-radius:4px; padding:2px 6px;">
                  CCTV Monitored
                </span>
              </div>
            </div>
          </td>

          <!-- 3. Invigilator -->
          <td>
            <div style="display:flex; flex-direction:column; gap:0.2rem;">
              <div style="display:flex; align-items:center; gap:0.4rem;">
                <strong style="color:#1d4ed8; font-size:0.88rem;">${d.invigilator}</strong>
                <span class="portal-badge badge-neutral" style="font-family:monospace; font-size:0.68rem; padding:1px 5px;">${d.empCode}</span>
              </div>
              <small style="color:#475569; font-weight:600; font-size:0.75rem;">${d.dept}</small>
              <div style="font-size:0.72rem; color:#64748b; display:flex; align-items:center; gap:0.5rem; margin-top:0.1rem;">
                <span><i class="fa-solid fa-phone mr-1"></i> ${d.phone || '+91 94400 00000'}</span>
              </div>
              <div style="margin-top:0.25rem; font-size:0.74rem; color:#047857; background:#ecfdf5; border:1px solid #a7f3d0; border-radius:4px; padding:2px 6px; width:fit-content;">
                <i class="fa-solid fa-user-clock mr-1 text-emerald"></i> Reliever: <strong>${d.relief}</strong>
              </div>
            </div>
          </td>

          <!-- 4. Duty Time -->
          <td>
            <div style="display:flex; flex-direction:column; gap:0.25rem;">
              <strong style="color:#0f172a; font-size:0.85rem; font-family:monospace;">
                <i class="fa-solid fa-stopwatch mr-1 text-primary"></i> ${d.dutyTime || d.time}
              </strong>
              <div style="font-size:0.74rem; color:#b45309; background:#fffbeb; border:1px solid #fde68a; padding:0.18rem 0.5rem; border-radius:4px; width:fit-content;">
                <i class="fa-solid fa-bell mr-1"></i> Reporting: <strong>${d.reportingTime}</strong>
              </div>
              <small class="text-muted" style="font-size:0.72rem;">Shift Window: 3h 45m (Includes Handover)</small>
            </div>
          </td>

          <!-- 5. Assigned Students or Capacity -->
          <td>
            <div style="display:flex; flex-direction:column; gap:0.25rem; min-width:140px;">
              <div style="display:flex; justify-content:space-between; align-items:baseline;">
                <strong style="font-size:0.86rem; color:#0f172a;">${d.assignedStudents} <span style="font-size:0.72rem; font-weight:normal; color:#64748b;">/ ${d.capacity} Desks</span></strong>
                <span style="font-size:0.72rem; font-weight:700; color:${barColor};">${utilPercent}%</span>
              </div>
              <div style="width:100%; height:6px; background:#e2e8f0; border-radius:3px; overflow:hidden;">
                <div style="width:${utilPercent}%; height:100%; background:${barColor}; border-radius:3px;"></div>
              </div>
              <div style="font-size:0.73rem; color:#475569; margin-top:0.1rem;">
                <i class="fa-solid fa-users-rectangle mr-1 text-muted"></i> ${d.classes || 'Class X-A & IX-A'}
              </div>
            </div>
          </td>

          <!-- 6. Confirmation Status -->
          <td style="text-align:center;">
            <div style="display:inline-flex; flex-direction:column; align-items:center; gap:0.3rem;">
              <span class="portal-badge ${statusBadgeClass}" style="font-size:0.74rem; cursor:pointer;" onclick="portalApp.cycleInvigilationDutyStatus('${d.id}')" title="Click to cycle confirmation status">
                <i class="fa-solid ${statusIcon}"></i> ${d.status}
              </span>
              <small class="text-muted" style="font-size:0.68rem; cursor:pointer;" onclick="portalApp.cycleInvigilationDutyStatus('${d.id}')">
                <i class="fa-solid fa-arrows-rotate mr-1"></i> Toggle Status
              </small>
            </div>
          </td>

          <!-- 7. Operational Actions -->
          <td style="text-align:center;">
            <div style="display:inline-flex; align-items:center; gap:0.4rem; justify-content:center;">
              <button class="btn btn-outline-primary btn-sm" style="padding:0.3rem 0.55rem; font-size:0.78rem;" onclick="portalApp.openReassignInvigilatorModal('${d.id}')" title="Reassign Invigilator / Reliever">
                <i class="fa-solid fa-user-pen mr-1"></i> Reassign
              </button>
              <button class="btn btn-secondary btn-sm" style="padding:0.3rem 0.55rem; font-size:0.78rem;" onclick="portalApp.printSingleDutySlip('${d.id}')" title="Print Official Duty Order Slip">
                <i class="fa-solid fa-print"></i>
              </button>
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

  function filterInvigilationDuties() {
    renderInvigilationDutyTable();
  }

  function resetInvigilationFilters() {
    const sFilter = document.getElementById('invigilationSessionFilter');
    if (sFilter) sFilter.value = 'all';
    const hFilter = document.getElementById('invigilationHallFilter');
    if (hFilter) hFilter.value = 'all';
    const stFilter = document.getElementById('invigilationStatusFilter');
    if (stFilter) stFilter.value = 'all';
    const sInput = document.getElementById('invigilationSearchInput');
    if (sInput) sInput.value = '';
    renderInvigilationDutyTable();
    showToast('Invigilation duty filters reset to all active allocations.', 'info');
  }

  function cycleInvigilationDutyStatus(dutyId) {
    ensureInvigilationDutiesData();
    const duty = window.INVIGILATION_DUTIES_DATA.find(d => d.id === dutyId);
    if (!duty) return;
    const states = [
      'Assigned & Confirmed',
      'Reporting Confirmed',
      'Active In-Hall',
      'Relieved / Completed',
      'Pending Acceptance'
    ];
    const curIdx = states.indexOf(duty.status);
    duty.status = states[(curIdx + 1) % states.length];
    renderInvigilationDutyTable();
    showToast(`Duty status for ${duty.invigilator} updated to: ${duty.status}`, 'info');
  }

  // --- ACTION 1: ASSIGN DUTY ---
  function openAssignInvigilationModal() {
    openModal('assignInvigilationDutyModal');
  }

  function handleAssignInvigilationDutySubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    ensureInvigilationDutiesData();

    const sessionVal = document.getElementById('assignExamSession')?.value || '';
    const roomVal = document.getElementById('assignDutyRoom')?.value || '';
    const primaryInv = document.getElementById('assignPrimaryInvigilator')?.value || '';
    const reliefInv = document.getElementById('assignReliefInvigilator')?.value || 'Sri P. Satyanarayana';
    const dateVal = document.getElementById('assignDutyDate')?.value || '2026-10-24';
    const startTimeVal = document.getElementById('assignDutyStartTime')?.value || '09:00';
    const endTimeVal = document.getElementById('assignDutyEndTime')?.value || '12:45';
    const reportTimeVal = document.getElementById('assignReportingTime')?.value || '08:45 AM (Strict)';
    const studentsVal = parseInt(document.getElementById('assignAssignedStudents')?.value || '75', 10);
    const capacityVal = parseInt(document.getElementById('assignRoomCapacity')?.value || '80', 10);
    const statusVal = document.getElementById('assignConfirmationStatus')?.value || 'Assigned & Confirmed';

    if (!sessionVal || !roomVal || !primaryInv) {
      showToast('Please fill all mandatory duty assignment fields.', 'warning');
      return;
    }

    // Clash audit
    const isShiftFN = startTimeVal < '13:00';
    const shiftLabel = isShiftFN ? 'Forenoon (FN)' : 'Afternoon (AN)';
    const existingClash = window.INVIGILATION_DUTIES_DATA.find(d => 
      d.date.includes(dateVal) && d.session.includes(shiftLabel) && d.invigilator.toLowerCase().includes(primaryInv.toLowerCase())
    );

    if (existingClash) {
      const confirmOverride = confirm(`Potential Staff Conflict: ${primaryInv} is already allocated to ${existingClash.hall} during ${shiftLabel}. Do you wish to override and proceed with emergency dual deployment?`);
      if (!confirmOverride) return;
    }

    const newId = `INV-${Math.floor(100 + Math.random() * 900)}`;
    const newRecord = {
      id: newId,
      examSession: sessionVal,
      examName: sessionVal.split('•')[0].trim(),
      date: dateVal,
      day: 'Duty Day',
      session: shiftLabel,
      subject: 'Scheduled Board Assessment',
      hall: roomVal,
      room: roomVal.split('(')[0].trim(),
      roomLocation: 'Academic Campus',
      invigilator: primaryInv,
      empCode: `EMP-0${Math.floor(10 + Math.random() * 20)}`,
      dept: 'Secondary Teaching Faculty',
      phone: '+91 94401 99887',
      relief: reliefInv,
      dutyTime: `${startTimeVal} – ${endTimeVal}`,
      time: `${startTimeVal} – ${endTimeVal}`,
      reportingTime: reportTimeVal,
      assignedStudents: studentsVal,
      classes: 'Allocated Class Cohort',
      capacity: capacityVal,
      status: statusVal
    };

    window.INVIGILATION_DUTIES_DATA.unshift(newRecord);
    closeModal('assignInvigilationDutyModal');
    renderInvigilationDutyTable();
    showToast(`Official duty ${newId} successfully assigned to ${primaryInv}!`, 'success');
  }

  // --- ACTION 2: REASSIGN ---
  function openReassignInvigilatorModal(dutyId) {
    ensureInvigilationDutiesData();
    const duty = window.INVIGILATION_DUTIES_DATA.find(d => d.id === dutyId);
    if (!duty) {
      showToast('Invigilation duty record not found.', 'error');
      return;
    }

    const idInput = document.getElementById('reassignDutyId');
    if (idInput) idInput.value = duty.id;

    const idDisplay = document.getElementById('reassignDutyIdDisplay');
    if (idDisplay) idDisplay.textContent = duty.id;

    const sessionDisplay = document.getElementById('reassignCurrentSessionDisplay');
    if (sessionDisplay) sessionDisplay.textContent = `${duty.examSession} • ${duty.dutyTime}`;

    const invigDisplay = document.getElementById('reassignCurrentInvigilatorDisplay');
    if (invigDisplay) invigDisplay.textContent = `${duty.invigilator} (${duty.empCode} • ${duty.dept})`;

    const hallDisplay = document.getElementById('reassignCurrentHallDisplay');
    if (hallDisplay) hallDisplay.textContent = `${duty.hall} (${duty.assignedStudents} Students)`;

    openModal('reassignInvigilatorModal');
  }

  function handleReassignInvigilatorSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    ensureInvigilationDutiesData();

    const dutyId = document.getElementById('reassignDutyId')?.value;
    const duty = window.INVIGILATION_DUTIES_DATA.find(d => d.id === dutyId);
    if (!duty) {
      showToast('Duty record not found.', 'error');
      return;
    }

    const replacementStaff = document.getElementById('reassignReplacementStaff')?.value || '';
    const newRelief = document.getElementById('reassignReliefStaff')?.value || duty.relief;
    const reason = document.getElementById('reassignReason')?.value || 'Administrative Reallocation';
    const notifyStaff = document.getElementById('reassignNotificationCheckbox')?.checked;

    if (!replacementStaff) {
      showToast('Please select a replacement invigilator.', 'warning');
      return;
    }

    const previousStaff = duty.invigilator;
    duty.invigilator = replacementStaff;
    duty.relief = newRelief;
    duty.status = 'Assigned & Confirmed';

    closeModal('reassignInvigilatorModal');
    renderInvigilationDutyTable();

    if (notifyStaff) {
      showToast(`Duty reassigned from ${previousStaff} to ${replacementStaff}. SMS & WhatsApp notifications dispatched!`, 'success');
    } else {
      showToast(`Duty successfully reassigned from ${previousStaff} to ${replacementStaff}. Reason logged: ${reason}.`, 'success');
    }
  }

  // --- ACTION 3: RESOLVE CONFLICTS ---
  function resolveInvigilationConflicts() {
    ensureInvigilationDutiesData();
    const clashes = detectInvigilationClashes();
    const container = document.getElementById('invigilationConflictListContainer');
    const badge = document.getElementById('conflictAuditSummaryBadge');

    if (badge) {
      badge.textContent = clashes.length === 0 ? '0 Clashes Detected' : `${clashes.length} Active Conflict(s)`;
      badge.style.background = clashes.length === 0 ? '#ecfdf5' : '#fef2f2';
      badge.style.color = clashes.length === 0 ? '#047857' : '#dc2626';
    }

    if (container) {
      if (clashes.length === 0) {
        container.innerHTML = `
          <div style="background:#ecfdf5; border:1px solid #a7f3d0; border-radius:8px; padding:1.5rem; text-align:center;">
            <i class="fa-solid fa-circle-check text-emerald" style="font-size:2.2rem; margin-bottom:0.75rem; display:block;"></i>
            <h5 style="color:#065f46; font-weight:700; margin-bottom:0.35rem;">Zero Invigilation Conflicts Detected</h5>
            <p style="color:#047857; font-size:0.84rem; margin-bottom:0;">
              All invigilators have compliant shift intervals, no double-room allocations, and seating capacities adhere strictly to AP Board norms.
            </p>
          </div>
        `;
      } else {
        container.innerHTML = clashes.map(c => `
          <div style="background:#fff; border:1px solid #fecaca; border-left:4px solid #ef4444; border-radius:8px; padding:1rem; margin-bottom:0.85rem; display:flex; justify-content:space-between; align-items:center;">
            <div>
              <div style="display:flex; align-items:center; gap:0.5rem; margin-bottom:0.25rem;">
                <span class="badge" style="background:#fee2e2; color:#b91c1c; font-size:0.72rem; font-weight:700;">${c.type}</span>
                <strong style="color:#0f172a; font-size:0.86rem;">${c.staff}</strong>
              </div>
              <p style="margin:0; font-size:0.82rem; color:#475569;">${c.description}</p>
            </div>
            <button class="btn btn-outline-danger btn-sm" onclick="portalApp.autoResolveSingleConflict('${c.staff}')" style="white-space:nowrap; font-size:0.78rem;">
              <i class="fa-solid fa-wand-magic-sparkles mr-1"></i> Auto-Rebalance
            </button>
          </div>
        `).join('');
      }
    }

    openModal('invigilationConflictModal');
  }

  function autoResolveSingleConflict(staffName) {
    ensureInvigilationDutiesData();
    const duties = window.INVIGILATION_DUTIES_DATA.filter(d => d.invigilator === staffName);
    if (duties.length > 1) {
      // Reassign the second duty to reserve relief staff
      duties[1].invigilator = 'Sri P. Satyanarayana (Relief Reserve)';
      duties[1].status = 'Assigned & Confirmed';
      renderInvigilationDutyTable();
      resolveInvigilationConflicts();
      showToast(`Conflict resolved! Second duty reassigned to Sri P. Satyanarayana.`, 'success');
    } else {
      showToast(`Clash audit re-calculated for ${staffName}.`, 'info');
      resolveInvigilationConflicts();
    }
  }

  function autoResolveAllInvigilationConflicts() {
    ensureInvigilationDutiesData();
    const duties = window.INVIGILATION_DUTIES_DATA;
    let resolvedCount = 0;

    for (let i = 0; i < duties.length; i++) {
      for (let j = i + 1; j < duties.length; j++) {
        if (duties[i].date === duties[j].date && duties[i].session === duties[j].session && duties[i].invigilator === duties[j].invigilator) {
          duties[j].invigilator = 'Sri P. Satyanarayana (Reserve Reliever)';
          duties[j].status = 'Assigned & Confirmed';
          resolvedCount++;
        }
      }
      if (duties[i].assignedStudents > duties[i].capacity) {
        duties[i].assignedStudents = duties[i].capacity;
        resolvedCount++;
      }
    }

    renderInvigilationDutyTable();
    closeModal('invigilationConflictModal');
    showToast(`Surveillance engine automatically resolved ${resolvedCount} invigilation and hall conflict(s)!`, 'success');
  }

