  function viewStudentPaymentHistory(admNo, studentName) {
    const studentPayments = feeCollectionData.filter(function(r) { return r.admNo === admNo; });
    let totalPaid = 0;
    studentPayments.forEach(function(r) {
      totalPaid += parseFloat(String(r.amountPaid).replace(/[^0-9.]/g, '')) || 0;
    });

    const info = 'Payment History for ' + studentName + ' (' + admNo + '):\n\n' +
      'Total Records: ' + studentPayments.length + '\n' +
      'Total Realized: ₹' + totalPaid.toLocaleString('en-IN') + '\n\n' +
      studentPayments.map(function(p) {
        return '• ' + p.paymentDate + ': ' + p.feeHead + ' - ' + p.amountPaid + ' (' + p.paymentMethod + ') - ' + p.receiptNo;
      }).join('\n');

    alert(info);
  }

  function openFeeReversalOrRefundModal(receiptNo) {
    const rec = feeCollectionData.find(function(r) { return r.receiptNo === receiptNo; });
    if (!rec) return;

    const reason = prompt('Enter authorized statutory reason for Reversal or Refund Request on ' + rec.receiptNo + ' (' + rec.student + ' - ' + rec.amountPaid + '):', 'Parent excess payment refund request');
    if (!reason) return;

    // Create a refund request
    const nextRefId = 'REF-2026-0' + (feeRefundsData.length + 1);
    feeRefundsData.unshift({
      id: nextRefId,
      originalPayment: rec.receiptNo + ' (' + rec.amountPaid + ')',
      student: rec.student,
      admNo: rec.admNo,
      class: rec.class,
      refundReason: reason,
      requestedAmount: rec.amountPaid,
      approvedAmount: '₹0',
      approvalStatus: 'Pending Independent Approval',
      paymentStatus: 'Awaiting Authorization',
      recordedBy: 'S. Ramu (Cashier)',
      approvedBy: null,
      reconciled: false,
      date: new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }),
      receiptNo: null
    });

    renderFeeRefunds();
    showToast('Refund docket ' + nextRefId + ' initiated for ' + rec.receiptNo + '. Segregation of duties applied; awaiting Principal approval.', 'success');
  }

