  // 10.2 PENDING DUES CONTROLLER & ACTIONS
  // =========================================================================

  function renderDefaultersTable(list) {
    const tbody = document.getElementById('defaultersTableBody');
    if (!tbody) return;

    const data = list || defaultersData;

    if (data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="11" class="text-center text-muted p-4"><i class="fa-solid fa-check-circle mr-2 text-emerald"></i>No outstanding fee dues found. All accounts are in good standing.</td></tr>';
      return;
    }

    tbody.innerHTML = data.map(function(d) {
      const isCritical = (d.overdueDays || 0) >= 30;
      const daysBadge = isCritical
        ? '<span class="portal-badge badge-danger" style="font-size:0.75rem;"><i class="fa-solid fa-triangle-exclamation mr-1"></i>' + d.overdueDays + ' Days</span>'
        : '<span class="portal-badge badge-warning" style="font-size:0.75rem;">' + (d.overdueDays || 15) + ' Days</span>';

      const disputeBadge = d.disputed
        ? '<div style="font-size:0.72rem; color:#b91c1c; font-weight:700; margin-top:2px;"><i class="fa-solid fa-gavel mr-1"></i>Disputed by Parent</div>'
        : '';

      return '<tr>' +
        '<td>' +
          '<div style="font-weight:700; color:var(--color-text-dark);">' + d.name + '</div>' +
          '<div class="font-mono text-muted" style="font-size:0.75rem;">' + d.admNo + ' &bull; ' + d.parent + '</div>' +
          disputeBadge +
        '</td>' +
        '<td>' + d.class + '</td>' +
        '<td><span class="font-mono" style="color:#1e40af; font-weight:600;">' + (d.invoiceNo || 'INV-2026-00' + d.admNo.slice(-2)) + '</span></td>' +
        '<td>' + d.head + '</td>' +
        '<td style="font-size:0.83rem;">' + (d.dueDate || '15 Oct 2026') + '</td>' +
        '<td style="text-align: right; font-weight:600;">' + (d.amountDue || d.amount) + '</td>' +
        '<td style="text-align: right; font-weight:600; color:#16a34a;">' + (d.amountPaid || '₹0') + '</td>' +
        '<td style="text-align: right; font-weight:800; color:#dc2626;">' + (d.balance || d.amount) + '</td>' +
        '<td style="text-align: center;">' + daysBadge + '</td>' +
        '<td>' +
          '<span class="portal-badge badge-info" style="font-size:0.73rem;">' + (d.reminderStatus || d.reminder) + '</span>' +
        '</td>' +
        '<td style="text-align: center;">' +
          '<div style="display:inline-flex; gap:4px; flex-wrap:wrap; justify-content:center;">' +
            '<button class="btn btn-sm btn-outline-primary" style="padding:2px 7px; font-size:0.75rem;" title="Send Authorized SMS & WhatsApp Reminder" onclick="portalApp.sendAuthorizedFeeReminder(\'' + d.invoiceNo + '\')">' +
              '<i class="fa-solid fa-paper-plane"></i> Remind' +
            '</button>' +
            '<button class="btn btn-sm btn-outline-warning" style="padding:2px 7px; font-size:0.75rem;" title="Record Parental Fee Dispute" onclick="portalApp.openRecordFeeDisputeModal(\'' + d.invoiceNo + '\')">' +
              '<i class="fa-solid fa-scale-unbalanced"></i> Dispute' +
            '</button>' +
            '<button class="btn btn-sm btn-outline-info" style="padding:2px 7px; font-size:0.75rem;" title="Apply Approved Concession Adjustment" onclick="portalApp.openRecordApprovedConcessionModal(\'' + d.invoiceNo + '\')">' +
              '<i class="fa-solid fa-tags"></i> Concession' +
            '</button>' +
            '<button class="btn btn-sm btn-success" style="padding:2px 7px; font-size:0.75rem;" title="Record Payment at Counter" onclick="portalApp.openRecordPaymentModal(\'' + d.name.replace(/'/g, "\\'") + '\', \'' + d.invoiceNo + '\')">' +
              '<i class="fa-solid fa-hand-holding-dollar"></i> Pay' +
            '</button>' +
            '<button class="btn btn-sm btn-outline-secondary" style="padding:2px 7px; font-size:0.75rem;" title="View Invoice Dossier" onclick="portalApp.viewPendingInvoiceDossier(\'' + d.invoiceNo + '\')">' +
              '<i class="fa-solid fa-file-invoice"></i>' +
            '</button>' +
          '</div>' +
        '</td>' +
      '</tr>';
    }).join('');

    updateDefaultersKPIs();
  }

  function updateDefaultersKPIs() {
    const totalCountEl = document.getElementById('defTotalCount');
    const totalAmountEl = document.getElementById('defTotalAmount');
    if (totalCountEl) totalCountEl.textContent = defaultersData.length;
    if (totalAmountEl) {
      let sum = 0;
      defaultersData.forEach(function(d) {
        sum += parseFloat(String(d.balance || d.amount).replace(/[^0-9.]/g, '')) || 0;
      });
      totalAmountEl.textContent = '₹' + sum.toLocaleString('en-IN');
      const badge = document.getElementById('feePendingTabBadge');
      if (badge) badge.textContent = '₹' + (sum / 100000).toFixed(1) + 'L';
    }
  }

