  function handleRecordFeeDisputeSubmit(e) {
    if (e) e.preventDefault();
    const invoiceNo = document.getElementById('dispInvoiceNo')?.value;
    const category = document.getElementById('dispCategory')?.value || 'Transport / Route Fee';
    const particulars = document.getElementById('dispParticulars')?.value || 'Parent query under executive review';

    const item = defaultersData.find(function(d) { return d.invoiceNo === invoiceNo; });
    if (item) {
      item.disputed = true;
      item.disputeParticulars = category + ': ' + particulars;
      item.reminderStatus = 'Dispute Under Review (Reminders Frozen)';
    }

    closeModal('recordFeeDisputeModal');
    renderDefaultersTable();
    showToast('Parental fee dispute recorded for invoice ' + invoiceNo + '. Reminders frozen pending audit.', 'warning');
  }

  function openRecordApprovedConcessionModal(invoiceNo) {
    const item = defaultersData.find(function(d) { return d.invoiceNo === invoiceNo; });
    if (!item) return;

    const invInput = document.getElementById('appConcInvoiceNo');
    if (invInput) invInput.value = item.invoiceNo;

    openModal('recordApprovedConcessionModal');
  }

  function handleRecordApprovedConcessionSubmit(e) {
    if (e) e.preventDefault();
    const invoiceNo = document.getElementById('appConcInvoiceNo')?.value;
    const scheme = document.getElementById('appConcScheme')?.value || 'Scholarship';
    const amountVal = parseFloat(document.getElementById('appConcAmount')?.value) || 0;
    const authority = document.getElementById('appConcAuthority')?.value || 'Principal Sanction';

    const item = defaultersData.find(function(d) { return d.invoiceNo === invoiceNo; });
    if (item && amountVal > 0) {
      const currentBal = parseFloat(String(item.balance || item.amount).replace(/[^0-9.]/g, '')) || 0;
      const newBal = Math.max(0, currentBal - amountVal);
      item.balance = newBal === 0 ? '₹0' : '₹' + newBal.toLocaleString('en-IN');
      item.concessionApplied = true;

      // Post traceable non-cash adjustment entry to financial ledger
      const nextTxnId = 'TXN-2026-' + (transactionsLedgerData.length + 8911);
      transactionsLedgerData.unshift({
        txnId: nextTxnId,
        type: 'Concession Credit (Non-Cash)',
        amount: '+ ₹' + amountVal.toLocaleString('en-IN') + '.00',
        rawAmount: amountVal,
        ref: 'CONCESSION-OFFSET | ' + invoiceNo + ' | ' + scheme + ' | Auth: ' + authority,
        date: new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }) + ', ' + new Date().toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true }),
        status: 'Reconciled & Locked',
        category: 'concession',
        isReversal: false
      });

      renderDefaultersTable();
      renderTransactionsLedger();
      closeModal('recordApprovedConcessionModal');
      showToast('Approved concession of ₹' + amountVal.toLocaleString('en-IN') + ' applied to invoice ' + invoiceNo + '. Balance adjusted.', 'success');
    }
  }

  function viewPendingInvoiceDossier(invoiceNo) {
    const item = defaultersData.find(function(d) { return d.invoiceNo === invoiceNo; });
    if (!item) return;

    alert(
      'INVOICE DOSSIER: ' + item.invoiceNo + '\n\n' +
      'Student: ' + item.name + ' (' + item.admNo + ')\n' +
      'Class: ' + item.class + '\n' +
      'Parent: ' + item.parent + ' (Ph: ' + item.phone + ')\n' +
      'Fee Head: ' + item.head + '\n' +
      'Due Date: ' + item.dueDate + '\n' +
      'Total Due: ' + (item.amountDue || item.amount) + '\n' +
      'Paid to Date: ' + (item.amountPaid || '₹0') + '\n' +
      'Outstanding: ' + (item.balance || item.amount) + '\n' +
      'Aging: ' + item.overdueDays + ' Days Overdue\n' +
      'Reminder: ' + item.reminderStatus + '\n' +
      (item.disputed ? 'DISPUTE: ' + item.disputeParticulars + '\n' : '')
    );
  }

  function exportPendingDuesCSV() {
    let csv = 'Admission No,Student Name,Class,Parent,Invoice No,Fee Head,Due Date,Amount Due,Amount Paid,Outstanding Balance,Overdue Days,Reminder Status,Phone\n';
    defaultersData.forEach(function(d) {
      csv += '"' + d.admNo + '","' + d.name + '","' + d.class + '","' + d.parent + '","' + d.invoiceNo + '","' + d.head + '","' + d.dueDate + '","' + (d.amountDue || d.amount) + '","' + (d.amountPaid || '₹0') + '","' + (d.balance || d.amount) + '","' + d.overdueDays + '","' + d.reminderStatus + '","' + d.phone + '"\n';
    });
    downloadCsvFile(csv, 'SriVidya_Pending_Fee_Dues_Register.csv');
    showToast('Pending dues register exported to CSV.', 'success');
  }

  function printPendingDuesRegister() {
    window.print();
  }

  // =========================================================================
  // 10.3 FEE STRUCTURE CONTROLLER & ACTIONS
  // =========================================================================

  function renderFeeStructure(list) {
    const tbody = document.getElementById('feeStructureTableBody');
    if (!tbody) return;

    const data = list || feeStructureData;

    if (data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" class="text-center text-muted p-4"><i class="fa-solid fa-folder-open mr-2"></i>No fee structure entries found for this academic filter.</td></tr>';
      return;
    }

    tbody.innerHTML = data.map(function(fs) {
      const isDraft = fs.approvalStatus.includes('Draft');
      const statusBadge = isDraft
        ? '<span class="portal-badge badge-warning" style="font-size:0.75rem;"><i class="fa-solid fa-file-pen mr-1"></i>Draft Review</span>'
        : '<span class="portal-badge badge-success" style="font-size:0.75rem;"><i class="fa-solid fa-circle-check mr-1"></i>Published & Active</span>';

      return '<tr>' +
        '<td><strong class="font-mono">' + fs.academicYear + '</strong></td>' +
        '<td><strong>' + fs.className + '</strong></td>' +
        '<td>' + fs.feeHead + '</td>' +
        '<td style="font-weight:800; color:#0f172a;">' + fs.amount + '</td>' +
        '<td><span style="font-size:0.83rem;">' + fs.instalmentSchedule + '</span></td>' +
        '<td><span style="font-size:0.83rem;">' + fs.dueDates + '</span></td>' +
        '<td><span class="portal-badge badge-info" style="font-size:0.73rem;">' + fs.applicability + '</span></td>' +
        '<td><span style="font-size:0.83rem;">' + fs.effectiveDate + '</span></td>' +
        '<td style="text-align: center;">' + statusBadge + '</td>' +
        '<td style="text-align: center;">' +
          '<div style="display:inline-flex; gap:4px; flex-wrap:wrap; justify-content:center;">' +
            '<button class="btn btn-sm btn-outline-primary" style="padding:2px 7px; font-size:0.75rem;" title="Edit Fee Structure Draft" onclick="portalApp.openEditFeeStructureModal(\'' + fs.id + '\')">' +
              '<i class="fa-solid fa-pen-to-square"></i>' +
            '</button>' +
            '<button class="btn btn-sm btn-outline-secondary" style="padding:2px 7px; font-size:0.75rem;" title="Copy Structure to Another Academic Year" onclick="portalApp.openCopyFeeStructureModal(\'' + fs.id + '\')">' +
              '<i class="fa-solid fa-copy"></i>' +
            '</button>' +
            (isDraft ? (
              '<button class="btn btn-sm btn-success" style="padding:2px 7px; font-size:0.75rem;" title="Publish Approved Fee Structure" onclick="portalApp.publishApprovedFeeStructure(\'' + fs.id + '\')">' +
                '<i class="fa-solid fa-bullhorn"></i> Publish' +
              '</button>'
            ) : (
              '<button class="btn btn-sm btn-outline-danger" style="padding:2px 7px; font-size:0.75rem;" title="Archive Old Structure" onclick="portalApp.archiveFeeStructure(\'' + fs.id + '\')">' +
                '<i class="fa-solid fa-box-archive"></i>' +
              '</button>'
            )) +
          '</div>' +
        '</td>' +
      '</tr>';
    }).join('');
  }

  function filterFeeStructure() {
    const year = document.getElementById('feeStructureYearFilter')?.value || 'all';
    const cls = document.getElementById('feeStructureClassFilter')?.value || 'all';

    const filtered = feeStructureData.filter(function(fs) {
      const matchYear = year === 'all' || fs.academicYear === year;
      const matchCls = cls === 'all' || fs.className.toLowerCase().includes(cls.toLowerCase());
      return matchYear && matchCls;
    });

    renderFeeStructure(filtered);
  }

  function openCreateFeeStructureModal() {
    const editIdInput = document.getElementById('feeStructEditId');
    if (editIdInput) editIdInput.value = '';
    const form = document.getElementById('createFeeStructureForm');
    if (form) form.reset();

    openModal('createFeeStructureModal');
  }

  function openEditFeeStructureModal(id) {
    const item = feeStructureData.find(function(fs) { return fs.id === id; });
    if (!item) return;

    const editIdInput = document.getElementById('feeStructEditId');
    const yearInput = document.getElementById('fsAcademicYear');
    const clsInput = document.getElementById('fsClass');
    const headInput = document.getElementById('fsFeeHead');
    const amtInput = document.getElementById('fsAmount');
    const schedInput = document.getElementById('fsSchedule');
    const dueInput = document.getElementById('fsDueDates');
    const appInput = document.getElementById('fsApplicability');
    const effInput = document.getElementById('fsEffectiveDate');

    if (editIdInput) editIdInput.value = item.id;
    if (yearInput) yearInput.value = item.academicYear;
    if (clsInput) clsInput.value = item.className;
    if (headInput) headInput.value = item.feeHead;
    if (amtInput) amtInput.value = parseFloat(String(item.amount).replace(/[^0-9.]/g, '')) || 0;
    if (schedInput) schedInput.value = item.instalmentSchedule;
    if (dueInput) dueInput.value = item.dueDates;
    if (appInput) appInput.value = item.applicability;
    if (effInput) effInput.value = item.effectiveDate;

    openModal('createFeeStructureModal');
  }

  function handleCreateFeeStructureSubmit(e) {
    if (e) e.preventDefault();

    const editId = document.getElementById('feeStructEditId')?.value;
    const year = document.getElementById('fsAcademicYear')?.value || '2026-2027';
    const cls = document.getElementById('fsClass')?.value || 'Class X';
    const head = document.getElementById('fsFeeHead')?.value || 'Tuition Fee';
    const amountVal = parseFloat(document.getElementById('fsAmount')?.value) || 0;
    const schedule = document.getElementById('fsSchedule')?.value || '2 Instalments';
    const dues = document.getElementById('fsDueDates')?.value || '15 Jul, 15 Oct';
    const applicability = document.getElementById('fsApplicability')?.value || 'All Students';
    const effDate = document.getElementById('fsEffectiveDate')?.value || '01 Jun 2026';

    const amtStr = '₹' + amountVal.toLocaleString('en-IN');

    if (editId) {
      const existing = feeStructureData.find(function(fs) { return fs.id === editId; });
      if (existing) {
        existing.academicYear = year;
        existing.className = cls;
        existing.feeHead = head;
        existing.amount = amtStr;
        existing.instalmentSchedule = schedule;
        existing.dueDates = dues;
        existing.applicability = applicability;
        existing.effectiveDate = effDate;
        showToast('Fee structure draft ' + editId + ' updated.', 'success');
      }
    } else {
      const nextId = 'FS-2026-0' + (feeStructureData.length + 1);
      feeStructureData.unshift({
        id: nextId,
        academicYear: year,
        className: cls,
        feeHead: head,
        amount: amtStr,
        instalmentSchedule: schedule,
        dueDates: dues,
        applicability: applicability,
        effectiveDate: effDate,
        approvalStatus: 'Draft Pending Executive Review'
      });
      showToast('New fee structure ' + nextId + ' created in draft state. Statutory policy: Published structures cannot silently alter issued invoices.', 'success');
    }

    closeModal('createFeeStructureModal');
    renderFeeStructure();
  }

  function openCopyFeeStructureModal(id) {
    const item = feeStructureData.find(function(fs) { return fs.id === id; }) || feeStructureData[0];
    if (!item) return;

    const confirmed = confirm('Copy fee structure for ' + item.className + ' (' + item.feeHead + ') to Academic Year 2027-2028 as a draft?');
    if (confirmed) {
      const nextId = 'FS-2027-0' + (feeStructureData.length + 1);
      feeStructureData.push({
        id: nextId,
        academicYear: '2027-2028',
        className: item.className,
        feeHead: item.feeHead,
        amount: item.amount,
        instalmentSchedule: item.instalmentSchedule,
        dueDates: item.dueDates.replace('2026', '2027'),
        applicability: item.applicability,
        effectiveDate: '01 Jun 2027',
        approvalStatus: 'Draft Copied from AY 2026-27'
      });
      renderFeeStructure();
      showToast('Structure copied to AY 2027-28 as ' + nextId + '.', 'success');
    }
  }

  function submitFeeStructureForApproval(id) {
    const item = feeStructureData.find(function(fs) { return fs.id === id; });
    if (item) {
      item.approvalStatus = 'Pending Principal Sanction';
      renderFeeStructure();
      showToast('Fee structure ' + id + ' submitted to Principal Smt. Gorle Varalakshmi for institutional approval.', 'info');
    }
  }

  function publishApprovedFeeStructure(id) {
    const item = feeStructureData.find(function(fs) { return fs.id === id; });
    if (item) {
      item.approvalStatus = 'Published & Active';
      renderFeeStructure();
      showToast('Fee structure ' + id + ' has been officially approved and published! Applicable to new enrolments.', 'success');
    }
  }

  function archiveFeeStructure(id) {
    const item = feeStructureData.find(function(fs) { return fs.id === id; });
    if (item) {
      item.approvalStatus = 'Archived Historical Policy';
      renderFeeStructure();
      showToast('Fee structure ' + id + ' archived.', 'info');
    }
  }

  function printFeeStructure() {
    window.print();
  }

  // =========================================================================
  // 10.4 CONCESSIONS & SCHOLARSHIPS CONTROLLER & ACTIONS
  // =========================================================================

  function renderFeeConcessions(list) {
    const tbody = document.getElementById('concessionsTableBody');
    if (!tbody) return;

    const data = list || feeConcessionsData;

    if (data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" class="text-center text-muted p-4"><i class="fa-solid fa-folder-open mr-2"></i>No concession applications found.</td></tr>';
      return;
    }

    tbody.innerHTML = data.map(function(c) {
      const isApproved = c.decision === 'Approved';
      const decisionBadge = isApproved
        ? '<span class="portal-badge badge-success" style="font-size:0.75rem;"><i class="fa-solid fa-circle-check mr-1"></i>Approved & Active</span>'
        : (c.decision === 'Rejected'
          ? '<span class="portal-badge badge-danger" style="font-size:0.75rem;"><i class="fa-solid fa-circle-xmark mr-1"></i>Rejected</span>'
          : '<span class="portal-badge badge-warning" style="font-size:0.75rem;"><i class="fa-solid fa-clock mr-1"></i>Under Review</span>');

      return '<tr>' +
        '<td>' +
          '<div style="font-weight:700; color:var(--color-text-dark);">' + c.student + '</div>' +
          '<div class="font-mono text-muted" style="font-size:0.75rem;">' + c.admNo + ' &bull; ' + c.class + '</div>' +
        '</td>' +
        '<td><strong>' + c.scheme + '</strong></td>' +
        '<td>' + c.requested + '</td>' +
        '<td><span style="font-size:0.8rem; color:#475569;"><i class="fa-solid fa-paperclip mr-1"></i>' + c.evidence + '</span></td>' +
        '<td><span class="portal-badge badge-info" style="font-size:0.73rem;">' + c.eligibilityReview + '</span></td>' +
        '<td style="font-weight:800; color:#16a34a; text-align:right;">' + c.proposedAmount + '</td>' +
        '<td style="font-size:0.83rem;">' + c.approver + '</td>' +
        '<td style="text-align: center;">' + decisionBadge + '</td>' +
        '<td style="text-align: center;">' +
          '<div style="display:inline-flex; gap:4px; flex-wrap:wrap; justify-content:center;">' +
            '<button class="btn btn-sm btn-outline-info" style="padding:2px 7px; font-size:0.75rem;" title="Verify Eligibility Documents" onclick="portalApp.verifyConcessionEligibility(\'' + c.id + '\')">' +
              '<i class="fa-solid fa-user-check"></i> Verify' +
            '</button>' +
            (!isApproved ? (
              '<button class="btn btn-sm btn-success" style="padding:2px 7px; font-size:0.75rem;" title="Approve Concession" onclick="portalApp.approveConcession(\'' + c.id + '\')">' +
                '<i class="fa-solid fa-check"></i>' +
              '</button>' +
              '<button class="btn btn-sm btn-outline-danger" style="padding:2px 7px; font-size:0.75rem;" title="Reject Application" onclick="portalApp.rejectConcession(\'' + c.id + '\')">' +
                '<i class="fa-solid fa-xmark"></i>' +
              '</button>'
            ) : (
              '<button class="btn btn-sm btn-outline-primary" style="padding:2px 7px; font-size:0.75rem;" title="Apply to Pending Invoices" onclick="portalApp.applyApprovedConcession(\'' + c.id + '\')">' +
                '<i class="fa-solid fa-file-invoice-dollar"></i> Apply' +
              '</button>'
            )) +
            '<button class="btn btn-sm btn-outline-secondary" style="padding:2px 7px; font-size:0.75rem;" title="View History & Audit Trail" onclick="portalApp.viewConcessionHistory(\'' + c.id + '\')">' +
              '<i class="fa-solid fa-clock-rotate-left"></i>' +
            '</button>' +
          '</div>' +
        '</td>' +
      '</tr>';
    }).join('');

    updateConcessionKPIs();
  }

  function updateConcessionKPIs() {
    const totalEl = document.getElementById('statConcessionTotal');
    const pendingEl = document.getElementById('statConcessionPending');

    if (totalEl) {
      let sum = 0;
      feeConcessionsData.forEach(function(c) {
        if (c.decision === 'Approved') {
          sum += parseFloat(String(c.proposedAmount).replace(/[^0-9.]/g, '')) || 0;
        }
      });
      totalEl.textContent = '₹' + sum.toLocaleString('en-IN');
    }

    if (pendingEl) {
      const pendingCount = feeConcessionsData.filter(function(c) { return c.decision !== 'Approved' && c.decision !== 'Rejected'; }).length;
      pendingEl.textContent = pendingCount + ' Pending Review';
    }
  }

  function openSubmitConcessionModal() {
    const studentSelect = document.getElementById('concStudentSelect');
    if (studentSelect) {
      studentSelect.innerHTML = '<option value="">-- Select Enrolled Student --</option>';
      defaultersData.forEach(function(d) {
        studentSelect.innerHTML += '<option value="' + d.admNo + '">' + d.name + ' (' + d.admNo + ' - ' + d.class + ')</option>';
      });
    }

    openModal('submitConcessionRequestModal');
  }

  function handleSubmitConcessionRequest(e) {
    if (e) e.preventDefault();

    const admNo = document.getElementById('concStudentSelect')?.value;
    const scheme = document.getElementById('concScheme')?.value || 'Merit-Cum-Means Scholarship';
    const requested = document.getElementById('concRequested')?.value || 'Fee Concession Request';
    const proposedAmt = parseFloat(document.getElementById('concProposedAmount')?.value) || 0;
    const evidence = document.getElementById('concEvidence')?.value || 'Official supporting document uploaded';

    const studentRec = defaultersData.find(function(d) { return d.admNo === admNo; });
    const studentName = studentRec ? studentRec.name : 'Applicant Student';
    const studentClass = studentRec ? studentRec.class : 'Class X-A';

    const nextId = 'CONC-2026-0' + (feeConcessionsData.length + 1);
    feeConcessionsData.unshift({
      id: nextId,
      student: studentName,
      admNo: admNo,
      class: studentClass,
      scheme: scheme,
      requested: requested,
      evidence: evidence,
      eligibilityReview: 'Awaiting Clerk Document Check',
      proposedAmount: '₹' + proposedAmt.toLocaleString('en-IN'),
      approver: 'Pending Principal Review',
      decision: 'Pending Review',
      effectiveDates: '01 Nov 2026 - 31 Mar 2027',
      applied: false
    });

    closeModal('submitConcessionRequestModal');
    renderFeeConcessions();
    showToast('Scholarship / concession application ' + nextId + ' registered for ' + studentName + '. Pending eligibility audit.', 'success');
  }

  function verifyConcessionEligibility(id) {
    const item = feeConcessionsData.find(function(c) { return c.id === id; });
    if (item) {
      item.eligibilityReview = 'Verified & Income Criteria Met';
      renderFeeConcessions();
      showToast('Eligibility verified for ' + item.student + ' under ' + item.scheme + '.', 'success');
    }
  }

  function approveConcession(id) {
    const item = feeConcessionsData.find(function(c) { return c.id === id; });
    if (item) {
      item.decision = 'Approved';
      item.approver = 'Smt. Gorle Varalakshmi (Principal)';
      renderFeeConcessions();
      showToast('Concession ' + id + ' officially APPROVED by Principal Smt. Gorle Varalakshmi.', 'success');
    }
  }

  function rejectConcession(id) {
    const reason = prompt('Enter authorized reason for rejecting this concession request:', 'Income slab exceeds statutory criteria for fee waiver');
    if (!reason) return;

    const item = feeConcessionsData.find(function(c) { return c.id === id; });
    if (item) {
      item.decision = 'Rejected';
      item.approver = 'Smt. Gorle Varalakshmi (Principal)';
      renderFeeConcessions();
      showToast('Concession ' + id + ' rejected with institutional reason.', 'warning');
    }
  }

  function openSetConcessionDatesModal(id) {
    const newDates = prompt('Enter authorized effective dates (e.g. 01 Jun 2026 - 31 Mar 2027):', '01 Jun 2026 - 31 Mar 2027');
    if (newDates) {
      const item = feeConcessionsData.find(function(c) { return c.id === id; });
      if (item) {
        item.effectiveDates = newDates;
        renderFeeConcessions();
        showToast('Effective period updated for ' + id + '.', 'success');
      }
    }
  }

  function applyApprovedConcession(id) {
    const item = feeConcessionsData.find(function(c) { return c.id === id; });
    if (!item) return;

    const matchedDef = defaultersData.find(function(d) { return d.admNo === item.admNo; });
    if (!matchedDef) {
      showToast('No outstanding dues found for this student to apply concession.', 'info');
      return;
    }

    const amt = parseFloat(String(item.proposedAmount).replace(/[^0-9.]/g, '')) || 0;
    const currentBal = parseFloat(String(matchedDef.balance || matchedDef.amount).replace(/[^0-9.]/g, '')) || 0;
    const newBal = Math.max(0, currentBal - amt);

    matchedDef.balance = newBal === 0 ? '₹0' : '₹' + newBal.toLocaleString('en-IN');
    item.applied = true;

    // Post to ledger
    const nextTxnId = 'TXN-2026-' + (transactionsLedgerData.length + 8911);
    transactionsLedgerData.unshift({
      txnId: nextTxnId,
      type: 'Scholarship Subsidy Offset',
      amount: '+ ₹' + amt.toLocaleString('en-IN') + '.00',
      rawAmount: amt,
      ref: item.id + ' | ' + item.scheme + ' applied to ' + matchedDef.invoiceNo,
      date: new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }) + ', ' + new Date().toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true }),
      status: 'Reconciled & Locked',
      category: 'concession',
      isReversal: false
    });

    renderDefaultersTable();
    renderTransactionsLedger();
    showToast('Concession of ' + item.proposedAmount + ' applied to ' + matchedDef.name + '\'s invoice ' + matchedDef.invoiceNo + '.', 'success');
  }

  function viewConcessionHistory(id) {
    const item = feeConcessionsData.find(function(c) { return c.id === id; });
    if (!item) return;

    alert(
      'CONCESSION AUDIT HISTORY: ' + item.id + '\n\n' +
      'Student: ' + item.student + ' (' + item.admNo + ')\n' +
      'Class: ' + item.class + '\n' +
      'Scheme: ' + item.scheme + '\n' +
      'Requested: ' + item.requested + '\n' +
      'Evidence: ' + item.evidence + '\n' +
      'Review: ' + item.eligibilityReview + '\n' +
      'Amount: ' + item.proposedAmount + '\n' +
      'Approver: ' + item.approver + '\n' +
      'Decision: ' + item.decision + '\n' +
      'Effective Dates: ' + item.effectiveDates + '\n' +
      'Applied to Ledger: ' + (item.applied ? 'Yes (Offset Active)' : 'No')
    );
  }

  function exportConcessionsCSV() {
    let csv = 'ID,Student,Admission No,Class,Scheme,Requested,Evidence,Eligibility,Proposed Amount,Approver,Decision,Effective Dates\n';
    feeConcessionsData.forEach(function(c) {
      csv += '"' + c.id + '","' + c.student + '","' + c.admNo + '","' + c.class + '","' + c.scheme + '","' + c.requested + '","' + c.evidence + '","' + c.eligibilityReview + '","' + c.proposedAmount + '","' + c.approver + '","' + c.decision + '","' + c.effectiveDates + '"\n';
    });
    downloadCsvFile(csv, 'SriVidya_Fee_Concessions_Scholarships.csv');
    showToast('Fee concessions and scholarships exported to CSV.', 'success');
  }

  // =========================================================================
  // 10.5 REFUNDS CONTROLLER & ACTIONS (SEGREGATION OF DUTIES ENFORCED)
  // =========================================================================

  function renderFeeRefunds(list) {
    const tbody = document.getElementById('refundsTableBody');
    if (!tbody) return;

    const data = list || feeRefundsData;

    if (data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" class="text-center text-muted p-4"><i class="fa-solid fa-folder-open mr-2"></i>No fee refund applications recorded.</td></tr>';
      return;
    }

    tbody.innerHTML = data.map(function(r) {
      const isApproved = r.approvalStatus.includes('Approved');
      const isPending = r.approvalStatus.includes('Pending');

      const statusBadge = isApproved
        ? '<span class="portal-badge badge-success" style="font-size:0.75rem;"><i class="fa-solid fa-circle-check mr-1"></i>Approved by Principal</span>'
        : (isPending
          ? '<span class="portal-badge badge-warning" style="font-size:0.75rem;"><i class="fa-solid fa-shield-halved mr-1"></i>Awaiting Authorization</span>'
          : '<span class="portal-badge badge-danger" style="font-size:0.75rem;"><i class="fa-solid fa-ban mr-1"></i>Rejected</span>');

      const payBadge = r.paymentStatus.includes('Processed') || r.paymentStatus.includes('Disbursed')
        ? '<span class="portal-badge badge-info" style="font-size:0.75rem;"><i class="fa-solid fa-paper-plane mr-1"></i>Disbursed</span>'
        : '<span class="portal-badge badge-secondary" style="font-size:0.75rem;">Pending Disbursement</span>';

      return '<tr>' +
        '<td><strong class="font-mono" style="color:#1e40af;">' + r.originalPayment + '</strong></td>' +
        '<td>' +
          '<div style="font-weight:700; color:var(--color-text-dark);">' + r.student + '</div>' +
          '<div class="font-mono text-muted" style="font-size:0.75rem;">' + r.admNo + ' &bull; ' + r.class + '</div>' +
        '</td>' +
        '<td style="font-size:0.83rem;">' + r.refundReason + '</td>' +
        '<td style="text-align: right; font-weight:700;">' + r.requestedAmount + '</td>' +
        '<td style="text-align: right; font-weight:800; color:#dc2626;">' + r.approvedAmount + '</td>' +
        '<td style="text-align: center;">' + statusBadge + '</td>' +
        '<td style="text-align: center;">' + payBadge + '</td>' +
        '<td style="text-align: center;">' +
          '<div style="display:inline-flex; gap:4px; flex-wrap:wrap; justify-content:center;">' +
            '<button class="btn btn-sm btn-outline-primary" style="padding:2px 7px; font-size:0.75rem;" title="Review Docket & Segregation of Duties" onclick="portalApp.openReviewRefundModal(\'' + r.id + '\')">' +
              '<i class="fa-solid fa-scale-balanced"></i> Review' +
            '</button>' +
            (isApproved && !r.paymentStatus.includes('Disbursed') ? (
              '<button class="btn btn-sm btn-success" style="padding:2px 7px; font-size:0.75rem;" title="Process Bank Disbursement" onclick="portalApp.processRefundPayment(\'' + r.id + '\')">' +
                '<i class="fa-solid fa-money-bill-transfer"></i> Disburse' +
              '</button>'
            ) : '') +
            '<button class="btn btn-sm btn-outline-info" style="padding:2px 7px; font-size:0.75rem;" title="Generate Refund Voucher Slip" onclick="portalApp.generateRefundReceipt(\'' + r.id + '\')">' +
              '<i class="fa-solid fa-receipt"></i> Voucher' +
            '</button>' +
            (!r.reconciled && isApproved ? (
              '<button class="btn btn-sm btn-outline-success" style="padding:2px 7px; font-size:0.75rem;" title="Reconcile against Bank Debit" onclick="portalApp.reconcileRefund(\'' + r.id + '\')">' +
                '<i class="fa-solid fa-check-double"></i>' +
              '</button>'
            ) : '') +
          '</div>' +
        '</td>' +
      '</tr>';
    }).join('');
  }

  function openRequestRefundModal() {
    const originalPaymentSelect = document.getElementById('refOriginalPayment');
    const studentDisplay = document.getElementById('refStudentDisplay');
    const requestedAmount = document.getElementById('refRequestedAmount');
    const recordedByInput = document.getElementById('refRecordedBy');

    if (originalPaymentSelect) {
      originalPaymentSelect.innerHTML = '<option value="">-- Select Completed Collection Receipt --</option>';
      feeCollectionData.forEach(function(r) {
        originalPaymentSelect.innerHTML += '<option value="' + r.receiptNo + '">' + r.receiptNo + ' - ' + r.student + ' (' + r.class + ') - ' + r.amountPaid + '</option>';
      });

      originalPaymentSelect.onchange = function() {
        const sel = feeCollectionData.find(function(r) { return r.receiptNo === originalPaymentSelect.value; });
        if (sel) {
          if (studentDisplay) studentDisplay.value = sel.student + ' (' + sel.admNo + ' - ' + sel.class + ')';
          if (requestedAmount) requestedAmount.value = parseFloat(String(sel.amountPaid).replace(/[^0-9.]/g, '')) || 0;
        }
      };
    }

    if (recordedByInput) {
      recordedByInput.value = 'S. Ramu (Accounts Desk / Cashier)';
    }

    openModal('requestRefundModal');
  }

  function handleRequestRefundSubmit(e) {
    if (e) e.preventDefault();

    const receiptNo = document.getElementById('refOriginalPayment')?.value;
    const reason = document.getElementById('refReason')?.value || 'Parent refund application';
    const amountVal = parseFloat(document.getElementById('refRequestedAmount')?.value) || 0;
    const recordedBy = document.getElementById('refRecordedBy')?.value || 'S. Ramu (Cashier)';

    const sel = feeCollectionData.find(function(r) { return r.receiptNo === receiptNo; });
    if (!sel || amountVal <= 0) {
      showToast('Please select a valid original payment receipt and enter a valid amount.', 'error');
      return;
    }

    const nextId = 'REF-2026-0' + (feeRefundsData.length + 1);
    feeRefundsData.unshift({
      id: nextId,
      originalPayment: sel.receiptNo + ' (' + sel.amountPaid + ')',
      student: sel.student,
      admNo: sel.admNo,
      class: sel.class,
      refundReason: reason,
      requestedAmount: '₹' + amountVal.toLocaleString('en-IN'),
      approvedAmount: '₹0',
      approvalStatus: 'Pending Independent Approval',
      paymentStatus: 'Awaiting Authorization',
      recordedBy: recordedBy,
      approvedBy: null,
      reconciled: false,
      date: new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }),
      receiptNo: null
    });

    closeModal('requestRefundModal');
    renderFeeRefunds();
    showToast('Refund request ' + nextId + ' registered. Note: Per segregation of duties policy, the person recording (' + recordedBy + ') cannot approve it.', 'success');
  }

  function openReviewRefundModal(id) {
    const item = feeRefundsData.find(function(r) { return r.id === id; });
    if (!item) return;

    const body = document.getElementById('reviewRefundBody');
    const footer = document.getElementById('reviewRefundFooter');
    if (!body || !footer) return;

    body.innerHTML = 
      '<div style="background:#eff6ff; border:1px solid #bfdbfe; border-radius:6px; padding:10px 14px; margin-bottom:1rem;">' +
        '<div style="font-weight:700; color:#1e40af; font-size:0.92rem;">' +
          '<i class="fa-solid fa-shield-halved mr-1"></i> Segregation of Duties Statutory Guard' +
        '</div>' +
        '<div style="font-size:0.83rem; color:#1e3a8a; margin-top:2px;">' +
          'This refund request was initiated by <strong>' + item.recordedBy + '</strong>. Financial regulations strictly forbid the initiating cashier from approving refund disbursements. Independent executive approval by the Principal is required.' +
        '</div>' +
      '</div>' +
      '<div style="display:grid; grid-template-columns:1fr 1fr; gap:0.75rem; font-size:0.88rem;">' +
        '<div><span class="text-muted">Refund ID:</span> <strong>' + item.id + '</strong></div>' +
        '<div><span class="text-muted">Original Payment:</span> <strong>' + item.originalPayment + '</strong></div>' +
        '<div><span class="text-muted">Student:</span> <strong>' + item.student + ' (' + item.admNo + ')</strong></div>' +
        '<div><span class="text-muted">Class & Section:</span> <strong>' + item.class + '</strong></div>' +
        '<div><span class="text-muted">Requested Amount:</span> <strong style="color:#dc2626; font-size:1.05rem;">' + item.requestedAmount + '</strong></div>' +
        '<div><span class="text-muted">Initiation Date:</span> <strong>' + item.date + '</strong></div>' +
        '<div style="grid-column:span 2;"><span class="text-muted">Refund Reason:</span> <strong>' + item.refundReason + '</strong></div>' +
        '<div style="grid-column:span 2;"><span class="text-muted">Recorded By:</span> <span class="portal-badge badge-warning">' + item.recordedBy + '</span></div>' +
        '<div style="grid-column:span 2;"><span class="text-muted">Current Approver Role:</span> <span class="portal-badge badge-success">Principal Smt. Gorle Varalakshmi (Full Authority)</span></div>' +
      '</div>';

    footer.innerHTML = 
      '<button type="button" class="btn btn-secondary" onclick="portalApp.closeModal(\'reviewRefundModal\')">Cancel</button>' +
      '<button type="button" class="btn btn-danger" onclick="portalApp.rejectRefund(\'' + item.id + '\')">' +
        '<i class="fa-solid fa-xmark mr-1"></i> Reject with Reason' +
      '</button>' +
      '<button type="button" class="btn btn-success" onclick="portalApp.approveRefund(\'' + item.id + '\')">' +
        '<i class="fa-solid fa-signature mr-1"></i> Authorize & Sanction (' + item.requestedAmount + ')' +
      '</button>';

    openModal('reviewRefundModal');
  }

  function approveRefund(id) {
    const item = feeRefundsData.find(function(r) { return r.id === id; });
    if (!item) return;

    item.approvalStatus = 'Approved by Principal';
    item.approvedAmount = item.requestedAmount;
    item.approvedBy = 'Smt. Gorle Varalakshmi (Principal)';
    item.receiptNo = 'REF-RCPT-2026-0' + (feeRefundsData.length + 1);

    // Post Debit Entry to Financial Ledger
    const numAmt = parseFloat(String(item.requestedAmount).replace(/[^0-9.]/g, '')) || 0;
    const nextTxnId = 'TXN-2026-' + (transactionsLedgerData.length + 8911);
    transactionsLedgerData.unshift({
      txnId: nextTxnId,
      type: 'Debit (Sanctioned Refund)',
      amount: '- ₹' + numAmt.toLocaleString('en-IN') + '.00',
      rawAmount: -numAmt,
      ref: item.id + ' | Offset against ' + item.originalPayment + ' | ' + item.student,
      date: new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }) + ', ' + new Date().toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true }),
      status: 'Awaiting Bank Match',
      category: 'refund',
      isReversal: false
    });

    closeModal('reviewRefundModal');
    renderFeeRefunds();
    renderTransactionsLedger();

    showToast('Refund ' + item.id + ' for ' + item.requestedAmount + ' approved by Principal. Financial debit posted to ledger.', 'success');
  }

  function rejectRefund(id) {
    const reason = prompt('Enter official policy grounds for rejecting this refund request:', 'Non-refundable fee head per institutional admissions policy');
    if (!reason) return;

    const item = feeRefundsData.find(function(r) { return r.id === id; });
    if (item) {
      item.approvalStatus = 'Rejected: ' + reason;
      item.approvedAmount = '₹0';
      item.approvedBy = 'Smt. Gorle Varalakshmi (Principal)';
      closeModal('reviewRefundModal');
      renderFeeRefunds();
      showToast('Refund request ' + id + ' rejected with recorded justification.', 'warning');
    }
  }

  function processRefundPayment(id) {
    const item = feeRefundsData.find(function(r) { return r.id === id; });
    if (item) {
      item.paymentStatus = 'Processed & Disbursed via Bank Transfer';
      renderFeeRefunds();
      showToast('Disbursement of ' + item.approvedAmount + ' processed via SBI NEFT transfer.', 'success');
    }
  }

  function reconcileRefund(id) {
    const item = feeRefundsData.find(function(r) { return r.id === id; });
    if (item) {
      item.reconciled = true;
      const ledgerEntry = transactionsLedgerData.find(function(t) { return t.ref.includes(item.id); });
      if (ledgerEntry) ledgerEntry.status = 'Reconciled & Locked';
      renderFeeRefunds();
      renderTransactionsLedger();
      showToast('Refund ' + item.id + ' reconciled against bank account debit.', 'success');
    }
  }

  function generateRefundReceipt(id) {
    const item = feeRefundsData.find(function(r) { return r.id === id; });
    if (!item) return;

    alert(
      'SRI VIDYA E.M. HIGH SCHOOL - OFFICIAL REFUND DEBIT VOUCHER\n\n' +
      'Voucher No: ' + (item.receiptNo || 'VCH-REF-PENDING') + '\n' +
      'Refund Docket: ' + item.id + '\n' +
      'Student: ' + item.student + ' (' + item.admNo + ' - ' + item.class + ')\n' +
      'Original Credit: ' + item.originalPayment + '\n' +
      'Amount Refunded: ' + (item.approvedAmount || item.requestedAmount) + '\n' +
      'Reason: ' + item.refundReason + '\n' +
      'Initiated By: ' + item.recordedBy + '\n' +
      'Authorized By: ' + (item.approvedBy || 'Pending Executive Review') + '\n' +
      'Status: ' + item.approvalStatus + ' | ' + item.paymentStatus + '\n' +
      'Statutory Note: Immutable ledger adjustment verified.'
    );
  }

  function exportRefundsCSV() {
    let csv = 'Refund ID,Original Payment,Student,Admission No,Class,Reason,Requested Amount,Approved Amount,Approval Status,Payment Status,Recorded By,Approved By,Date\n';
    feeRefundsData.forEach(function(r) {
      csv += '"' + r.id + '","' + r.originalPayment + '","' + r.student + '","' + r.admNo + '","' + r.class + '","' + r.refundReason + '","' + r.requestedAmount + '","' + r.approvedAmount + '","' + r.approvalStatus + '","' + r.paymentStatus + '","' + r.recordedBy + '","' + (r.approvedBy || '') + '","' + r.date + '"\n';
    });
    downloadCsvFile(csv, 'SriVidya_Fee_Refunds_Register.csv');
    showToast('Fee refunds register exported to CSV.', 'success');
  }

  // =========================================================================
  // 10.6 FINANCIAL REPORTS & LEDGER (IMMUTABLE AUDIT TRAIL)
  // =========================================================================

  function renderTransactionsLedger(filterType) {
    const tbody = document.getElementById('transactionsLedgerTableBody');
    if (!tbody) return;

    let data = transactionsLedgerData;

    if (filterType === 'credit') {
      data = data.filter(function(t) { return t.type.includes('Credit'); });
    } else if (filterType === 'debit') {
      data = data.filter(function(t) { return t.type.includes('Debit') || t.type.includes('Reversal'); });
    } else if (filterType === 'reconciled') {
      data = data.filter(function(t) { return t.status.includes('Reconciled'); });
    } else if (filterType === 'pending') {
      data = data.filter(function(t) { return !t.status.includes('Reconciled'); });
    }

    if (data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" class="text-center text-muted p-4"><i class="fa-solid fa-folder-open mr-2"></i>No ledger entries found for this filter.</td></tr>';
      return;
    }

    tbody.innerHTML = data.map(function(t) {
      const isCredit = t.amount.startsWith('+');
      const amtColor = isCredit ? '#16a34a' : '#dc2626';

      const typeBadge = isCredit
        ? '<span class="portal-badge badge-success" style="font-size:0.75rem;"><i class="fa-solid fa-arrow-down-left mr-1"></i>Credit</span>'
        : (t.isReversal
          ? '<span class="portal-badge badge-warning" style="font-size:0.75rem;"><i class="fa-solid fa-rotate-left mr-1"></i>Reversal</span>'
          : '<span class="portal-badge badge-danger" style="font-size:0.75rem;"><i class="fa-solid fa-arrow-up-right mr-1"></i>Debit</span>');

      const isLocked = t.status.includes('Locked');
      const statusBadge = isLocked
        ? '<span class="portal-badge badge-success" style="font-size:0.73rem;"><i class="fa-solid fa-lock mr-1"></i>Reconciled & Locked</span>'
        : '<span class="portal-badge badge-warning" style="font-size:0.73rem;"><i class="fa-solid fa-clock mr-1"></i>Pending Bank Match</span>';

      return '<tr>' +
        '<td><strong class="font-mono" style="color:#0f172a;">' + t.txnId + '</strong></td>' +
        '<td>' + typeBadge + ' <small style="margin-left:4px; font-weight:600;">' + t.type + '</small></td>' +
        '<td style="text-align: right; font-weight:800; font-size:0.95rem; color:' + amtColor + ';">' + t.amount + '</td>' +
        '<td><span style="font-size:0.83rem; font-family:var(--font-mono, monospace); color:#334155;">' + t.ref + '</span></td>' +
        '<td style="font-size:0.82rem;">' + t.date + '</td>' +
        '<td style="text-align: center;">' + statusBadge + '</td>' +
        '<td style="text-align: center;">' +
          '<div style="display:inline-flex; gap:4px; justify-content:center;">' +
            '<button class="btn btn-sm btn-outline-primary" style="padding:2px 7px; font-size:0.75rem;" title="View Immutable Audit Detail" onclick="alert(\'AUDIT CERTIFICATE: \\nTransaction ID: ' + t.txnId + '\\nType: ' + t.type + '\\nAmount: ' + t.amount + '\\nTraceable Ref: ' + t.ref.replace(/'/g, "\\'") + '\\nTimestamp: ' + t.date + '\\nStatus: ' + t.status + '\\nImmutability Rule: Transactions cannot be edited or deleted; corrected exclusively via counterbalance reversal entries.\')">' +
              '<i class="fa-solid fa-magnifying-glass"></i> Audit' +
            '</button>' +
            '<button class="btn btn-sm btn-outline-secondary" style="padding:2px 7px; font-size:0.75rem;" title="Print Ledger Voucher" onclick="window.print()">' +
              '<i class="fa-solid fa-print"></i>' +
            '</button>' +
          '</div>' +
        '</td>' +
      '</tr>';
    }).join('');
  }

  function setLedgerFilter(filterType) {
    renderTransactionsLedger(filterType);
    showToast('Ledger filtered by: ' + filterType.toUpperCase(), 'info');
  }

  function openFilterDateRangeModal() {
    const fromDate = prompt('Filter ledger entries from date (YYYY-MM-DD):', '2026-09-01');
    if (fromDate) {
      showToast('Transactions filtered from ' + fromDate + ' to current timestamp.', 'info');
    }
  }

  function reconcilePendingTransactions() {
    let reconciledCount = 0;
    transactionsLedgerData.forEach(function(t) {
      if (!t.status.includes('Locked')) {
        t.status = 'Reconciled & Locked';
        reconciledCount++;
      }
    });

    renderTransactionsLedger();
    showToast(reconciledCount + ' pending transactions reconciled and locked against SBI core banking statement.', 'success');
  }

  function printFinancialStatement() {
    window.print();
  }

  function exportAuthorizedFinancialReport() {
    exportTransactionsLedgerCSV();
  }

  function exportTransactionsLedgerCSV() {
    let csv = 'Transaction ID,Type,Amount,Traceable Reference & Offsets,Recorded Timestamp,Reconciliation Status\n';
    transactionsLedgerData.forEach(function(t) {
      csv += '"' + t.txnId + '","' + t.type + '","' + t.amount + '","' + t.ref + '","' + t.date + '","' + t.status + '"\n';
    });
    downloadCsvFile(csv, 'SriVidya_Traceable_Transactions_Ledger_2026-27.csv');
    showToast('Immutable transactions ledger exported to CSV.', 'success');
  }

