  function renderTimetableClassSchedules() {
    const classData = TIMETABLE_CLASS_DATA[currentTimetableClass] || TIMETABLE_CLASS_DATA['Class X-A'];

    const nameEl = document.getElementById('ttSummaryClassName');
    if (nameEl) nameEl.textContent = currentTimetableClass;

    const roomEl = document.getElementById('ttSummaryRoom');
    if (roomEl) roomEl.textContent = classData.room;

    const teacherEl = document.getElementById('ttSummaryTeacher');
    if (teacherEl) teacherEl.textContent = classData.classTeacher;

    const badgeEl = document.getElementById('ttHeaderBadge');
    if (badgeEl) badgeEl.textContent = currentTimetableClass + ' • ' + classData.room;

    if (currentTimetableCalendarView === 'weekly') {
      renderTimetableWeeklyView();
    } else if (currentTimetableCalendarView === 'daily') {
      renderTimetableDailyView();
    } else if (currentTimetableCalendarView === 'class-wise') {
      renderTimetableClassWiseView();
    }
  }

  function renderTimetableWeeklyView() {
    const container = document.getElementById('ttCalendarContent');
    if (!container) return;

    const classData = TIMETABLE_CLASS_DATA[currentTimetableClass] || TIMETABLE_CLASS_DATA['Class X-A'];
    const days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

    let html = `
      <div class="table-responsive">
        <table class="data-table" style="width:100%; border-collapse:collapse;">
          <thead>
            <tr style="background:#f8fafc; border-bottom:2px solid #e2e8f0;">
              <th style="width:14%; text-align:center; padding:0.75rem;"><i class="fa-regular fa-clock"></i> Day &amp; Period</th>
              ${days.map(d => `<th style="width:14.3%; text-align:center; padding:0.75rem;">${d}</th>`).join('')}
            </tr>
          </thead>
          <tbody>
    `;

    classData.periods.forEach((p, pIdx) => {
      if (p.isBreak) {
        html += `
          <tr style="background:#fefce8; border-top:1px solid #fef08a; border-bottom:1px solid #fef08a;">
            <td style="text-align:center; font-weight:700; color:#854d0e; padding:0.6rem; font-size:0.8125rem;">
              ${p.period}<br><small style="color:#a16207;">${p.time}</small>
            </td>
            <td colspan="6" style="text-align:center; font-weight:700; color:#854d0e; letter-spacing:0.04em; padding:0.6rem; font-size:0.85rem;">
              <i class="${p.icon || 'fa-solid fa-bell'} mr-1"></i> ${p.title} (${p.time})
            </td>
          </tr>
        `;
      } else {
        html += `
          <tr style="border-bottom:1px solid #e2e8f0;">
            <td style="text-align:center; font-weight:700; background:#f8fafc; padding:0.6rem; vertical-align:middle;">
              <div style="font-size:0.875rem; color:#0f172a;">${p.period}</div>
              <div style="font-size:0.75rem; color:#64748b; margin-top:0.15rem;"><i class="fa-regular fa-clock"></i> ${p.time}</div>
            </td>
        `;

        days.forEach(day => {
          const slot = p[day] || { subject: 'Study Hour', teacher: 'Class Teacher', room: classData.room };
          const badgeClass = slot.badgeClass || 'badge-primary';

          html += `
            <td style="padding:0.5rem; vertical-align:top;">
              <div class="tt-slot-card" style="background:#ffffff; border:1px solid #e2e8f0; border-radius:6px; padding:0.5rem; transition:all 0.2s ease;">
                <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:0.35rem;">
                  <span class="portal-badge ${badgeClass}" style="font-size:0.75rem; font-weight:700; padding:0.15rem 0.55rem; border-radius:4px;">
                    ${slot.subject}
                  </span>
                  ${ttIsDraftMode ? `
                    <button type="button" class="btn btn-xs btn-link text-primary" style="padding:0; font-size:0.75rem;" onclick="portalApp.openEditScheduleSlotModal('${day}', ${pIdx}, '${currentTimetableClass}')" title="Edit Period Slot">
                      <i class="fa-solid fa-pen-to-square"></i>
                    </button>
                  ` : ''}
                </div>
                <div style="font-size:0.8rem; font-weight:600; color:#1e293b; display:flex; align-items:center; gap:0.3rem;">
                  <i class="fa-solid fa-chalkboard-user text-muted" style="font-size:0.75rem;"></i> ${slot.teacher}
                </div>
                <div style="font-size:0.72rem; color:#64748b; margin-top:0.25rem; display:flex; align-items:center; gap:0.25rem;">
                  <span class="tt-room-pill" style="font-size:0.7rem; background:#f1f5f9; padding:0.1rem 0.4rem; border-radius:3px;">
                    <i class="fa-solid fa-door-open text-primary"></i> ${slot.room || classData.room}
                  </span>
                </div>
              </div>
            </td>
          `;
        });

        html += '</tr>';
      }
    });

    html += `
          </tbody>
        </table>
      </div>
    `;

    container.innerHTML = html;
  }

