  // =========================================================================
  // SUBMENU 2: SUBSTITUTION PLANNER RENDERER & ACTIONS
  // =========================================================================

  function renderSubstitutionPlanner() {
    const tbody = document.getElementById('substitutionPlannerTableBody');
    if (!tbody) return;

    const classFilter = document.getElementById('subClassFilter')?.value || 'all';
    const periodFilter = document.getElementById('subPeriodFilter')?.value || 'all';
    const statusFilter = document.getElementById('subStatusFilter')?.value || 'all';
    const searchVal = (document.getElementById('subSearchInput')?.value || '').toLowerCase().trim();

    const filtered = SUBSTITUTION_PLANNER_DATA.filter(item => {
      const matchClass = classFilter === 'all' || item.class === classFilter;
      const matchPeriod = periodFilter === 'all' || item.period === periodFilter;
      const matchStatus = statusFilter === 'all' || item.status === statusFilter;
      const matchSearch = !searchVal ||
        item.absentTeacher.toLowerCase().includes(searchVal) ||
        item.replacementTeacher.toLowerCase().includes(searchVal) ||
        item.class.toLowerCase().includes(searchVal) ||
        item.originalSubject.toLowerCase().includes(searchVal) ||
        (item.topic && item.topic.toLowerCase().includes(searchVal));
      return matchClass && matchPeriod && matchStatus && matchSearch;
    });

    // Update KPI counts based on full roster
    const absentCount = new Set(SUBSTITUTION_PLANNER_DATA.map(i => i.absentTeacher)).size;
    const totalPeriodsToCover = SUBSTITUTION_PLANNER_DATA.length;
    const coveredCount = SUBSTITUTION_PLANNER_DATA.filter(i => i.replacementTeacher !== 'Unassigned').length;
    const pendingCount = SUBSTITUTION_PLANNER_DATA.filter(i => i.replacementTeacher === 'Unassigned').length;

    const elAbsentCount = document.getElementById('subAbsentFacultyCount');
    if (elAbsentCount) elAbsentCount.textContent = absentCount + ' Teachers';

    const elCoverCount = document.getElementById('subCoverRequiredCount');
    if (elCoverCount) elCoverCount.textContent = totalPeriodsToCover + ' Periods';

    const elAssignedCount = document.getElementById('subAssignedCount');
    if (elAssignedCount) elAssignedCount.textContent = coveredCount + ' Covered';

    const elPendingCount = document.getElementById('subPendingCount');
    if (elPendingCount) elPendingCount.textContent = pendingCount + ' Pending';

    const elBadgeCount = document.getElementById('subBadgeCount');
    if (elBadgeCount) elBadgeCount.textContent = filtered.length + ' Roster Entries';

    // Update banner text
    const bannerText = document.getElementById('subRosterStatusText');
    const banner = document.getElementById('subRosterStatusBanner');
    if (banner && bannerText) {
      if (pendingCount > 0) {
        banner.style.background = '#fefce8';
        banner.style.borderLeft = '4px solid #eab308';
        bannerText.innerHTML = '<strong>' + pendingCount + ' Period(s) Require Emergency Replacement:</strong> All remaining slots have assigned coverage. Review workload and confirm allocation before bell time.';
      } else {
        banner.style.background = '#ecfdf5';
        banner.style.borderLeft = '4px solid #10b981';
        bannerText.innerHTML = '<strong class="text-emerald">All ' + totalPeriodsToCover + ' Affected Periods Fully Covered:</strong> Replacement teachers have verified free periods with 0 schedule collisions. Ready to publish and dispatch.';
      }
    }

    if (filtered.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" class="text-center py-4 text-muted"><i class="fa-solid fa-folder-open mb-2" style="font-size:1.5rem; display:block;"></i>No faculty substitutions match the selected filter criteria.</td></tr>';
      return;
    }

    tbody.innerHTML = filtered.map(item => {
      const isUnassigned = item.replacementTeacher === 'Unassigned';
      return `
        <tr style="vertical-align: middle;">
          <!-- 1. Absent Teacher -->
          <td>
            <div class="sub-teacher-cell">
              <span class="sub-teacher-name" style="color:#b91c1c; font-weight:700;">
                <i class="fa-solid fa-user-xmark mr-1"></i> ${item.absentTeacher}
              </span>
              <span class="sub-subject-pill" style="background:#fee2e2; color:#991b1b;">
                ${item.absentTeacherDept || 'Faculty'}
              </span>
              <span class="sub-reason-text" title="${item.absentReason}">
                <i class="fa-solid fa-file-waveform text-muted"></i> ${item.absentReason}
              </span>
            </div>
          </td>

          <!-- 2. Affected Class -->
          <td style="text-align:center;">
            <div class="sub-class-cell">
              <strong style="color:#0f172a; font-size:0.9rem;">${item.class}</strong>
              <span class="tt-room-pill" style="display:inline-flex; align-items:center; gap:0.25rem; font-size:0.75rem; background:#f1f5f9; padding:0.15rem 0.5rem; border-radius:4px; margin-top:0.2rem;">
                <i class="fa-solid fa-door-open text-primary"></i> ${item.room}
              </span>
            </div>
          </td>

          <!-- 3. Period -->
          <td style="text-align:center;">
            <div class="sub-period-badge">
              <strong style="color:#1e293b; font-size:0.9rem;">${item.period}</strong>
              <span class="sub-time-meta" style="display:block; font-size:0.75rem; color:#64748b; margin-top:0.15rem;">
                <i class="fa-regular fa-clock"></i> ${item.time}
              </span>
            </div>
          </td>

          <!-- 4. Original Subject -->
          <td>
            <div style="display:flex; flex-direction:column; gap:0.25rem; align-items:flex-start;">
              <span class="portal-badge badge-primary" style="font-size:0.75rem; font-weight:700; padding:0.2rem 0.6rem; border-radius:9999px;">
                ${item.originalSubject}
              </span>
              <span style="font-size:0.75rem; color:#475569; line-height:1.3;" title="${item.topic}">
                <i class="fa-solid fa-book-bookmark text-muted"></i> ${item.topic}
              </span>
            </div>
          </td>

          <!-- 5. Available Replacement Teacher -->
          <td>
            ${isUnassigned ? `
              <div style="background:#fef2f2; border:1px dashed #f87171; border-radius:6px; padding:0.4rem 0.6rem;">
                <span style="color:#dc2626; font-weight:700; font-size:0.8125rem; display:block;">
                  <i class="fa-solid fa-triangle-exclamation"></i> Unassigned
                </span>
                <span style="font-size:0.75rem; color:#991b1b; display:block;">Emergency Cover Needed</span>
                <button type="button" class="btn btn-xs btn-primary mt-1" style="font-size:0.72rem; padding:0.2rem 0.5rem;" onclick="portalApp.openFindAvailableTeacherModal('${item.period}', '${item.id}')">
                  <i class="fa-solid fa-magnifying-glass"></i> Find Free Teacher
                </button>
              </div>
            ` : `
              <div class="sub-teacher-cell">
                <span class="sub-teacher-name text-primary" style="font-weight:700;">
                  <i class="fa-solid fa-user-check text-emerald"></i> ${item.replacementTeacher}
                </span>
                <span class="sub-role-text" style="font-size:0.75rem; color:#64748b;">${item.replacementRole}</span>
                <div style="display:flex; gap:0.35rem; align-items:center; flex-wrap:wrap; margin-top:0.2rem;">
                  <span class="sub-free-badge" style="font-size:0.7rem; color:#047857; background:#dcfce7; padding:0.12rem 0.45rem; border-radius:4px; font-weight:600;">
                    <i class="fa-solid fa-circle-check"></i> ${item.replacementFree}
                  </span>
                  <span style="font-size:0.7rem; color:#4338ca; background:#e0e7ff; padding:0.12rem 0.45rem; border-radius:4px; font-weight:600;" title="Current teaching load today">
                    <i class="fa-solid fa-gauge"></i> ${item.replacementWorkload}
                  </span>
                </div>
              </div>
            `}
          </td>

          <!-- 6. Replacement Status -->
          <td style="text-align:center;">
            <span class="portal-badge ${item.statusBadge}" style="font-size:0.72rem; font-weight:700; padding:0.3rem 0.65rem; border-radius:9999px; text-transform:uppercase; letter-spacing:0.04em; display:inline-block;">
              ${item.status}
            </span>
            ${item.notified ? '<span style="display:block; font-size:0.7rem; color:#059669; margin-top:0.25rem;"><i class="fa-solid fa-paper-plane"></i> SMS Dispatched</span>' : ''}
          </td>

          <!-- Actions -->
          <td style="text-align:center;">
            <div style="display:flex; gap:0.3rem; justify-content:center; align-items:center;">
              <button type="button" class="btn btn-secondary btn-sm" style="padding:0.3rem 0.5rem;" onclick="portalApp.openAssignSubstitutionModal('${item.id}')" title="Assign / Reassign Faculty">
                <i class="fa-solid fa-user-pen"></i>
              </button>
              <button type="button" class="btn btn-secondary btn-sm" style="padding:0.3rem 0.5rem;" onclick="portalApp.openNotifySubstitutionModal('${item.id}')" title="Send SMS Notice to Covering Teacher">
                <i class="fa-solid fa-paper-plane text-emerald"></i>
              </button>
              <button type="button" class="btn btn-primary btn-sm" style="padding:0.3rem 0.5rem;" onclick="portalApp.confirmSingleSubstitutionSignoff('${item.id}')" title="Sign-Off / Verify Substitution">
                <i class="fa-solid fa-check"></i>
              </button>
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

  function filterSubstitutionPlanner() {
    renderSubstitutionPlanner();
  }

  function resetSubstitutionFilters() {
    const elClass = document.getElementById('subClassFilter');
    const elPeriod = document.getElementById('subPeriodFilter');
    const elStatus = document.getElementById('subStatusFilter');
    const elSearch = document.getElementById('subSearchInput');

    if (elClass) elClass.value = 'all';
    if (elPeriod) elPeriod.value = 'all';
    if (elStatus) elStatus.value = 'all';
    if (elSearch) elSearch.value = '';

    renderSubstitutionPlanner();
    showToast('Substitution filters reset to default view.', 'info');
  }

  // ACTION 1: FIND AVAILABLE TEACHER
  function openFindAvailableTeacherModal(targetPeriod, targetSlotId) {
    const periodSelect = document.getElementById('findTeacherPeriodSelect');
    if (periodSelect && targetPeriod) {
      periodSelect.value = targetPeriod;
    }

    const modal = document.getElementById('findAvailableTeacherModal');
    if (modal) {
      modal.setAttribute('data-target-slot', targetSlotId || '');
      modal.style.display = 'flex';
      runFindAvailableTeachersScan();
    }
  }

  function runFindAvailableTeachersScan() {
    const periodSelect = document.getElementById('findTeacherPeriodSelect');
    const deptSelect = document.getElementById('findTeacherDeptSelect');
    const tbody = document.getElementById('findAvailableTeacherTableBody');
    const badgeCount = document.getElementById('findTeacherAvailableCountBadge');

    if (!periodSelect || !tbody) return;

    const period = periodSelect.value;
    const dept = deptSelect ? deptSelect.value : 'all';
    const modal = document.getElementById('findAvailableTeacherModal');
    const targetSlotId = modal ? modal.getAttribute('data-target-slot') : '';

    // Filter teachers who are FREE in this period and match department
    const freeTeachers = TEACHER_WORKLOAD_DATA.filter(t => {
      const pInfo = t.periods[period];
      const isFree = pInfo && pInfo.status === 'Free';
      const matchDept = dept === 'all' || t.dept === dept;
      return isFree && matchDept;
    });

    // Sort by lowest current daily teaching load to avoid fatigue
    freeTeachers.sort((a, b) => a.assignedCount - b.assignedCount);

    if (badgeCount) {
      badgeCount.textContent = freeTeachers.length + ' Verified Free Teachers';
    }

    if (freeTeachers.length === 0) {
      tbody.innerHTML = '<tr><td colspan="5" class="text-center py-4 text-muted"><i class="fa-solid fa-circle-exclamation text-amber mb-2" style="font-size:1.5rem; display:block;"></i>No faculty members have free periods in ' + period + ' matching the department criteria.</td></tr>';
      return;
    }

    tbody.innerHTML = freeTeachers.map(t => {
      let loadClass = 'badge-success';
      if (t.assignedCount >= 5) loadClass = 'badge-warning';
      if (t.assignedCount >= t.maxCap) loadClass = 'badge-danger';

      return `
        <tr>
          <td>
            <div style="font-weight:700; color:#0f172a;">${t.name}</div>
            <div style="font-size:0.75rem; color:#64748b;">${t.role}</div>
          </td>
          <td>
            <span class="portal-badge badge-primary" style="font-size:0.75rem;">${t.dept}</span>
          </td>
          <td style="text-align:center;">
            <span class="portal-badge ${loadClass}" style="font-size:0.75rem; font-weight:700;">
              ${t.assignedCount} / ${t.maxCap} Periods
            </span>
          </td>
          <td style="text-align:center;">
            <span class="portal-badge badge-success" style="font-size:0.75rem;">
              <i class="fa-solid fa-circle-check"></i> Free in ${period}
            </span>
          </td>
          <td style="text-align:center;">
            <button type="button" class="btn btn-primary btn-sm" onclick="portalApp.quickAssignSubstitute('${targetSlotId}', '${t.name}')">
              <i class="fa-solid fa-plus"></i> Assign Now
            </button>
          </td>
        </tr>
      `;
    }).join('');
  }

  function quickAssignSubstitute(slotId, teacherName) {
    const slot = SUBSTITUTION_PLANNER_DATA.find(s => s.id === slotId) || SUBSTITUTION_PLANNER_DATA.find(s => s.replacementTeacher === 'Unassigned');
    const teacher = TEACHER_WORKLOAD_DATA.find(t => t.name === teacherName);

    if (!slot) {
      showToast('No active unassigned substitution slot found.', 'warning');
      return;
    }

    slot.replacementTeacher = teacherName;
    slot.replacementRole = teacher ? teacher.role : 'Covering Faculty';
    slot.replacementFree = 'Free in ' + slot.period + ' (0 Clashes)';
    slot.replacementWorkload = teacher ? (teacher.assignedCount + 1) + ' / ' + teacher.maxCap + ' periods today' : '4 / 6 periods';
    slot.status = 'Confirmed';
    slot.statusBadge = 'badge-success';

    // Update teacher workload
    if (teacher && teacher.periods[slot.period]) {
      teacher.periods[slot.period] = {
        status: 'Substituted',
        class: slot.class,
        subject: slot.originalSubject + ' (Cover for ' + slot.absentTeacher + ')'
      };
      teacher.assignedCount += 1;
    }

    closeModal('findAvailableTeacherModal');
    renderSubstitutionPlanner();
    showToast('Successfully assigned ' + teacherName + ' to cover ' + slot.class + ' (' + slot.period + ')!', 'success');
  }

  // ACTION 2: ASSIGN SUBSTITUTE MODAL & SUBMIT
  function openAssignSubstitutionModal(slotId) {
    const select = document.getElementById('subSlotSelect');
    if (select) {
      if (slotId) select.value = slotId;
      onSelectSubstitutionSlot(select.value);
    }
    openModal('assignSubstitutionModal');
  }

  function onSelectSubstitutionSlot(slotId) {
    const slot = SUBSTITUTION_PLANNER_DATA.find(s => s.id === slotId);
    if (!slot) return;

    const elAbsent = document.getElementById('subAbsentTeacherDisplay');
    const elClass = document.getElementById('subClassPeriodDisplay');
    const elSubj = document.getElementById('subOriginalSubjectDisplay');
    const elRoom = document.getElementById('subRoomDisplay');
    const elInstr = document.getElementById('subInstructions');
    const elSubTeacher = document.getElementById('substituteTeacher');

    if (elAbsent) elAbsent.value = slot.absentTeacher + ' (' + (slot.absentTeacherDept || 'Faculty') + ' - ' + slot.absentReason + ')';
    if (elClass) elClass.value = slot.class + ' (' + slot.period + ': ' + slot.time + ')';
    if (elSubj) elSubj.value = slot.originalSubject;
    if (elRoom) elRoom.value = slot.room;
    if (elInstr && slot.topic) elInstr.value = 'Conduct ' + slot.topic + ' & class workbook corrections';

    // Populate substitute options filtered for this period
    if (elSubTeacher) {
      const freeTeachers = TEACHER_WORKLOAD_DATA.filter(t => {
        const p = t.periods[slot.period];
        return p && (p.status === 'Free' || t.name === slot.replacementTeacher);
      }).sort((a, b) => a.assignedCount - b.assignedCount);

      if (freeTeachers.length > 0) {
        elSubTeacher.innerHTML = freeTeachers.map(t => {
          const isSelected = t.name === slot.replacementTeacher ? 'selected' : '';
          return '<option value="' + t.name + '" ' + isSelected + '>' + t.name + ' (' + t.role + ' - ' + t.assignedCount + '/' + t.maxCap + ' periods today - Free in ' + slot.period + ')</option>';
        }).join('');
      }
    }
  }

  function handleAssignSubstitutionSubmit(event) {
    if (event && event.preventDefault) event.preventDefault();

    const select = document.getElementById('subSlotSelect');
    const slotId = select ? select.value : 'SUB-2026-005';
    const subTeacherName = document.getElementById('substituteTeacher')?.value || 'Sri V. Ramesh Babu';
    const instructions = document.getElementById('subInstructions')?.value || 'Supervised study';
    const notifyCheck = document.getElementById('subNotifyTeacherCheckbox')?.checked;

    const slot = SUBSTITUTION_PLANNER_DATA.find(s => s.id === slotId);
    const teacher = TEACHER_WORKLOAD_DATA.find(t => t.name === subTeacherName);

    if (slot) {
      slot.replacementTeacher = subTeacherName;
      slot.replacementRole = teacher ? teacher.role : 'Covering Faculty';
      slot.replacementFree = 'Free in ' + slot.period + ' (0 Clashes)';
      slot.replacementWorkload = teacher ? (teacher.assignedCount + 1) + ' / ' + teacher.maxCap + ' periods today' : '4 / 6 periods';
      slot.topic = instructions;
      slot.status = 'Confirmed';
      slot.statusBadge = 'badge-success';
      if (notifyCheck) slot.notified = true;

      // Update teacher workload
      if (teacher && teacher.periods[slot.period]) {
        teacher.periods[slot.period] = {
          status: 'Substituted',
          class: slot.class,
          subject: slot.originalSubject + ' (Cover for ' + slot.absentTeacher + ')'
        };
        teacher.assignedCount += 1;
      }
    }

    closeModal('assignSubstitutionModal');
    renderSubstitutionPlanner();
    showToast('Faculty substitution confirmed for ' + subTeacherName + ' covering ' + (slot ? slot.class : 'Class') + '!' + (notifyCheck ? ' (SMS Notice Dispatched)' : ''), 'success');
  }

  // ACTION 3: CHECK WORKLOAD MODAL
  function openTeacherWorkloadModal() {
    const tbody = document.getElementById('teacherWorkloadTableBody');
    if (tbody) {
      tbody.innerHTML = TEACHER_WORKLOAD_DATA.map(t => {
        let loadTag = 'badge-success';
        let loadLabel = 'Optimal Load';
        if (t.assignedCount === 5) { loadTag = 'badge-warning'; loadLabel = 'Moderate'; }
        if (t.assignedCount >= t.maxCap) { loadTag = 'badge-danger'; loadLabel = 'At Cap'; }
        if (t.assignedCount === 0) { loadTag = 'badge-secondary'; loadLabel = 'On Leave'; }

        const periodsHtml = ['Period 1', 'Period 2', 'Period 3', 'Period 4', 'Period 5', 'Period 6', 'Period 7', 'Period 8'].map(pKey => {
          const p = t.periods[pKey];
          if (!p || p.status === 'Free') {
            return '<td style="text-align:center; background:#f0fdf4; color:#166534; font-size:0.75rem; font-weight:700;">FREE</td>';
          }
          if (p.status === 'Substituted') {
            return '<td style="text-align:center; background:#fef3c7; color:#92400e; font-size:0.72rem; font-weight:700;" title="' + (p.subject || '') + '">SUB<br><small>' + (p.class || '') + '</small></td>';
          }
          if (p.status === 'On Leave') {
            return '<td style="text-align:center; background:#fee2e2; color:#991b1b; font-size:0.72rem; font-weight:700;">LEAVE</td>';
          }
          return '<td style="text-align:center; background:#f1f5f9; color:#0f172a; font-size:0.72rem; font-weight:600;" title="' + (p.subject || '') + '">' + (p.class || 'Class') + '</td>';
        }).join('');

        return `
          <tr>
            <td>
              <div style="font-weight:700; color:#0f172a;">${t.name}</div>
              <div style="font-size:0.75rem; color:#64748b;">${t.role}</div>
            </td>
            ${periodsHtml}
            <td style="text-align:center;">
              <span class="portal-badge ${loadTag}" style="font-size:0.75rem; font-weight:700;">
                ${t.assignedCount} / ${t.maxCap} (${loadLabel})
              </span>
            </td>
          </tr>
        `;
      }).join('');
    }

    const modal = document.getElementById('teacherWorkloadModal');
    if (modal) modal.style.display = 'flex';
  }

  // ACTION 4: NOTIFY AFFECTED TEACHERS
  function openNotifySubstitutionModal(slotId) {
    const list = document.getElementById('notifyRecipientsList');
    if (list) {
      let targetSlots = SUBSTITUTION_PLANNER_DATA;
      if (slotId) {
        targetSlots = SUBSTITUTION_PLANNER_DATA.filter(s => s.id === slotId);
      }

      list.innerHTML = targetSlots.map(slot => `
        <div style="background:#f8fafc; border:1px solid #e2e8f0; border-radius:6px; padding:0.6rem 0.85rem; display:flex; justify-content:space-between; align-items:center;">
          <div>
            <div style="font-weight:700; font-size:0.875rem; color:#0f172a;">
              To: ${slot.replacementTeacher} <span class="portal-badge badge-primary" style="font-size:0.7rem;">Covering Faculty</span>
            </div>
            <div style="font-size:0.75rem; color:#475569; margin-top:0.2rem;">
              "SRI VIDYA EM SCHOOL: You are deputed to cover <strong>${slot.class}</strong> in <strong>${slot.period} (${slot.time})</strong> in Room <strong>${slot.room}</strong> for ${slot.absentTeacher} (${slot.originalSubject}). Ref: #${slot.id}"
            </div>
          </div>
          <span class="portal-badge ${slot.notified ? 'badge-success' : 'badge-warning'}" style="font-size:0.72rem;">
            ${slot.notified ? 'Dispatched' : 'Queued'}
          </span>
        </div>
      `).join('');
    }

    const modal = document.getElementById('notifySubstitutionModal');
    if (modal) modal.style.display = 'flex';
  }

  function confirmDispatchSubstitutionNotifications() {
    SUBSTITUTION_PLANNER_DATA.forEach(s => {
      if (s.replacementTeacher !== 'Unassigned') {
        s.notified = true;
      }
    });

    closeModal('notifySubstitutionModal');
    renderSubstitutionPlanner();
    showToast('SMS & push notifications successfully dispatched to all covering and absent faculty!', 'success');
  }

  function confirmSingleSubstitutionSignoff(slotId) {
    const slot = SUBSTITUTION_PLANNER_DATA.find(s => s.id === slotId);
    if (!slot) return;

    if (slot.replacementTeacher === 'Unassigned') {
      showToast('Cannot sign off unassigned slot. Please assign a substitute first.', 'warning');
      return;
    }

    slot.status = 'Confirmed';
    slot.statusBadge = 'badge-success';
    renderSubstitutionPlanner();
    showToast('Substitution #' + slot.id + ' officially verified and signed-off by Vice Principal!', 'success');
  }

  // ACTION 5: PUBLISH SUBSTITUTION
  function openPublishSubstitutionModal() {
    const summary = document.getElementById('publishValidationSummary');
    const pendingSlots = SUBSTITUTION_PLANNER_DATA.filter(s => s.replacementTeacher === 'Unassigned');

    if (summary) {
      if (pendingSlots.length > 0) {
        summary.innerHTML = `
          <div class="alert alert-warning" style="margin-bottom:0.75rem; font-size:0.875rem;">
            <i class="fa-solid fa-triangle-exclamation"></i> <strong>Warning:</strong> You have <strong>${pendingSlots.length} unassigned slot(s)</strong> (${pendingSlots.map(p => p.class + ' ' + p.period).join(', ')}). All students must have assigned supervision before publishing.
          </div>
          <div style="font-size:0.8125rem; color:#64748b;">
            Click 'Find Available Teacher' to complete allocations before finalizing the official publication.
          </div>
        `;
      } else {
        summary.innerHTML = `
          <div class="alert alert-success" style="margin-bottom:0.75rem; font-size:0.875rem;">
            <i class="fa-solid fa-circle-check"></i> <strong>Validation Cleared (0 Gaps):</strong> All 6 affected class periods have verified replacement teachers with 0 timetable collisions.
          </div>
          <div style="font-size:0.8125rem; color:#64748b;">
            Ready to publish official roster to the Staff Room digital board and issue daily print register.
          </div>
        `;
      }
    }

    const modal = document.getElementById('publishSubstitutionModal');
    if (modal) modal.style.display = 'flex';
  }

  function confirmPublishSubstitution() {
    SUBSTITUTION_PLANNER_DATA.forEach(s => {
      if (s.replacementTeacher !== 'Unassigned') {
        s.status = 'Published';
        s.statusBadge = 'badge-info';
        s.published = true;
      }
    });

    closeModal('publishSubstitutionModal');
    renderSubstitutionPlanner();
    showToast('Official daily substitution roster published to Staff Room display & Digital Notice Board!', 'success');
  }

