    html += '        <th>Day</th>';
    html += '        <th>Period 1</th><th>Period 2</th><th>Period 3</th><th>Period 4</th>';
    html += '        <th>Period 5</th><th>Period 6</th><th>Period 7</th><th>Period 8</th>';
