  function submitAnnouncementForApproval(id) {
    const ann = commAnnouncementsData.find(a => a.id === id);
    if (ann) {
      ann.status = 'Pending Approval';
      showToast('Announcement ' + id + ' submitted to Principal Smt. Gorle Varalakshmi for review.', 'info');
      renderAnnouncements();
    }
  }

  function approveAnnouncement(id) {
    const ann = commAnnouncementsData.find(a => a.id === id);
    if (ann) {
      ann.status = 'Approved';
      showToast('Announcement ' + id + ' approved by Executive Leadership.', 'success');
      renderAnnouncements();
    }
  }

  function publishAnnouncement(id) {
    const ann = commAnnouncementsData.find(a => a.id === id);
    if (ann) {
      ann.status = 'Published';
      ann.publishDate = '01 Nov 2026, 04:30 PM';
      showToast('Announcement ' + id + ' is now LIVE on Parent & Student Portals.', 'success');
      renderAnnouncements();
    }
  }

  function openRetractAnnouncementModal(id) {
    const ann = commAnnouncementsData.find(a => a.id === id);
    if (!ann) return;

    document.getElementById('retractAnnouncementId').value = id;
    document.getElementById('retractAnnouncementTitleDisplay').textContent = ann.title + ' (' + ann.id + ')';
    document.getElementById('retractReason').value = '';
    openModal('retractAnnouncementModal');
  }

  function handleRetractAnnouncementSubmit(e) {
    if (e) e.preventDefault();

    const id = document.getElementById('retractAnnouncementId').value;
    const reason = document.getElementById('retractReason').value;

    const ann = commAnnouncementsData.find(a => a.id === id);
    if (ann) {
      ann.status = 'Retracted';
      ann.retractReason = reason;
      showToast('Announcement ' + id + ' has been retracted and archived.', 'warning');
      closeModal('retractAnnouncementModal');
      renderAnnouncements();
    }
  }

