  function renderOfficialCirculars(list) {
    const tbody = document.getElementById('officialCircularsTableBody');
    if (!tbody) return;

    const data = list || commCircularsData;
    updateCircularsKPIs();

    if (data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" class="text-center text-muted p-4">No official circulars matching criteria.</td></tr>';
      return;
    }

    tbody.innerHTML = data.map(function(cir) {
      let statusBadge = '<span class="portal-badge badge-success"><i class="fa-solid fa-circle-check mr-1"></i>Published</span>';
      if (cir.status === 'Awaiting Signatures') {
        statusBadge = '<span class="portal-badge badge-warning"><i class="fa-solid fa-signature mr-1"></i>Awaiting Signatures</span>';
      } else if (cir.status === 'Draft') {
        statusBadge = '<span class="portal-badge badge-secondary">Draft</span>';
      } else if (cir.status === 'Archived') {
        statusBadge = '<span class="portal-badge badge-danger">Archived</span>';
      }

      const ackPercent = Math.round((cir.acknowledgedCount / cir.totalCount) * 100);
      const ackHtml = 
        '<div>' +
          '<div style="display:flex; justify-content:space-between; font-size:0.75rem; font-weight:700; margin-bottom:2px;">' +
            '<span style="color:#059669;">' + cir.acknowledgedCount + ' / ' + cir.totalCount + ' Signed</span>' +
            '<span>' + ackPercent + '%</span>' +
          '</div>' +
          '<div style="height:5px; background:#e2e8f0; border-radius:3px; overflow:hidden;">' +
            '<div style="width:' + ackPercent + '%; height:100%; background:#10b981;"></div>' +
          '</div>' +
          '<div style="font-size:0.72rem; color:#64748b; margin-top:2px;">' + cir.ackRequirement + '</div>' +
        '</div>';

      return '<tr>' +
        '<td><strong style="color:#1e3a8a; font-family:monospace; font-size:0.83rem;">' + cir.circularNo + '</strong></td>' +
        '<td>' +
          '<div style="font-weight:700; color:#0f172a; line-height:1.25;">' + cir.title + '</div>' +
          '<div style="margin-top:3px;">' +
            '<span class="text-primary" style="font-size:0.78rem; font-weight:600; cursor:pointer;" onclick="portalApp.downloadCircularDoc(\'' + cir.circularNo + '\')">' +
              '<i class="fa-solid fa-file-pdf mr-1 text-danger"></i>' + cir.document +
            '</span>' +
          '</div>' +
        '</td>' +
        '<td><span style="font-size:0.82rem; font-weight:600; color:#334155;">' + cir.issueDate + '</span></td>' +
        '<td><span class="portal-badge badge-primary" style="font-size:0.75rem;">' + cir.audience + '</span></td>' +
        '<td><div style="font-size:0.8rem; font-weight:600; color:#0f172a;"><i class="fa-solid fa-stamp mr-1 text-primary"></i>' + cir.approver + '</div></td>' +
        '<td>' + ackHtml + '</td>' +
        '<td style="text-align:center;">' + statusBadge + '</td>' +
        '<td style="text-align:center;">' +
          '<div style="display:flex; justify-content:center; gap:5px;">' +
            '<button type="button" class="btn btn-outline-secondary btn-sm" onclick="portalApp.openPreviewCircularModal(\'' + cir.circularNo + '\')" title="Preview Official Document"><i class="fa-solid fa-eye"></i></button>' +
            '<button type="button" class="btn btn-outline-primary btn-sm" onclick="portalApp.openTrackCircularAckModal(\'' + cir.circularNo + '\')" title="Track Acknowledgements"><i class="fa-solid fa-signature"></i></button>' +
            '<button type="button" class="btn btn-outline-success btn-sm" onclick="portalApp.downloadCircularDoc(\'' + cir.circularNo + '\')" title="Download Circular PDF"><i class="fa-solid fa-download"></i></button>' +
          '</div>' +
        '</td>' +
      '</tr>';
    }).join('');
  }

  function updateCircularsKPIs() {
    const total = commCircularsData.length;
    let sumAck = 0;
    let sumTot = 0;
    commCircularsData.forEach(c => {
      sumAck += c.acknowledgedCount;
      sumTot += c.totalCount;
    });
    const avgAck = sumTot > 0 ? ((sumAck / sumTot) * 100).toFixed(1) : '96.8';

    const elTot = document.getElementById('commStatCirTotal');
    const elRate = document.getElementById('commStatCirAckRate');
    const elBdg = document.getElementById('commCirCountBadge');

    if (elTot) elTot.textContent = total + ' Issued';
    if (elRate) elRate.textContent = avgAck + '%';
    if (elBdg) elBdg.textContent = total;
  }

  function filterOfficialCirculars() {
    const q = (document.getElementById('circularsSearchInput')?.value || '').toLowerCase().trim();
    const aud = document.getElementById('circularsAudienceFilter')?.value || 'all';
    const stat = document.getElementById('circularsStatusFilter')?.value || 'all';

    const filtered = commCircularsData.filter(function(cir) {
      const matchQ = !q ||
        cir.circularNo.toLowerCase().includes(q) ||
        cir.title.toLowerCase().includes(q) ||
        cir.summary.toLowerCase().includes(q);

      const matchAud = (aud === 'all') || (cir.audience === aud);
      const matchStat = (stat === 'all') || (cir.status === stat);

      return matchQ && matchAud && matchStat;
    });

    renderOfficialCirculars(filtered);
  }

