  function downloadCircularDoc(circularNo) {
    const cir = commCircularsData.find(c => c.circularNo === circularNo);
    const docName = cir ? cir.document : 'Circular.pdf';
    showToast('Downloading official signed PDF: ' + docName, 'info');
    setTimeout(() => {
      window.print();
    }, 400);
  }

  function openTrackCircularAckModal(circularNo) {
    const cir = commCircularsData.find(c => c.circularNo === circularNo);
    if (!cir) return;

    const subEl = document.getElementById('trackCirSub');
    if (subEl) subEl.textContent = cir.circularNo + ' • ' + cir.title;

    const countEl = document.getElementById('trackAckCount');
    const pctEl = document.getElementById('trackAckPct');
    const pendEl = document.getElementById('trackPendingCount');

    if (countEl) countEl.textContent = cir.acknowledgedCount + ' / ' + cir.totalCount;
    if (pctEl) pctEl.textContent = Math.round((cir.acknowledgedCount / cir.totalCount) * 100) + '%';
    if (pendEl) pendEl.textContent = (cir.totalCount - cir.acknowledgedCount) + ' Parents';

    const tbody = document.getElementById('trackCircularAckTableBody');
    if (tbody) {
      tbody.innerHTML = cir.ackRoster.map(function(r) {
        const isSigned = r.status === 'Acknowledged';
        const badge = isSigned
          ? '<span class="portal-badge badge-success"><i class="fa-solid fa-circle-check mr-1"></i>Signed</span>'
          : '<span class="portal-badge badge-warning"><i class="fa-solid fa-clock mr-1"></i>Pending</span>';

        return '<tr>' +
          '<td><strong>' + r.admNo + '</strong></td>' +
          '<td>' + r.name + ' (' + r.grade + ')</td>' +
          '<td>' + r.parent + '</td>' +
          '<td>' + r.phone + '</td>' +
          '<td>' + badge + '</td>' +
          '<td>' + r.timestamp + '</td>' +
        '</tr>';
      }).join('');
    }

    openModal('trackCircularAckModal');
  }

