  function renderSmsBroadcast(list) {
    const tbody = document.getElementById('smsBroadcastTableBody');
    if (!tbody) return;

    const data = list || commSmsData;

    if (data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" class="text-center text-muted p-4">No SMS campaigns found.</td></tr>';
      return;
    }

    tbody.innerHTML = data.map(function(sms) {
      let statusBadge = '<span class="portal-badge badge-success"><i class="fa-solid fa-circle-check mr-1"></i>' + sms.status + '</span>';
      if (sms.status === 'Partial Failures') {
        statusBadge = '<span class="portal-badge badge-warning"><i class="fa-solid fa-triangle-exclamation mr-1"></i>Partial Failures</span>';
      } else if (sms.status === 'Scheduled') {
        statusBadge = '<span class="portal-badge badge-info"><i class="fa-solid fa-clock mr-1"></i>Scheduled</span>';
      }

      const summaryHtml = 
        '<div style="font-size:0.78rem;">' +
          '<span style="color:#059669; font-weight:700;">' + sms.delivered + ' Delivered</span> • ' +
          '<span style="color:#dc2626; font-weight:700;">' + sms.failed + ' Failed</span>' +
        '</div>';

      return '<tr>' +
        '<td>' +
          '<div style="font-weight:700; color:#0f172a;">' + sms.campaignName + '</div>' +
          '<div style="font-size:0.75rem; color:#64748b; font-family:monospace;">' + sms.campaignId + '</div>' +
        '</td>' +
        '<td>' +
          '<div style="font-size:0.75rem; color:#1d4ed8; font-weight:700;">' + sms.dltTemplateId + ' • ' + sms.templateName + '</div>' +
          '<div style="font-size:0.8rem; color:#475569; max-width:280px; display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; overflow:hidden;">' + sms.messageText + '</div>' +
        '</td>' +
        '<td><span class="portal-badge badge-primary">' + sms.recipientGroup + '</span></td>' +
        '<td style="text-align:center; font-weight:700;">' + sms.recipientCount + '</td>' +
        '<td><span style="font-size:0.8rem; color:#334155;">' + sms.schedule + '</span></td>' +
        '<td>' +
          summaryHtml +
          '<div style="margin-top:2px;">' + statusBadge + '</div>' +
        '</td>' +
        '<td style="text-align:center;">' +
          '<div style="display:flex; justify-content:center; gap:5px;">' +
            '<button type="button" class="btn btn-outline-secondary btn-sm" onclick="portalApp.showToast(\'Campaign ' + sms.campaignId + ': ' + sms.messageText + '\', \'info\')" title="Preview SMS"><i class="fa-solid fa-eye"></i></button>' +
            (sms.failed > 0 ? '<button type="button" class="btn btn-outline-warning btn-sm" onclick="portalApp.retrySmsCampaign(\'' + sms.campaignId + '\')" title="Retry Failed Numbers"><i class="fa-solid fa-rotate-right"></i></button>' : '') +
            '<button type="button" class="btn btn-outline-primary btn-sm" onclick="portalApp.openValidateRecipientsModal()" title="Validate Recipients"><i class="fa-solid fa-user-check"></i></button>' +
          '</div>' +
        '</td>' +
      '</tr>';
    }).join('');
  }

  function filterSmsBroadcast() {
    const q = (document.getElementById('smsSearchInput')?.value || '').toLowerCase().trim();
    const grp = document.getElementById('smsRecipientFilter')?.value || 'all';
    const stat = document.getElementById('smsStatusFilter')?.value || 'all';

    const filtered = commSmsData.filter(function(s) {
      const matchQ = !q ||
        s.campaignName.toLowerCase().includes(q) ||
        s.messageText.toLowerCase().includes(q) ||
        s.dltTemplateId.toLowerCase().includes(q);

      const matchGrp = (grp === 'all') || (s.recipientGroup === grp);
      const matchStat = (stat === 'all') || (s.status.includes(stat));

      return matchQ && matchGrp && matchStat;
    });

    renderSmsBroadcast(filtered);
  }

