  function updateSmsRecipientCount(group) {
    const countBox = document.getElementById('smsCalculatedCount');
    let cnt = '500 Parents';
    if (group === 'Absent Today') cnt = '19 Parents';
    if (group === 'Fee Due Batch A') cnt = '42 Parents';
    if (group === 'Class X Parents') cnt = '45 Parents';
    if (group === 'Transport Route 3') cnt = '28 Parents';
    if (countBox) countBox.value = cnt;
  }

  function handleSmsCampaignSubmit(e) {
    if (e) e.preventDefault();

    const name = document.getElementById('smsCampaignName').value;
    const tplId = document.getElementById('commSmsTemplateSelect') ? document.getElementById('commSmsTemplateSelect').value : 'TPL-DLT-001';
    const group = document.getElementById('smsRecipientGroup').value;
    const msg = document.getElementById('smsMessageText').value;

    let cnt = 19;
    if (group === 'Fee Due Batch A') cnt = 42;
    if (group === 'Class X Parents') cnt = 45;
    if (group === 'Transport Route 3') cnt = 28;
    if (group === 'All Parents') cnt = 500;

    const newCampaign = {
      campaignId: 'SMS-2026-0' + (commSmsData.length + 43),
      campaignName: name,
      dltTemplateId: tplId,
      templateName: 'Custom DLT Alert',
      messageText: msg,
      recipientGroup: group,
      recipientCount: cnt,
      schedule: 'Immediate (Dispatched ' + new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) + ')',
      delivered: cnt,
      failed: 0,
      status: 'Delivered'
    };

    commSmsData.unshift(newCampaign);
    showToast('SMS Campaign ' + newCampaign.campaignId + ' queued for dispatch (' + cnt + ' messages).', 'success');
    closeModal('composeSmsModal');
    renderSmsBroadcast();
  }

