  // =========================================================================

  function renderEmailDispatch(list) {
    const tbody = document.getElementById('emailDispatchTableBody');
    if (!tbody) return;

    const data = list || commEmailData;

    if (data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" class="text-center text-muted p-4">No email campaigns found.</td></tr>';
      return;
    }

    tbody.innerHTML = data.map(function(eml) {
      let statusBadge = '<span class="portal-badge badge-success"><i class="fa-solid fa-circle-check mr-1"></i>Delivered</span>';
      if (eml.status === 'Scheduled') {
        statusBadge = '<span class="portal-badge badge-info"><i class="fa-solid fa-clock mr-1"></i>Scheduled</span>';
      } else if (eml.status === 'Draft') {
        statusBadge = '<span class="portal-badge badge-secondary">Draft</span>';
      }

      const attachHtml = eml.attachments
        ? '<span class="text-primary" style="font-size:0.78rem; font-weight:600;"><i class="fa-solid fa-paperclip mr-1"></i>' + eml.attachments + '</span>'
        : '<span class="text-muted" style="font-size:0.78rem;">None</span>';

      return '<tr>' +
        '<td>' +
          '<div style="font-weight:700; color:#0f172a;">' + eml.campaignName + '</div>' +
          '<div style="font-size:0.75rem; color:#64748b; font-family:monospace;">' + eml.campaignId + '</div>' +
        '</td>' +
        '<td>' +
          '<div style="font-weight:600; color:#1e293b; font-size:0.83rem;">' + eml.subject + '</div>' +
          '<div style="font-size:0.78rem; color:#64748b; max-width:240px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">' + eml.messageSnippet + '</div>' +
        '</td>' +
        '<td><span class="portal-badge badge-primary" style="font-size:0.75rem;">' + eml.recipientGroup + ' (' + eml.recipientCount + ')</span></td>' +
        '<td>' + attachHtml + '</td>' +
        '<td><span style="font-size:0.8rem; font-family:monospace; color:#334155;">' + eml.sender + '</span></td>' +
        '<td><span style="font-size:0.78rem; color:#64748b;">' + eml.schedule + '</span></td>' +
        '<td style="text-align:center;">' + statusBadge + '</td>' +
        '<td style="text-align:center;">' +
          '<div style="display:flex; justify-content:center; gap:5px;">' +
            '<button type="button" class="btn btn-outline-secondary btn-sm" onclick="portalApp.showToast(\'Subject: ' + eml.subject + '\', \'info\')" title="Preview Email"><i class="fa-solid fa-eye"></i></button>' +
            (eml.status === 'Scheduled' ? '<button type="button" class="btn btn-outline-danger btn-sm" onclick="portalApp.cancelScheduledEmail(\'' + eml.campaignId + '\')" title="Cancel Schedule"><i class="fa-solid fa-ban"></i></button>' : '') +
            '<button type="button" class="btn btn-outline-primary btn-sm" onclick="portalApp.openTestSendEmailModal()" title="Send Test"><i class="fa-solid fa-flask"></i></button>' +
          '</div>' +
        '</td>' +
      '</tr>';
    }).join('');
  }

  function filterEmailDispatch() {
    const q = (document.getElementById('emailSearchInput')?.value || '').toLowerCase().trim();
    const stat = document.getElementById('emailStatusFilter')?.value || 'all';

    const filtered = commEmailData.filter(function(e) {
      const matchQ = !q ||
        e.campaignName.toLowerCase().includes(q) ||
        e.subject.toLowerCase().includes(q) ||
        e.recipientGroup.toLowerCase().includes(q);

      const matchStat = (stat === 'all') || (e.status === stat);

      return matchQ && matchStat;
    });

    renderEmailDispatch(filtered);
  }

  function openComposeEmailModal() {
    openModal('composeEmailModal');
  }

  function handleEmailDispatchSubmit(e) {
    if (e) e.preventDefault();

    const name = document.getElementById('emailCampaignName').value;
    const subject = document.getElementById('emailSubject').value;
    const group = document.getElementById('emailRecipientGroup').value;
    const sender = document.getElementById('emailSender').value;
    const attach = document.getElementById('emailAttachments').value || null;
    const schedule = document.getElementById('emailSchedule').value;
    const msg = document.getElementById('emailBody').value;

    const newEml = {
      campaignId: 'EML-2026-0' + (commEmailData.length + 21),
      campaignName: name,
      subject: subject,
      messageSnippet: msg.substring(0, 80) + '...',
      recipientGroup: group,
      recipientCount: 500,
      attachments: attach,
      sender: sender,
      schedule: schedule === 'Immediate' ? 'Immediate (Sent ' + new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}) + ')' : 'Scheduled for Tomorrow',
      status: schedule === 'Immediate' ? 'Delivered' : 'Scheduled',
      opened: 0,
      bounced: 0
    };

    commEmailData.unshift(newEml);
    showToast('Email campaign ' + newEml.campaignId + ' queued (' + newEml.status + ').', 'success');
    closeModal('composeEmailModal');
    renderEmailDispatch();
  }

  function openTestSendEmailModal() {
    openModal('testSendEmailModal');
  }

  function handleTestSendEmailSubmit(e) {
    if (e) e.preventDefault();
    const email = document.getElementById('testEmailAddress').value;
    showToast('Instant test dispatch transmitted to ' + email + '.', 'success');
    closeModal('testSendEmailModal');
  }

  function cancelScheduledEmail(campaignId) {
    const eml = commEmailData.find(e => e.campaignId === campaignId);
    if (eml) {
      eml.status = 'Draft';
      eml.schedule = 'Cancelled by user';
      showToast('Scheduled email campaign ' + campaignId + ' has been cancelled.', 'warning');
      renderEmailDispatch();
    }
  }

  function exportEmailDispatchCSV() {
    let csv = 'Campaign ID,Campaign Name,Subject,Recipient Group,Count,Sender,Schedule,Status\n';
    commEmailData.forEach(function(e) {
      csv += '"' + e.campaignId + '","' + e.campaignName + '","' + e.subject + '","' + e.recipientGroup + '","' + e.recipientCount + '","' + e.sender + '","' + e.schedule + '","' + e.status + '"\n';
    });
    downloadCsvFile(csv, 'SriVidya_Email_Dispatch_Report.csv');
    showToast('Email dispatch report exported to CSV.', 'success');
  }

