  // =========================================================================
  // 12.6 PARENT ENQUIRIES AND MESSAGES CONTROLLER & ACTIONS
  // =========================================================================

  function renderParentEnquiries(list) {
    const tbody = document.getElementById('parentEnquiriesTableBody');
    if (!tbody) return;

    const data = list || commEnquiriesData;
    updateEnquiriesKPIs();

    if (data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" class="text-center text-muted p-4">No parent enquiries found.</td></tr>';
      return;
    }

    tbody.innerHTML = data.map(function(enq) {
      let statusBadge = '<span class="portal-badge badge-warning">' + enq.status + '</span>';
      if (enq.status === 'Resolved' || enq.status === 'Closed') {
        statusBadge = '<span class="portal-badge badge-success"><i class="fa-solid fa-check mr-1"></i>' + enq.status + '</span>';
      } else if (enq.status === 'Escalated') {
        statusBadge = '<span class="portal-badge badge-danger"><i class="fa-solid fa-triangle-exclamation mr-1"></i>Escalated</span>';
      } else if (enq.status === 'In Review') {
        statusBadge = '<span class="portal-badge badge-info"><i class="fa-solid fa-spinner fa-spin mr-1"></i>In Review</span>';
      } else if (enq.status === 'Reopened') {
        statusBadge = '<span class="portal-badge badge-warning"><i class="fa-solid fa-rotate-left mr-1"></i>Reopened</span>';
      }

      let priorityBadge = '<span class="badge" style="background:#f1f5f9; color:#475569; font-size:0.75rem;">Normal</span>';
      if (enq.priority === 'High') priorityBadge = '<span class="badge" style="background:#fef3c7; color:#b45309; font-size:0.75rem; font-weight:700;">High</span>';
      if (enq.priority === 'Urgent') priorityBadge = '<span class="badge" style="background:#fee2e2; color:#b91c1c; font-size:0.75rem; font-weight:700;">Urgent</span>';

      return '<tr>' +
        '<td><strong style="color:#1e3a8a; font-family:monospace; font-size:0.83rem;">' + enq.enquiryId + '</strong></td>' +
        '<td>' +
          '<div style="font-weight:700; color:#0f172a;">' + enq.requester + '</div>' +
          '<div style="font-size:0.76rem; color:#64748b;">' + enq.phone + '</div>' +
        '</td>' +
        '<td>' +
          '<div style="font-weight:600; color:#1e293b; font-size:0.83rem;">' + enq.studentName + '</div>' +
          '<div style="font-size:0.75rem; color:#64748b;">' + enq.admNo + ' • ' + enq.grade + '</div>' +
        '</td>' +
        '<td><span class="portal-badge badge-primary" style="font-size:0.75rem;">' + enq.category + '</span></td>' +
        '<td><div style="font-size:0.8rem; font-weight:600; color:#0f172a;"><i class="fa-solid fa-user-tie mr-1 text-primary"></i>' + enq.assignedTo + '</div></td>' +
        '<td>' +
          '<div style="font-size:0.78rem; color:#334155;">' + enq.receivedDate + '</div>' +
          '<div style="margin-top:2px;">' + priorityBadge + '</div>' +
        '</td>' +
        '<td style="text-align:center;">' + statusBadge + '</td>' +
        '<td><span style="font-size:0.8rem; color:#64748b;">' + enq.resolutionDate + '</span></td>' +
        '<td style="text-align:center;">' +
          '<div style="display:flex; justify-content:center; gap:5px;">' +
            '<button type="button" class="btn btn-outline-primary btn-sm" onclick="portalApp.openReplyEnquiryModal(\'' + enq.enquiryId + '\')" title="Reply & Manage Enquiry"><i class="fa-solid fa-reply"></i></button>' +
            (enq.status !== 'Escalated' && enq.status !== 'Resolved' ? '<button type="button" class="btn btn-outline-warning btn-sm" onclick="portalApp.openEscalateEnquiryModal(\'' + enq.enquiryId + '\')" title="Escalate to Leadership"><i class="fa-solid fa-arrow-up-right-dots"></i></button>' : '') +
            (enq.status === 'Resolved' || enq.status === 'Closed' ? '<button type="button" class="btn btn-outline-secondary btn-sm" onclick="portalApp.reopenParentEnquiry(\'' + enq.enquiryId + '\')" title="Reopen Case"><i class="fa-solid fa-rotate-left"></i></button>' : '') +
          '</div>' +
        '</td>' +
      '</tr>';
    }).join('');
  }

  function updateEnquiriesKPIs() {
    const total = commEnquiriesData.length;
    const resolved = commEnquiriesData.filter(e => e.status === 'Resolved' || e.status === 'Closed').length;
    const pending = commEnquiriesData.filter(e => e.status === 'Open' || e.status === 'In Review').length;
    const escalated = commEnquiriesData.filter(e => e.status === 'Escalated').length;

    const elTot = document.getElementById('commStatEnqTotal');
    const elRes = document.getElementById('commStatEnqResolved');
    const elPen = document.getElementById('commStatEnqPending');
    const elEsc = document.getElementById('commStatEnqAvgTime');
    const elBdg = document.getElementById('commEnqCountBadge');

    if (elTot) elTot.textContent = total + ' Received';
    if (elRes) elRes.textContent = ((resolved / total) * 100).toFixed(1) + '% (' + resolved + ' Closed)';
    if (elPen) elPen.textContent = pending + ' Open';
    if (elEsc) elEsc.textContent = escalated + ' Case';
    if (elBdg) elBdg.textContent = total;
  }

  function filterParentEnquiries() {
    const q = (document.getElementById('enquirySearchInput')?.value || '').toLowerCase().trim();
    const cat = document.getElementById('enquiryCategoryFilter')?.value || 'all';
    const pri = document.getElementById('enquiryPriorityFilter')?.value || 'all';
    const stat = document.getElementById('enquiryStatusFilter')?.value || 'all';

    const filtered = commEnquiriesData.filter(function(enq) {
      const matchQ = !q ||
        enq.enquiryId.toLowerCase().includes(q) ||
        enq.requester.toLowerCase().includes(q) ||
        enq.studentName.toLowerCase().includes(q) ||
        enq.enquiryText.toLowerCase().includes(q);

      const matchCat = (cat === 'all') || (enq.category === cat);
      const matchPri = (pri === 'all') || (enq.priority === pri);
      const matchStat = (stat === 'all') || (enq.status === stat);

      return matchQ && matchCat && matchPri && matchStat;
    });

    renderParentEnquiries(filtered);
  }

  function openNewEnquiryModal() {
    // Uses addEnquiryModal if present
    const modal = document.getElementById('addEnquiryModal');
    if (modal) {
      openModal('addEnquiryModal');
    } else {
      const parentName = prompt('Enter Parent/Guardian Name:', 'Sri K. Venkat');
      if (!parentName) return;
      const phone = prompt('Enter Contact Phone Number:', '+91 98480 77889');
      const student = prompt('Enter Student Name & Class:', 'K. Sai (Class X-A)');
      const issue = prompt('Enter Inquiry / Grievance Subject:', 'Fee due concession review');

      const newId = 'ENQ-2026-0' + (commEnquiriesData.length + 94);
      commEnquiriesData.unshift({
        enquiryId: newId,
        requester: parentName,
        phone: phone || '+91 98480 00000',
        studentName: student || 'Enrolled Student',
        admNo: 'SV-NEW',
        grade: 'Class X',
        category: 'General',
        assignedTo: 'Sri Navva Anand (Vice Principal)',
        receivedDate: '01 Nov 2026, 04:30 PM',
        priority: 'Normal',
        status: 'Open',
        resolutionDate: '-',
        enquiryText: issue || 'General enquiry',
        staffReply: '',
        internalNotes: 'Logged at Reception Counter'
      });
      showToast('Enquiry ' + newId + ' registered successfully.', 'success');
      renderParentEnquiries();
    }
  }

  function openReplyEnquiryModal(enquiryId) {
    const enq = commEnquiriesData.find(e => e.enquiryId === enquiryId);
    if (!enq) return;

    document.getElementById('replyEnquiryId').value = enquiryId;
    document.getElementById('replyEnquiryRefDisplay').textContent = enq.enquiryId + ' • Received: ' + enq.receivedDate;
    document.getElementById('replyRequesterName').textContent = enq.requester;
    document.getElementById('replyRequesterPhone').textContent = enq.phone;
    document.getElementById('replyStudentInfo').textContent = 'Student: ' + enq.studentName + ' (' + enq.admNo + ' • ' + enq.grade + ') • Category: ' + enq.category;
    document.getElementById('replyEnquiryText').textContent = '"' + enq.enquiryText + '"';
    document.getElementById('replyPriorityBadge').textContent = enq.priority;
    document.getElementById('replyAssignee').value = enq.assignedTo;
    document.getElementById('replyMessageText').value = enq.staffReply || '';
    document.getElementById('replyInternalNote').value = enq.internalNotes || '';
    document.getElementById('replyMarkResolved').checked = (enq.status === 'Resolved');

    openModal('replyParentEnquiryModal');
  }

  function handleReplyEnquirySubmit(e) {
    if (e) e.preventDefault();

    const id = document.getElementById('replyEnquiryId').value;
    const channel = document.getElementById('replyChannel').value;
    const assignee = document.getElementById('replyAssignee').value;
    const replyText = document.getElementById('replyMessageText').value;
    const note = document.getElementById('replyInternalNote').value;
    const markResolved = document.getElementById('replyMarkResolved').checked;

    const enq = commEnquiriesData.find(e => e.enquiryId === id);
    if (enq) {
      enq.assignedTo = assignee;
      enq.staffReply = replyText;
      enq.internalNotes = note;
      if (markResolved) {
        enq.status = 'Resolved';
        enq.resolutionDate = '01 Nov 2026';
      } else {
        enq.status = 'In Review';
      }
      showToast('Response transmitted via ' + channel + ' and docket updated.', 'success');
      closeModal('replyParentEnquiryModal');
      renderParentEnquiries();
    }
  }

  function openEscalateEnquiryModal(enquiryId) {
    const enq = commEnquiriesData.find(e => e.enquiryId === enquiryId);
    if (!enq) return;

    document.getElementById('escalateEnquiryId').value = enquiryId;
    document.getElementById('escalateEnquiryRefDisplay').textContent = enq.enquiryId + ' (' + enq.requester + ' • ' + enq.studentName + ')';
    document.getElementById('escalateNotes').value = '';
    openModal('escalateEnquiryModal');
  }

  function openEscalateEnquiryModalFromReply() {
    const id = document.getElementById('replyEnquiryId').value;
    closeModal('replyParentEnquiryModal');
    openEscalateEnquiryModal(id);
  }

  function handleEscalateEnquirySubmit(e) {
    if (e) e.preventDefault();

    const id = document.getElementById('escalateEnquiryId').value;
    const toOfficial = document.getElementById('escalateToOfficial').value;
    const pri = document.getElementById('escalatePriority').value;
    const notes = document.getElementById('escalateNotes').value;

    const enq = commEnquiriesData.find(e => e.enquiryId === id);
    if (enq) {
      enq.assignedTo = toOfficial;
      enq.priority = pri;
      enq.status = 'Escalated';
      enq.internalNotes = (enq.internalNotes ? enq.internalNotes + ' | ' : '') + 'Escalated: ' + notes;
      showToast('Enquiry ' + id + ' escalated to ' + toOfficial + '.', 'warning');
      closeModal('escalateEnquiryModal');
      renderParentEnquiries();
    }
  }

  function reopenParentEnquiry(enquiryId) {
    const enq = commEnquiriesData.find(e => e.enquiryId === enquiryId);
    if (enq) {
      enq.status = 'Reopened';
      enq.resolutionDate = '-';
      showToast('Enquiry ' + enquiryId + ' reopened for active staff follow-up.', 'info');
      renderParentEnquiries();
    }
  }

  function exportParentEnquiriesCSV() {
    let csv = 'Enquiry ID,Requester,Phone,Student,Adm No,Grade,Category,Assigned To,Received Date,Priority,Status,Resolution Date\n';
    commEnquiriesData.forEach(function(e) {
      csv += '"' + e.enquiryId + '","' + e.requester + '","' + e.phone + '","' + e.studentName + '","' + e.admNo + '","' + e.grade + '","' + e.category + '","' + e.assignedTo + '","' + e.receivedDate + '","' + e.priority + '","' + e.status + '","' + e.resolutionDate + '"\n';
    });
    downloadCsvFile(csv, 'SriVidya_Parent_Enquiries_Register.csv');
    showToast('Parent enquiries register exported to CSV.', 'success');
  }

