  // 7.3 ROOM SEATING PLAN ENGINE
  function switchSeatingSubView(view) {
    activeSeatingSubView = view;
    const matrixContainer = document.getElementById('seatingHallDesksContainer');
    const rosterContainer = document.getElementById('seatingHallRosterContainer');
    const btnMatrix = document.getElementById('btnSeatingViewMatrix');
    const btnRoster = document.getElementById('btnSeatingViewRoster');

    if (matrixContainer && rosterContainer) {
      if (view === 'roster') {
        matrixContainer.style.display = 'none';
        rosterContainer.style.display = 'block';
        if (btnMatrix) btnMatrix.className = 'btn btn-sm btn-secondary';
        if (btnRoster) btnRoster.className = 'btn btn-sm btn-primary';
        const hallKey = document.getElementById('examHallSelector')?.value || 'Hall 1';
        renderAllocatedStudentsTable(hallKey);
      } else {
        matrixContainer.style.display = 'block';
        rosterContainer.style.display = 'none';
        if (btnMatrix) btnMatrix.className = 'btn btn-sm btn-primary';
        if (btnRoster) btnRoster.className = 'btn btn-sm btn-secondary';
      }
    }
  }

  function renderAllocatedStudentsTable(hallKey) {
    const tbody = document.getElementById('seatingRosterTableBody');
    if (!tbody) return;

    const hall = (typeof EXAM_HALLS_DATA !== 'undefined' && EXAM_HALLS_DATA[hallKey]) || {
      name: 'Hall 1: Rooms 101-102',
      capacityTotal: 78,
      desksCount: 39,
      primaryClass: 'Class X-A',
      secondaryClass: 'Class IX-A'
    };

    const primStudents = (state.students && state.students.filter(s => s.class === hall.primaryClass)) || [];
    const secStudents = (state.students && state.students.filter(s => s.class === hall.secondaryClass)) || [];

    let rowsHtml = '';
    for (let i = 1; i <= hall.desksCount; i++) {
      const deskNum = String(i).padStart(2, '0');
      const candA = primStudents[i - 1] || { admNo: 'SV-0' + (200 + i), rollNo: '#10' + deskNum, name: 'Candidate ' + i + 'A', class: hall.primaryClass };
      const candB = secStudents[i - 1] || { admNo: 'SV-0' + (400 + i), rollNo: '#9' + deskNum, name: 'Candidate ' + i + 'B', class: hall.secondaryClass };

      rowsHtml += `
        <tr>
          <td style="text-align: center;">
            <strong style="color: #1e40af; font-family: monospace; font-size: 0.88rem;">Desk #${deskNum}-A</strong>
          </td>
          <td>
            <div style="display:flex; align-items:center; gap:6px;">
              <span class="portal-badge badge-neutral" style="font-family:monospace; font-size:0.75rem;">${candA.admNo || 'SV-02' + deskNum}</span>
              <strong style="color:#2563eb; font-size:0.8rem;">${candA.rollNo || '#' + deskNum}</strong>
            </div>
          </td>
          <td>
            <div style="font-weight:700; color:#0f172a;">${candA.name}</div>
          </td>
          <td>
            <span class="portal-badge badge-primary">${candA.class || hall.primaryClass}</span>
          </td>
          <td>${hall.name || hallKey}</td>
          <td style="text-align: center;"><span class="text-muted">${hall.capacityTotal} Candidates</span></td>
          <td style="text-align: center;">
            <span class="portal-badge badge-success"><i class="fa-solid fa-circle-check"></i> Clean</span>
          </td>
        </tr>
        <tr>
          <td style="text-align: center;">
            <strong style="color: #059669; font-family: monospace; font-size: 0.88rem;">Desk #${deskNum}-B</strong>
          </td>
          <td>
            <div style="display:flex; align-items:center; gap:6px;">
              <span class="portal-badge badge-neutral" style="font-family:monospace; font-size:0.75rem;">${candB.admNo || 'SV-04' + deskNum}</span>
              <strong style="color:#059669; font-size:0.8rem;">${candB.rollNo || '#' + deskNum}</strong>
            </div>
          </td>
          <td>
            <div style="font-weight:700; color:#0f172a;">${candB.name}</div>
          </td>
          <td>
            <span class="portal-badge badge-success">${candB.class || hall.secondaryClass}</span>
          </td>
          <td>${hall.name || hallKey}</td>
          <td style="text-align: center;"><span class="text-muted">${hall.capacityTotal} Candidates</span></td>
          <td style="text-align: center;">
            <span class="portal-badge badge-success"><i class="fa-solid fa-circle-check"></i> Clean</span>
          </td>
        </tr>
      `;
    }

    tbody.innerHTML = rowsHtml;
  }

