  function handleGenerateSeatingPlanSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const hallKey = document.getElementById('genSeatingHallSelect')?.value || 'Hall 1';
    const clsA = document.getElementById('genSeatingClassA')?.value || 'Class X-A';
    const clsB = document.getElementById('genSeatingClassB')?.value || 'Class IX-A';
    const strategy = document.getElementById('genSeatingStrategy')?.value || 'Diagonal Alternate Class Seating';

    if (typeof EXAM_HALLS_DATA !== 'undefined' && EXAM_HALLS_DATA[hallKey]) {
      EXAM_HALLS_DATA[hallKey].primaryClass = clsA;
      EXAM_HALLS_DATA[hallKey].secondaryClass = clsB;
      EXAM_HALLS_DATA[hallKey].strategy = strategy;
    }

    closeModal('generateSeatingModal');
    renderRoomSeatingArrangement(hallKey);
    if (activeSeatingSubView === 'roster') {
      renderAllocatedStudentsTable(hallKey);
    }
    showToast(`Seating plan generated for ${hallKey} with ${clsA} & ${clsB} (${strategy})`, 'success');
  }

