  function computeGradeAndGp(score) {
    if (score >= 91) return { grade: 'A1', gp: '10.0', badgeClass: 'badge-success' };
    if (score >= 81) return { grade: 'A2', gp: '9.0', badgeClass: 'badge-success' };
    if (score >= 71) return { grade: 'B1', gp: '8.0', badgeClass: 'badge-primary' };
    if (score >= 61) return { grade: 'B2', gp: '7.0', badgeClass: 'badge-primary' };
    if (score >= 51) return { grade: 'C1', gp: '6.0', badgeClass: 'badge-warning' };
    if (score >= 41) return { grade: 'C2', gp: '5.0', badgeClass: 'badge-warning' };
    if (score >= 35) return { grade: 'D', gp: '4.0', badgeClass: 'badge-danger' };
    return { grade: 'F', gp: '0.0', badgeClass: 'badge-danger' };
  }

  function renderTabulationAndMarks() {
    const tbody = document.getElementById('tabulationMarksTableBody');
    if (!tbody) return;

    const classVal = document.getElementById('tabulationClassSelect')?.value || 'Class X-A';
    const subjVal = document.getElementById('tabulationSubjectSelect')?.value || 'Mathematics';
    const viewVal = document.getElementById('tabulationViewFilter')?.value || 'all';
    const searchVal = (document.getElementById('tabulationSearchInput')?.value || '').toLowerCase().trim();

    let filtered = TABULATION_RECORDS;
    if (viewVal === 'missing') {
      filtered = filtered.filter(m => m.missingEntry !== 'None (Entered)');
    } else if (viewVal === 'moderated') {
      filtered = filtered.filter(m => m.moderation > 0);
    }

    if (searchVal) {
      filtered = filtered.filter(m =>
        m.student.toLowerCase().includes(searchVal) ||
        m.admNo.toLowerCase().includes(searchVal) ||
        m.notes.toLowerCase().includes(searchVal)
      );
    }

    // Update KPI badges
    const totalCount = TABULATION_RECORDS.length;
    const enteredCount = TABULATION_RECORDS.filter(m => m.missingEntry === 'None (Entered)').length;
    const missingCount = TABULATION_RECORDS.filter(m => m.missingEntry !== 'None (Entered)').length;

    const totalEl = document.getElementById('tabulationTotalCount');
    const enteredEl = document.getElementById('tabulationEnteredCount');
    const missingEl = document.getElementById('tabulationMissingCount');
    const badgeEl = document.getElementById('tabulationBatchStatusBadge');

    if (totalEl) totalEl.textContent = `${totalCount} Students`;
    if (enteredEl) enteredEl.textContent = `${enteredCount} Entered`;
    if (missingEl) missingEl.textContent = `${missingCount} Flagged`;
    if (badgeEl) {
      badgeEl.innerHTML = `<i class="fa-solid fa-stamp"></i> ${currentMarksBatchSubmissionStatus}`;
      badgeEl.className = currentMarksBatchSubmissionStatus === 'Approved' ? 'portal-badge badge-success'
        : currentMarksBatchSubmissionStatus === 'Submitted for Review' ? 'portal-badge badge-primary'
        : currentMarksBatchSubmissionStatus === 'Changes Requested' ? 'portal-badge badge-danger'
        : currentMarksBatchSubmissionStatus === 'Locked' ? 'portal-badge badge-neutral'
        : 'portal-badge badge-warning';
    }

    tbody.innerHTML = filtered.map(m => {
      const gInfo = computeGradeAndGp(m.marksObtained);
      const isMissing = m.missingEntry !== 'None (Entered)';
      const isLocked = isTabulationMarksLocked || currentMarksBatchSubmissionStatus === 'Locked';

      return `
        <tr>
          <td>
            <div style="display:flex; align-items:center; gap:8px;">
              <div style="width:28px; height:28px; border-radius:50%; background:#e0e7ff; color:#3730a3; font-weight:700; font-size:0.75rem; display:flex; align-items:center; justify-content:center;">
                ${m.student.charAt(0)}
              </div>
              <strong style="color:#0f172a; font-size:0.86rem;">${m.student}</strong>
            </div>
          </td>
          <td>
            <span class="portal-badge badge-neutral" style="font-family:monospace; font-size:0.75rem;">${m.admNo}</span>
          </td>
          <td>
            <span class="portal-badge badge-primary">${m.class}</span>
          </td>
          <td>
            <span style="font-weight:600; color:#334155;">${m.subject}</span>
          </td>
          <td style="text-align: center;">
            <span style="font-weight:700; color:#64748b;">${m.maxMarks}</span>
          </td>
          <td style="text-align: center;">
            <input type="number" class="mark-input-inline ${m.marksObtained > m.maxMarks ? 'is-invalid' : ''}"
              min="0" max="${m.maxMarks}" value="${m.marksObtained}"
              onchange="portalApp.handleInlineMarkChange('${m.admNo}', this.value)"
              ${isLocked ? 'disabled' : ''}>
          </td>
          <td style="text-align: center;">
            <span class="portal-badge ${gInfo.badgeClass}" style="font-weight:800; font-size:0.75rem;">
              ${m.grade}
            </span>
          </td>
          <td style="text-align: center;">
            <span class="portal-badge ${isMissing ? 'badge-danger' : 'badge-success'}" style="font-size:0.75rem;">
              ${m.missingEntry}
            </span>
          </td>
          <td style="text-align: center;">
            <span class="portal-badge ${m.submissionStatus === 'Approved' ? 'badge-success' : m.submissionStatus === 'Changes Requested' ? 'badge-danger' : m.submissionStatus === 'Submitted for Review' ? 'badge-primary' : 'badge-neutral'}" style="font-size:0.75rem;">
              ${m.submissionStatus}
            </span>
          </td>
          <td style="text-align: center;">
            <button type="button" class="btn btn-sm btn-outline-primary" style="padding:2px 8px; font-size:0.75rem;" onclick="portalApp.openEnterMarksModal('${m.admNo}')" title="Edit Mark & Notes">
              <i class="fa-solid fa-pen"></i>
            </button>
          </td>
        </tr>
      `;
    }).join('');
  }

  function handleInlineMarkChange(admNo, valStr) {
    let val = parseFloat(valStr);
    if (isNaN(val)) val = 0;
    if (val > 100) {
      showToast('Validation Error: Score cannot exceed permitted maximum of 100 marks!', 'danger');
      val = 100;
    }
    if (val < 0) val = 0;

    const rec = TABULATION_RECORDS.find(r => r.admNo === admNo);
    if (rec) {
      rec.marksObtained = val;
      const gInfo = computeGradeAndGp(val);
      rec.grade = `${gInfo.grade} (${gInfo.gp})`;
      if (val > 0 && rec.missingEntry !== 'None (Entered)') {
        rec.missingEntry = 'None (Entered)';
      }
      renderTabulationAndMarks();
      showToast(`Updated score for ${rec.student} to ${val} (${rec.grade})`, 'info');
    }
  }

  function openEnterMarksModal(admNo) {
    const rec = TABULATION_RECORDS.find(r => r.admNo === admNo) || TABULATION_RECORDS[0];
    const selectEl = document.getElementById('entryStudentSelect');
    if (selectEl && rec) {
      selectEl.value = rec.admNo;
      onEnterMarksStudentChange(rec.admNo);
    }
    openModal('enterMarksModal');
  }

  function onEnterMarksStudentChange(admNo) {
    const rec = TABULATION_RECORDS.find(r => r.admNo === admNo);
    if (!rec) return;

    const subjInput = document.getElementById('entrySubjectInput');
    const internalInput = document.getElementById('entryInternalMarks');
    const theoryInput = document.getElementById('entryTheoryMarks');
    const missingStatusSelect = document.getElementById('entryMissingStatus');
    const notesInput = document.getElementById('entryNotesInput');

    if (subjInput) subjInput.value = rec.subject;
    if (internalInput) internalInput.value = rec.internal;
    if (theoryInput) theoryInput.value = rec.theory;
    if (missingStatusSelect) missingStatusSelect.value = rec.missingEntry;
    if (notesInput) notesInput.value = rec.notes;
    calcEntryTotalLive();
  }

  function calcEntryTotalLive() {
    const intVal = parseFloat(document.getElementById('entryInternalMarks')?.value || 0);
    const thVal = parseFloat(document.getElementById('entryTheoryMarks')?.value || 0);
    const tot = intVal + thVal;
    const gInfo = computeGradeAndGp(tot);
    const previewEl = document.getElementById('entryTotalGradePreview');
    if (previewEl) {
      previewEl.textContent = `Total: ${tot} / 100 • Grade: ${gInfo.grade} (${gInfo.gp})`;
      previewEl.style.color = tot > 100 ? '#dc2626' : '#0f172a';
    }
  }

  function onEntryMissingStatusChange(status) {
    if (status !== 'None (Entered)') {
      const intInput = document.getElementById('entryInternalMarks');
      const thInput = document.getElementById('entryTheoryMarks');
      if (intInput) intInput.value = 0;
      if (thInput) thInput.value = 0;
      calcEntryTotalLive();
    }
  }

  function handleEnterMarksSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const admNo = document.getElementById('entryStudentSelect')?.value;
    const internal = parseFloat(document.getElementById('entryInternalMarks')?.value || 0);
    const theory = parseFloat(document.getElementById('entryTheoryMarks')?.value || 0);
    const missingStatus = document.getElementById('entryMissingStatus')?.value || 'None (Entered)';
    const notes = document.getElementById('entryNotesInput')?.value || '';

    const tot = internal + theory;
    if (tot > 100) {
      showToast('Validation Failed: Combined score exceeds maximum permitted of 100 marks!', 'danger');
      return;
    }

    const rec = TABULATION_RECORDS.find(r => r.admNo === admNo);
    if (rec) {
      rec.internal = internal;
      rec.theory = theory;
      rec.marksObtained = tot;
      rec.missingEntry = missingStatus;
      rec.notes = notes;
      const gInfo = computeGradeAndGp(tot);
      rec.grade = `${gInfo.grade} (${gInfo.gp})`;
      closeModal('enterMarksModal');
      renderTabulationAndMarks();
      showToast(`Marks successfully validated and saved for ${rec.student} (${tot} / 100)`, 'success');
    }
  }

  function saveMarksDraft() {
    currentMarksBatchSubmissionStatus = 'Draft';
    TABULATION_RECORDS.forEach(r => r.submissionStatus = 'Draft');
    renderTabulationAndMarks();
    showToast('Marks draft successfully saved for Class X-A Mathematics (Local cache synchronized)', 'success');
  }

  function validateTabulationMarks() {
    let violations = 0;
    let unresolvedMissing = 0;

    TABULATION_RECORDS.forEach(r => {
      if (r.marksObtained > r.maxMarks) violations++;
      if (r.marksObtained === 0 && r.missingEntry === 'None (Entered)') unresolvedMissing++;
    });

    if (violations > 0) {
      showToast(`Validation Failed: ${violations} scores exceed permitted maximum mark ceiling!`, 'danger');
      return false;
    }
    if (unresolvedMissing > 0) {
      showToast(`Validation Warning: ${unresolvedMissing} candidate(s) have 0 marks without explicit Absent/Exempt resolution!`, 'warning');
      return false;
    }

    showToast('Validation Succeeded: All 44 entries comply with AP SCERT marks ceilings and institutional absent policies.', 'success');
    return true;
  }

  function submitMarksForApproval() {
    if (!validateTabulationMarks()) return;

    currentMarksBatchSubmissionStatus = 'Submitted for Review';
    isTabulationMarksLocked = true;
    TABULATION_RECORDS.forEach(r => r.submissionStatus = 'Submitted for Review');

    const targetSub = RESULT_APPROVAL_DATA.find(s => s.id === 'APR-2026-X-MATH');
    if (targetSub) {
      targetSub.status = 'Pending Review';
      targetSub.remarks = 'Batch submitted by Subject Teacher Sri B. Narayana on ' + new Date().toLocaleDateString('en-GB') + '. Awaiting Vice Principal review.';
    }

    renderTabulationAndMarks();
    if (typeof renderResultApprovalQueue === 'function') renderResultApprovalQueue();
    showToast('Class X-A Mathematics marks locked and submitted to Designated Reviewer (Sri Navva Anand, Vice Principal)!', 'success');
  }

  function openReturnForCorrectionModal() {
    openModal('returnForCorrectionModal');
  }

  function handleReturnForCorrectionSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const reason = document.getElementById('returnCorrectionReason')?.value || 'Re-check absent entries';

    currentMarksBatchSubmissionStatus = 'Changes Requested';
    isTabulationMarksLocked = false;
    TABULATION_RECORDS.forEach(r => r.submissionStatus = 'Changes Requested');

    const targetSub = RESULT_APPROVAL_DATA.find(s => s.id === 'APR-2026-X-MATH');
    if (targetSub) {
      targetSub.status = 'Changes Requested';
      targetSub.remarks = 'Changes Requested by Designated Reviewer: ' + reason;
    }

    closeModal('returnForCorrectionModal');
    renderTabulationAndMarks();
    if (typeof renderResultApprovalQueue === 'function') renderResultApprovalQueue();
    showToast('Marks batch returned to Subject Teacher with revision notes: ' + reason, 'warning');
  }

  function approveCurrentMarksBatch() {
    currentMarksBatchSubmissionStatus = 'Approved';
    isTabulationMarksLocked = true;
    TABULATION_RECORDS.forEach(r => r.submissionStatus = 'Approved');

    const targetSub = RESULT_APPROVAL_DATA.find(s => s.id === 'APR-2026-X-MATH');
    if (targetSub) {
      targetSub.status = 'Approved';
      targetSub.remarks = 'Verified against physical scripts. Final approval granted by Controller Sri Navva Anand on ' + new Date().toLocaleDateString('en-GB');
    }

    renderTabulationAndMarks();
    if (typeof renderResultApprovalQueue === 'function') renderResultApprovalQueue();
    showToast('Designated Reviewer Sign-Off Complete: Class X-A Mathematics approved for results compilation!', 'success');
  }

  function lockApprovedMarks() {
    currentMarksBatchSubmissionStatus = 'Locked';
    isTabulationMarksLocked = true;
    TABULATION_RECORDS.forEach(r => r.submissionStatus = 'Locked');
    renderTabulationAndMarks();
    showToast('Marks batch permanently locked against modifications. Authorized corrections require Executive Override.', 'info');
  }

  function generateTabulationRegister() {
    let csv = '"Roll No","Student Name","Admission No","Class","Subject","Maximum Marks","Internal (20)","Theory (80)","Moderation","Marks Obtained","Grade","Missing Status","Submission Status","Notes"\n';
    TABULATION_RECORDS.forEach((r, idx) => {
      csv += `"${idx + 1}","${r.student}","${r.admNo}","${r.class}","${r.subject}","${r.maxMarks}","${r.internal}","${r.theory}","${r.moderation}","${r.marksObtained}","${r.grade}","${r.missingEntry}","${r.submissionStatus}","${r.notes.replace(/"/g, '""')}"\n`;
    });
    downloadCsvFile('Sri_Vidya_Class_X_A_Official_Tabulation_Register.csv', csv);
    showToast('Official AP SCERT Tabulation Register generated and downloaded (CSV)', 'success');
  }


