  function handleRecordCorrectionSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const admNo = document.getElementById('corrStudentSelect')?.value || 'SV-0210';
    const subj = document.getElementById('corrSubjectSelect')?.value || 'Mathematics';
    const newScore = parseFloat(document.getElementById('corrNewMarks')?.value || 99);
    const authorizer = document.getElementById('corrAuthorizer')?.value || 'Vice Principal';
    const reason = document.getElementById('corrAuditReason')?.value || 'Re-verification';

    AUDIT_CORRECTIONS_LOG.unshift({
      timestamp: new Date().toISOString(),
      studentAdm: admNo,
      subject: subj,
      newScore: newScore,
      authorizer: authorizer,
      reason: reason
    });

    closeModal('recordCorrectionModal');
    handleInlineMarkChange(admNo, newScore);
    showToast(`Correction officially authorized & recorded: ${admNo} ${subj} = ${newScore} (Auth: ${authorizer})`, 'success');
  }



  
  
  
