  // =========================================================================
  // 8.1 INCIDENT RECORDS RENDERER & ACTIONS
  // =========================================================================
  function renderDisciplineIncidents(list) {
    const tableBody = document.getElementById('incidentsTableBody');
    const incidents = list || state.disciplineIncidents || [];

    // Sync badges & stats
    const badgeAll = document.getElementById('tabBadgeDisciplineAll');
    if (badgeAll) badgeAll.textContent = incidents.length;
    const activeBadge = document.getElementById('activeIncidentsBadge');
    const openCount = (state.disciplineIncidents || []).filter(i => i.status !== 'Resolved' && i.status !== 'Closed').length;
    if (activeBadge) activeBadge.textContent = `${openCount} Active Case${openCount === 1 ? '' : 's'}`;
    const activeCasesCount = document.getElementById('activeCasesCount');
    if (activeCasesCount) activeCasesCount.textContent = openCount;

    if (!tableBody) return;

    if (incidents.length === 0) {
      tableBody.innerHTML = '<tr><td colspan="12" class="text-center p-4 text-muted">No disciplinary incidents match criteria. All students in good standing!</td></tr>';
      return;
    }

    const isLeadership = (state.currentRole === 'principal' || state.currentRole === 'vice-principal');

    tableBody.innerHTML = incidents.map(inc => {
      let badgeClass = 'badge-warning';
      if (inc.status === 'Resolved' || inc.status === 'Closed') badgeClass = 'badge-success';
      else if (inc.severity === 'Severe' || inc.severity === 'High') badgeClass = 'badge-danger';

      let sevBadge = 'badge-neutral';
      if (inc.severity === 'Severe' || inc.severity === 'High') sevBadge = 'badge-danger';
      else if (inc.severity === 'Moderate') sevBadge = 'badge-warning';
      else if (inc.severity === 'Minor') sevBadge = 'badge-primary';

      const isRestrictedAndHidden = inc.isSensitive && !isLeadership;

      const descText = isRestrictedAndHidden 
        ? '<span class="badge-restricted-mask"><i class="fa-solid fa-lock"></i> Restricted Case — Leadership Clearance Required</span>'
        : `<div style="font-size: 0.83rem; color: #334155; line-height: 1.4;">${inc.description}</div>`;

      const immActionText = isRestrictedAndHidden
        ? '<span class="text-muted"><i class="fa-solid fa-user-shield"></i> Quarantined by VP</span>'
        : `<div style="font-size: 0.82rem; font-weight: 600; color: #0f172a;">${inc.immediateAction}</div>`;

      return `
        <tr>
          <td>
            <div style="display:flex; align-items:center; gap:5px;">
              <strong class="text-primary font-mono" style="font-size: 0.85rem;">${inc.id}</strong>
              ${inc.isSensitive ? '<span title="Restricted Confidential Incident" style="color:#ef4444;"><i class="fa-solid fa-lock"></i></span>' : ''}
            </div>
          </td>
          <td>
            <div style="font-weight: 700; color: #1e293b; font-size:0.83rem;"><i class="fa-regular fa-calendar text-muted"></i> ${inc.date}</div>
            <small class="text-muted"><i class="fa-regular fa-clock"></i> ${inc.time || '11:15 AM'}</small>
          </td>
          <td>
            <span class="portal-badge badge-neutral" style="font-size:0.75rem;"><i class="fa-solid fa-location-dot text-primary"></i> ${inc.location || 'Campus'}</span>
          </td>
          <td>
            <span class="portal-badge ${sevBadge}" style="display: inline-block; margin-bottom: 2px;">${inc.severity}</span>
            <div style="font-size: 0.8rem; font-weight: 600; color: #334155;">${inc.category}</div>
          </td>
          <td>
            <div style="font-weight: 700; color: #0f172a; font-size: 0.88rem;">${inc.student}</div>
            <small class="text-muted"><span class="font-mono">${inc.admNo}</span> &bull; <span class="portal-badge badge-primary" style="font-size:0.7rem;">${inc.class}</span></small>
          </td>
          <td>
            <div style="font-size: 0.82rem; font-weight: 600; color: #1e293b;">${inc.reportingStaff}</div>
          </td>
          <td>${descText}</td>
          <td>${immActionText}</td>
          <td>
            <div style="font-size: 0.82rem; font-weight: 700; color: #1e40af;"><i class="fa-solid fa-user-check"></i> ${inc.assignedReviewer}</div>
          </td>
          <td>
            <div style="font-size: 0.8rem; color: #475569;">${inc.followUp}</div>
          </td>
          <td>
            <span class="portal-badge ${badgeClass}" style="font-weight: 700;">${inc.status}</span>
          </td>
          <td style="text-align: center; white-space: nowrap;">
            <div style="display:flex; gap:4px; justify-content:center;">
              <button class="btn btn-secondary btn-sm" onclick="portalApp.openAssignIncidentReviewerModal('${inc.id}')" title="Assign / Change Reviewer">
                <i class="fa-solid fa-user-tag text-primary"></i>
              </button>
              <button class="btn btn-secondary btn-sm" onclick="portalApp.openAddAuthorizedIncidentNoteModal('${inc.id}')" title="Add Authorized Case Note">
                <i class="fa-solid fa-comment-medical text-emerald"></i>
              </button>
              <button class="btn btn-secondary btn-sm" onclick="portalApp.openRecordIncidentFollowUpModal('${inc.id}')" title="Record Follow-Up Protocol">
                <i class="fa-solid fa-list-check text-blue"></i>
              </button>
              <button class="btn btn-secondary btn-sm" onclick="portalApp.scheduleIncidentParentMeeting('${inc.id}')" title="Schedule Parent Meeting">
                <i class="fa-solid fa-phone text-amber"></i>
              </button>
              ${inc.status !== 'Closed' ? `
                <button class="btn btn-primary btn-sm" onclick="portalApp.closeIncidentCase('${inc.id}')" title="Close Case Formally">
                  <i class="fa-solid fa-check"></i>
                </button>
              ` : ''}
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

  function filterDisciplineIncidents(sev) {
    if (!state.disciplineIncidents) return;
    const searchVal = (document.getElementById('incidentsSearchInput')?.value || '').toLowerCase().trim();
    
    let filtered = state.disciplineIncidents.filter(i => {
      let matchesSev = true;
      if (sev === 'High') matchesSev = (i.severity === 'High' || i.severity === 'Severe');
      else if (sev === 'Moderate') matchesSev = (i.severity === 'Moderate');
      else if (sev === 'Minor') matchesSev = (i.severity === 'Minor');

      let matchesSearch = true;
      if (searchVal) {
        matchesSearch = (i.student && i.student.toLowerCase().includes(searchVal)) ||
                        (i.admNo && i.admNo.toLowerCase().includes(searchVal)) ||
                        (i.id && i.id.toLowerCase().includes(searchVal)) ||
                        (i.location && i.location.toLowerCase().includes(searchVal)) ||
                        (i.category && i.category.toLowerCase().includes(searchVal));
      }

      return matchesSev && matchesSearch;
    });

    renderDisciplineIncidents(filtered);
  }

  function openRecordIncidentModal() {
    const nextId = 'INC-2026-0' + Math.floor(45 + (state.disciplineIncidents ? state.disciplineIncidents.length : 0));
    const idInput = document.getElementById('recIncId');
    if (idInput) idInput.value = nextId;

    const dtInput = document.getElementById('recIncDateTime');
    if (dtInput) {
      const now = new Date();
      now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
      dtInput.value = now.toISOString().slice(0, 16);
    }
    openModal('recordIncidentModal');
  }

  function handleRecordIncidentSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const id = document.getElementById('recIncId')?.value || 'INC-2026-045';
    const dt = document.getElementById('recIncDateTime')?.value || new Date().toISOString();
    const loc = document.getElementById('recIncLocation')?.value || 'Main Campus';
    const cat = document.getElementById('recIncCategory')?.value || 'Behavioral / Insubordination';
    const studentRaw = document.getElementById('recIncStudent')?.value || 'B. Tarun Reddy|SV-0042|Class IX-A';
    const [studentName, admNo, cls] = studentRaw.split('|');
    const reportingStaff = document.getElementById('recIncReportingStaff')?.value || 'Duty Faculty';
    const desc = document.getElementById('recIncDescription')?.value || '';
    const immAction = document.getElementById('recIncImmediateAction')?.value || 'Parties separated; escalated to VP';
    const reviewer = document.getElementById('recIncReviewer')?.value || 'Sri Navva Anand (Vice Principal)';
    const followUp = document.getElementById('recIncFollowUp')?.value || 'Parent conference scheduled';
    const status = document.getElementById('recIncStatus')?.value || 'Under Review';
    const isSensitive = !!document.getElementById('recIncIsSensitive')?.checked;

    const dateFormatted = new Date(dt).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
    const timeFormatted = new Date(dt).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });

    const newRecord = {
      id: id,
      datetime: dt,
      date: dateFormatted,
      time: timeFormatted,
      location: loc,
      category: cat,
      student: studentName,
      admNo: admNo,
      class: cls,
      reportingStaff: reportingStaff,
      description: desc,
      immediateAction: immAction,
      assignedReviewer: reviewer,
      followUp: followUp,
      status: status,
      severity: cat.includes('Device') || cat.includes('Damage') ? 'Moderate' : (cat.includes('Bullying') || cat.includes('Dishonesty') ? 'High' : 'Minor'),
      isSensitive: isSensitive,
      notes: [
        { date: `${dateFormatted} ${timeFormatted}`, author: reviewer, type: 'Intake Note', text: `Incident logged by ${reportingStaff}. Initial directive: ${immAction}` }
      ]
    };

    state.disciplineIncidents.unshift(newRecord);
    renderDisciplineIncidents();
    closeModal('recordIncidentModal');
    showToast(`Incident ${id} recorded for ${studentName} under Vice Principal oversight`, 'success');
  }

  function openAssignIncidentReviewerModal(id) {
    const inc = (state.disciplineIncidents || []).find(i => i.id === id);
    if (!inc) return;

    document.getElementById('assignRevIncidentId').value = id;
    document.getElementById('assignRevCaseDisplay').textContent = `${inc.id} • ${inc.student} (${inc.class}) — ${inc.category}`;
    openModal('assignIncidentReviewerModal');
  }

  function handleAssignIncidentReviewerSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const id = document.getElementById('assignRevIncidentId')?.value;
    const reviewer = document.getElementById('assignRevOfficial')?.value;
    const notes = document.getElementById('assignRevNotes')?.value;

    const inc = (state.disciplineIncidents || []).find(i => i.id === id);
    if (inc) {
      inc.assignedReviewer = reviewer;
      if (notes) {
        inc.notes.push({
          date: new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }),
          author: 'Executive Desk',
          type: 'Reviewer Assignment',
          text: `Case referred to ${reviewer}. Directive: ${notes}`
        });
      }
      renderDisciplineIncidents();
      closeModal('assignIncidentReviewerModal');
      showToast(`Reviewer for ${id} reassigned to ${reviewer}`, 'success');
    }
  }

  function openAddAuthorizedIncidentNoteModal(id) {
    const inc = (state.disciplineIncidents || []).find(i => i.id === id);
    if (!inc) return;

    document.getElementById('addNoteIncidentId').value = id;
    document.getElementById('addNoteCaseDisplay').textContent = `${inc.id} • ${inc.student} (${inc.class})`;
    document.getElementById('addNoteText').value = '';
    openModal('addAuthorizedIncidentNoteModal');
  }

  function handleAddAuthorizedIncidentNoteSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const id = document.getElementById('addNoteIncidentId')?.value;
    const cat = document.getElementById('addNoteCategory')?.value;
    const text = document.getElementById('addNoteText')?.value;
    const auth = document.getElementById('addNoteAuthorizer')?.value || 'Vice Principal';

    const inc = (state.disciplineIncidents || []).find(i => i.id === id);
    if (inc && text) {
      inc.notes = inc.notes || [];
      inc.notes.push({
        date: new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }) + ' ' + new Date().toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' }),
        author: auth,
        type: cat,
        text: text
      });
      closeModal('addAuthorizedIncidentNoteModal');
      showToast(`Authorized note recorded for ${id}`, 'success');
    }
  }

  function openRecordIncidentFollowUpModal(id) {
    const inc = (state.disciplineIncidents || []).find(i => i.id === id);
    if (!inc) return;

    document.getElementById('recFollowUpIncidentId').value = id;
    document.getElementById('recFollowUpCaseDisplay').textContent = `${inc.id} • ${inc.student} (${inc.class})`;
    document.getElementById('recFollowUpAction').value = inc.followUp || '';
    openModal('recordIncidentFollowUpModal');
  }

  function handleRecordIncidentFollowUpSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const id = document.getElementById('recFollowUpIncidentId')?.value;
    const action = document.getElementById('recFollowUpAction')?.value;
    const status = document.getElementById('recFollowUpStatus')?.value;

    const inc = (state.disciplineIncidents || []).find(i => i.id === id);
    if (inc) {
      inc.followUp = action;
      inc.status = status;
      inc.notes = inc.notes || [];
      inc.notes.push({
        date: new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }),
        author: 'Vice Principal Sri Navva Anand',
        type: 'Follow-Up Resolution',
        text: `Follow-up logged: ${action}. Status updated to: ${status}`
      });
      renderDisciplineIncidents();
      closeModal('recordIncidentFollowUpModal');
      showToast(`Follow-up protocol saved for ${id}`, 'success');
    }
  }

  function scheduleIncidentParentMeeting(id) {
    const inc = (state.disciplineIncidents || []).find(i => i.id === id);
    if (!inc) return;

    openScheduleParentMeetingModal();
    const select = document.getElementById('meetStudentSelect');
    if (select) {
      for (let i = 0; i < select.options.length; i++) {
        if (select.options[i].value.includes(inc.student)) {
          select.selectedIndex = i;
          break;
        }
      }
    }
    const purp = document.getElementById('meetPurpose');
    if (purp) purp.value = `Disciplinary inquiry regarding incident ${inc.id}: ${inc.category}`;
  }

  function closeIncidentCase(id) {
    const inc = (state.disciplineIncidents || []).find(i => i.id === id);
    if (inc) {
      inc.status = 'Closed';
      inc.notes = inc.notes || [];
      inc.notes.push({
        date: new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }),
        author: 'Vice Principal Sri Navva Anand',
        type: 'Case Closure',
        text: 'All follow-up obligations fulfilled. Case formally closed and archived in student conduct register.'
      });
      renderDisciplineIncidents();
      showToast(`Incident ${id} formally closed and archived in permanent register.`, 'success');
    }
  }

  function openRestrictedIncidentHistoryModal() {
    const isLeadership = (state.currentRole === 'principal' || state.currentRole === 'vice-principal');
    if (!isLeadership) {
      showToast('Restricted Access: Only Principal and Vice Principal have clearance to review confidential incident logs.', 'danger');
      return;
    }

    const container = document.getElementById('restrictedHistoryContainer');
    if (!container) return;

    const list = state.disciplineIncidents || [];
    container.innerHTML = list.map(inc => `
      <div style="border: 1px solid #e2e8f0; border-radius: 8px; padding: 1rem; margin-bottom: 1rem; background: #fff;">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:0.5rem; flex-wrap:wrap; gap:0.5rem;">
          <div>
            <strong style="color:#1e40af; font-family:monospace; font-size:0.95rem;">${inc.id}</strong>
            <span style="font-weight:700; margin-left:8px; color:#0f172a;">${inc.student} (${inc.admNo} • ${inc.class})</span>
            ${inc.isSensitive ? '<span class="portal-badge badge-danger" style="margin-left:6px;"><i class="fa-solid fa-lock"></i> Sensitive</span>' : ''}
          </div>
          <div>
            <span class="portal-badge ${inc.status === 'Closed' ? 'badge-success' : 'badge-warning'}">${inc.status}</span>
            <span class="text-muted" style="font-size:0.8rem; margin-left:8px;"><i class="fa-regular fa-calendar"></i> ${inc.date}</span>
          </div>
        </div>
        <div style="font-size:0.85rem; color:#334155; margin-bottom:0.5rem;">
          <strong>Category:</strong> ${inc.category} &bull; <strong>Location:</strong> ${inc.location} &bull; <strong>Reporting Staff:</strong> ${inc.reportingStaff}
        </div>
        <div style="font-size:0.85rem; color:#475569; background:#f8fafc; padding:8px 12px; border-radius:6px; margin-bottom:0.5rem;">
          <strong>Description:</strong> ${inc.description}<br>
          <strong>Immediate Action:</strong> ${inc.immediateAction}<br>
          <strong>Follow-Up:</strong> ${inc.followUp}
        </div>
        <div style="margin-top:0.75rem;">
          <strong style="font-size:0.78rem; text-transform:uppercase; color:#64748b; letter-spacing:0.04em;">Audit Notes &amp; Decisions:</strong>
          <div style="margin-top:4px;">
            ${(inc.notes && inc.notes.length > 0) ? inc.notes.map(n => `
              <div style="font-size:0.8rem; color:#1e293b; border-left:2px solid #2563eb; padding-left:8px; margin-bottom:4px;">
                <span class="text-muted">[${n.date} - ${n.author} (${n.type})]:</span> ${n.text}
              </div>
            `).join('') : '<span class="text-muted" style="font-size:0.8rem;">No formal notes appended yet.</span>'}
          </div>
        </div>
      </div>
    `).join('');

    openModal('restrictedIncidentHistoryModal');
  }

  // =========================================================================
  // 8.2 LATE-COMING REGISTER RENDERER & ACTIONS
  // =========================================================================
  function renderGateLateComing(list) {
    const tbody = document.getElementById('disciplineLateArrivalsTableBody') || document.getElementById('morningGateLateTableBody');
    if (!tbody) return;

    const records = list || state.gateLateRecords || [];

    const lateBadge = document.getElementById('tabBadgeDisciplineLate');
    if (lateBadge) lateBadge.textContent = records.length;
    const lateTodayCount = document.getElementById('lateArrivalsTodayCount');
    if (lateTodayCount) lateTodayCount.textContent = records.length;
    const btnCount = document.getElementById('btnLateCountLabel');
    if (btnCount) btnCount.textContent = records.length;

    if (records.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" class="text-center p-4 text-muted">No gate late arrivals recorded for today. Punctuality at 100%!</td></tr>';
      return;
    }

    tbody.innerHTML = records.map(r => {
      const commStatus = r.parentCommStatus || 'SMS Delivered (08:50 AM)';
      const repeatOcc = r.repeatOccurrences || '1st Offense';

      let commBadge = 'badge-success';
      if (commStatus.includes('Call')) commBadge = 'badge-primary';
      else if (commStatus.includes('Waiver') || commStatus.includes('Excused')) commBadge = 'badge-neutral';
      else if (commStatus.includes('Pending')) commBadge = 'badge-warning';

      let repBadge = 'badge-neutral';
      if (repeatOcc.includes('3rd') || repeatOcc.includes('Flagged')) repBadge = 'badge-danger';
      else if (repeatOcc.includes('2nd')) repBadge = 'badge-warning';

      return `
        <tr>
          <td>
            <div style="font-weight: 700; color: #0f172a; font-size:0.88rem;">${r.student}</div>
            <small class="text-muted"><span class="font-mono">${r.admNo}</span> &bull; <span class="portal-badge badge-primary" style="font-size:0.7rem;">${r.class}</span></small>
          </td>
          <td>
            <span style="font-size:0.83rem; font-weight:600; color:#1e293b;"><i class="fa-regular fa-calendar text-muted"></i> ${r.date}</span>
          </td>
          <td>
            <div style="font-weight:700; color:#e11d48; font-size:0.88rem;"><i class="fa-regular fa-clock"></i> ${r.arrivalTime}</div>
            <span class="late-delay-tag">${r.delay}</span>
          </td>
          <td>
            <div style="font-size:0.82rem; color:#334155; font-weight:600;">${r.reason}</div>
          </td>
          <td>
            <span style="font-size:0.8rem; color:#475569;"><i class="fa-solid fa-id-badge text-primary"></i> ${r.recordedBy}</span>
          </td>
          <td>
            <span class="portal-badge ${commBadge}" style="font-size:0.74rem;">${r.parentCommStatus}</span>
          </td>
          <td>
            <span class="portal-badge ${repBadge}" style="font-size:0.74rem; font-weight:700;">${r.repeatOccurrences}</span>
          </td>
          <td style="text-align: center; white-space: nowrap;">
            <div style="display:flex; gap:4px; justify-content:center;">
              <button class="btn btn-secondary btn-sm" onclick="portalApp.openCorrectLateEntryModal('${r.id}')" title="Correct Late Entry">
                <i class="fa-solid fa-pen text-primary"></i>
              </button>
              <button class="btn btn-secondary btn-sm" onclick="portalApp.sendAuthorizedLateNotification('${r.id}')" title="Send Authorized Notification">
                <i class="fa-solid fa-paper-plane text-amber"></i>
              </button>
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

  function openRecordLateArrivalModal() {
    const dateInput = document.getElementById('recLateDate');
    if (dateInput) dateInput.value = new Date().toISOString().slice(0, 10);
    openModal('recordLateArrivalModal');
  }

  function handleRecordLateArrivalSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const studentRaw = document.getElementById('recLateStudent')?.value || 'CH. Karthik|SV-0041|Class VIII-A';
    const [studentName, admNo, cls] = studentRaw.split('|');
    const dt = document.getElementById('recLateDate')?.value || new Date().toISOString().slice(0, 10);
    const tm = document.getElementById('recLateTime')?.value || '08:50';
    const reason = document.getElementById('recLateReason')?.value || 'Traffic delay';
    const recordedBy = document.getElementById('recLateRecordedBy')?.value || 'Security Officer K. Ramaiah';

    const formattedDate = new Date(dt).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
    const formattedTime = tm + ' AM';

    const prevCount = (state.gateLateRecords || []).filter(r => r.admNo === admNo).length;
    const repeatStr = prevCount === 0 ? '1st Offense' : (prevCount === 1 ? '2nd time this term (Moderate)' : `${prevCount + 1}rd time this week (High Frequency - Flagged)`);

    const newLate = {
      id: 'GL-2026-0' + Math.floor(85 + (state.gateLateRecords ? state.gateLateRecords.length : 0)),
      student: studentName,
      admNo: admNo,
      class: cls,
      date: formattedDate,
      arrivalTime: formattedTime,
      delay: '+20 mins late',
      reason: reason,
      recordedBy: recordedBy,
      parentCommStatus: reason.includes('Bus') ? 'Official Bus Waiver (No SMS)' : 'SMS Delivered (' + formattedTime + ')',
      repeatOccurrences: repeatStr,
      status: 'Gate Pass Issued'
    };

    state.gateLateRecords.unshift(newLate);
    renderGateLateComing();
    closeModal('recordLateArrivalModal');
    showToast(`Late arrival logged for ${studentName} (${formattedTime}). Punctuality ledger updated.`, 'success');
  }

  function openCorrectLateEntryModal(id) {
    const record = (state.gateLateRecords || []).find(r => r.id === id);
    if (!record) return;

    document.getElementById('corrLateId').value = id;
    document.getElementById('corrLateStudentDisplay').textContent = `${record.student} (${record.admNo} • ${record.class}) — ${record.date}`;
    const timeVal = record.arrivalTime || record.time || '08:50'; document.getElementById('corrLateTime').value = timeVal.replace(/[^0-9:]/g, '').padStart(5, '0');
    document.getElementById('corrLateReason').value = record.reason;
    document.getElementById('corrLateAuditReason').value = '';
    openModal('correctLateEntryModal');
  }

  function handleCorrectLateEntrySubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const id = document.getElementById('corrLateId')?.value;
    const time = document.getElementById('corrLateTime')?.value;
    const reason = document.getElementById('corrLateReason')?.value;
    const audit = document.getElementById('corrLateAuditReason')?.value;

    const record = (state.gateLateRecords || []).find(r => r.id === id);
    if (record) {
      record.arrivalTime = time + ' AM';
      record.reason = reason;
      record.parentCommStatus += ' [Corrected by VP]';
      renderGateLateComing();
      closeModal('correctLateEntryModal');
      showToast(`Late entry ${id} officially corrected (Audit: ${audit})`, 'success');
    }
  }

