  function publishApprovedAchievement(id) {
    if (id) {
      const m = (state.meritAwards || []).find(x => x.id === id);
      if (m) {
        if (m.approvalStatus !== 'Approved') {
          showToast('Requirement: Achievements must be formally approved before public publication.', 'warning');
          return;
        }
        m.isPublished = !m.isPublished;
        renderMeritAwards();
        showToast(m.isPublished 
          ? `Achievement for ${m.student} published to School Honor Wall!` 
          : `Achievement unpublished from public view.`, 
          m.isPublished ? 'success' : 'info');
      }
    } else {
      let count = 0;
      (state.meritAwards || []).forEach(m => {
        if (m.approvalStatus === 'Approved') {
          m.isPublished = true;
          count++;
        }
      });
      renderMeritAwards();
      showToast(`${count} Approved Merit Achievements published to Public Website & Portal!`, 'success');
    }
  }

  // =========================================================================
  // 8.4 PARENT MEETINGS RENDERER & ACTIONS
  // =========================================================================
  function renderParentConvocations(list) {
    const tableBody = document.getElementById('disciplineParentMeetingsTableBody');
    if (!tableBody) return;

    const records = list || state.parentConvocations || [];

    const meetBadge = document.getElementById('tabBadgeDisciplineMeetings');
    if (meetBadge) meetBadge.textContent = records.length;

    if (records.length === 0) {
      tableBody.innerHTML = '<tr><td colspan="8" class="text-center p-4 text-muted">No parent convocations or disciplinary conferences scheduled.</td></tr>';
      return;
    }

    tableBody.innerHTML = records.map(p => {
      const meetStatus = p.meetingStatus || 'Scheduled';
      const guardian = p.guardian || 'Parent / Guardian';
      const staff = p.assignedStaff || 'Vice Principal Sri Navva Anand';
      const tasks = p.followUpTasks || p.followUp || 'Follow-up pending';

      let statBadge = 'badge-warning';
      if (meetStatus === 'Concluded' || meetStatus.includes('Attended')) statBadge = 'badge-success';
      else if (meetStatus.includes('Invited') || meetStatus.includes('Dispatched')) statBadge = 'badge-primary';

      return `
        <tr>
          <td>
            <div style="font-weight: 700; color: #0f172a; font-size:0.88rem;">${p.student}</div>
            <small class="text-muted"><span class="font-mono">${p.admNo}</span> &bull; <span class="portal-badge badge-primary" style="font-size:0.7rem;">${p.class}</span></small>
          </td>
          <td>
            <div style="font-weight: 600; color: #1e293b; font-size:0.84rem;">${p.guardian}</div>
            <small class="text-muted"><i class="fa-solid fa-phone"></i> ${p.phone}</small>
          </td>
          <td>
            <div style="font-size: 0.82rem; font-weight: 600; color: #1e3a8a;">${p.purpose}</div>
          </td>
          <td>
            <span style="font-size:0.82rem; font-weight:700; color:#0f172a;"><i class="fa-solid fa-user-tie text-primary mr-1"></i> ${p.assignedStaff}</span>
          </td>
          <td>
            <div style="font-weight: 600; color: #1e293b; font-size:0.82rem;"><i class="fa-regular fa-calendar-check text-muted"></i> ${p.scheduledDate}</div>
          </td>
          <td>
            <span class="portal-badge ${statBadge}" style="font-weight:700; font-size:0.75rem;">${p.meetingStatus}</span>
          </td>
          <td>
            <div style="font-size:0.8rem; color:#475569;">${p.followUpTasks}</div>
          </td>
          <td style="text-align: center; white-space: nowrap;">
            <div style="display:flex; gap:4px; justify-content:center;">
              <button class="btn btn-secondary btn-sm" onclick="portalApp.inviteMeetingParticipants('${p.id}')" title="Invite Participants (Send Summons)">
                <i class="fa-solid fa-envelope-open-text text-primary"></i>
              </button>
              <button class="btn btn-secondary btn-sm" onclick="portalApp.recordMeetingAttendance('${p.id}')" title="Record Attendance">
                <i class="fa-solid fa-clipboard-user text-emerald"></i>
              </button>
              <button class="btn btn-secondary btn-sm" onclick="portalApp.openAddRestrictedMeetingNotesModal('${p.id}')" title="Add Restricted Meeting Notes">
                <i class="fa-solid fa-lock text-amber"></i>
              </button>
              ${p.meetingStatus !== 'Concluded' ? `
                <button class="btn btn-primary btn-sm" onclick="portalApp.closeParentMeeting('${p.id}')" title="Conclude &amp; Close Meeting">
                  <i class="fa-solid fa-check"></i>
                </button>
              ` : ''}
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

  function openScheduleParentMeetingModal() {
    const dtInput = document.getElementById('meetDateTime');
    if (dtInput) {
      const now = new Date();
      now.setDate(now.getDate() + 2);
      now.setHours(10, 0, 0, 0);
      now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
      dtInput.value = now.toISOString().slice(0, 16);
    }
    openModal('scheduleParentMeetingModal');
  }

  function handleScheduleParentMeetingSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const raw = document.getElementById('meetStudentSelect')?.value || 'B. Tarun Reddy|SV-0042|Class IX-A|B. Appa Rao (Father)|9848123490';
    const [name, adm, cls, guardian, phone] = raw.split('|');
    const purp = document.getElementById('meetPurpose')?.value || 'Student welfare review';
    const staff = document.getElementById('meetStaff')?.value || 'Sri Navva Anand (Vice Principal)';
    const dt = document.getElementById('meetDateTime')?.value;
    const venue = document.getElementById('meetVenue')?.value || 'Vice Principal Chamber';
    const followUp = document.getElementById('meetFollowUp')?.value || 'Review signed conduct undertaking';

    const formattedDT = new Date(dt).toLocaleDateString('en-GB', { weekday: 'short', day: '2-digit', month: 'short', year: 'numeric' }) + ' • ' + new Date(dt).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' }) + ' • ' + venue;

    const newMeeting = {
      id: 'CONV-2026-0' + Math.floor(11 + (state.parentConvocations ? state.parentConvocations.length : 0)),
      student: name,
      admNo: adm,
      class: cls,
      guardian: guardian,
      phone: phone,
      purpose: purp,
      assignedStaff: staff,
      scheduledDate: formattedDT,
      meetingStatus: 'Scheduled',
      followUpTasks: followUp,
      restrictedNotes: ''
    };

    state.parentConvocations.unshift(newMeeting);
    renderParentConvocations();
    closeModal('scheduleParentMeetingModal');
    showToast(`Formal Parent Meeting scheduled for ${name} with ${staff}. Digital invite prepared.`, 'success');
  }

  function inviteMeetingParticipants(id) {
    const p = (state.parentConvocations || []).find(x => x.id === id);
    if (p) {
      p.meetingStatus = 'Invitation Dispatched';
      renderParentConvocations();
      showToast(`Official summons letter & SMS invite dispatched to ${p.guardian} (${p.phone}) and ${p.assignedStaff}.`, 'success');
    }
  }

  function recordMeetingAttendance(id) {
    const p = (state.parentConvocations || []).find(x => x.id === id);
    if (p) {
      p.meetingStatus = 'Attended & Signed Undertaking';
      renderParentConvocations();
      showToast(`Meeting attendance verified: ${p.guardian} attended conference with ${p.assignedStaff}.`, 'success');
    }
  }

  function openAddRestrictedMeetingNotesModal(id) {
    const p = (state.parentConvocations || []).find(x => x.id === id);
    if (!p) return;

    document.getElementById('meetNotesId').value = id;
    document.getElementById('meetNotesCaseDisplay').textContent = `${p.id} • ${p.student} (${p.class}) with ${p.guardian}`;
    document.getElementById('meetNotesContent').value = p.restrictedNotes || '';
    document.getElementById('meetNotesTasks').value = p.followUpTasks || '';
    openModal('addRestrictedMeetingNotesModal');
  }

  function handleAddRestrictedMeetingNotesSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const id = document.getElementById('meetNotesId')?.value;
    const att = document.getElementById('meetNotesAttendance')?.value;
    const notes = document.getElementById('meetNotesContent')?.value;
    const tasks = document.getElementById('meetNotesTasks')?.value;

    const p = (state.parentConvocations || []).find(x => x.id === id);
    if (p) {
      p.meetingStatus = att;
      p.restrictedNotes = notes;
      p.followUpTasks = tasks;
      renderParentConvocations();
      closeModal('addRestrictedMeetingNotesModal');
      showToast(`Restricted conference minutes and follow-up tasks saved for ${p.student}.`, 'success');
    }
  }

  function closeParentMeeting(id) {
    const p = (state.parentConvocations || []).find(x => x.id === id);
    if (p) {
      p.meetingStatus = 'Concluded';
      renderParentConvocations();
      showToast(`Parent convocation ${p.id} concluded and archived with formal resolutions.`, 'success');
    }
  }

  // =========================================================================
  // 8.5 COUNSELLING REFERRALS RENDERER & ACTIONS
  // =========================================================================
  function renderCounsellingReferrals(list) {
    const tbody = document.getElementById('counsellingTableBody');
    const restrictedNotice = document.getElementById('counsellingRestrictedNotice');
    const authorizedDesk = document.getElementById('counsellingAuthorizedDesk');

    // Role-based safeguarding security gate:
    // Only Principal and Vice Principal (and designated child psychologist) have clearance to view confidential guidance files.
    const isLeadership = (state.currentRole === 'principal' || state.currentRole === 'vice-principal');

    if (!isLeadership) {
      if (restrictedNotice) restrictedNotice.style.display = 'block';
      if (authorizedDesk) authorizedDesk.style.display = 'none';
      return;
    } else {
      if (restrictedNotice) restrictedNotice.style.display = 'none';
      if (authorizedDesk) authorizedDesk.style.display = 'block';
    }

    if (!tbody) return;

    const records = list || state.counsellingReferrals || [];

    const cnsBadge = document.getElementById('tabBadgeDisciplineCounselling');
    if (cnsBadge) cnsBadge.textContent = records.length;

    if (records.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" class="text-center p-4 text-muted">No confidential counselling referrals on active docket.</td></tr>';
      return;
    }

    tbody.innerHTML = records.map(c => {
      const cStatus = c.caseStatus || 'Active / Open';
      const prof = c.assignedProfessional || c.counselor || 'Dr. Saranya CH';
      const appt = c.appointmentStatus || c.restrictedStatus || 'Active Therapy';
      const fuDate = c.followUpDate || 'Pending';

      let caseBadge = 'badge-warning';
      if (cStatus.includes('Resolved') || cStatus.includes('Graduated')) caseBadge = 'badge-success';
      else if (cStatus.includes('Closed')) caseBadge = 'badge-neutral';

      return `
        <tr>
          <td>
            <div style="display:flex; align-items:center; gap:5px;">
              <strong style="color: #92400e; font-family: monospace; font-size: 0.88rem;">${c.id}</strong>
              <span title="Confidential Safeguarding File" style="color:#f59e0b;"><i class="fa-solid fa-shield-halved"></i></span>
            </div>
          </td>
          <td>
            <div style="font-weight: 700; color: #0f172a; font-size:0.88rem;">${c.student}</div>
            <small class="text-muted"><span class="font-mono">${c.admNo}</span> &bull; <span class="portal-badge badge-primary" style="font-size:0.7rem;">${c.class}</span></small>
          </td>
          <td>
            <span style="font-size:0.83rem; font-weight:600; color:#334155;"><i class="fa-regular fa-calendar text-muted"></i> ${c.referralDate}</span>
          </td>
          <td>
            <div style="font-weight: 700; color: #1e40af; font-size:0.82rem;"><i class="fa-solid fa-user-doctor mr-1"></i> ${c.assignedProfessional}</div>
          </td>
          <td>
            <span class="portal-badge badge-neutral" style="font-size:0.75rem; font-weight:700;">${c.appointmentStatus}</span>
          </td>
          <td>
            <div style="font-size:0.82rem; font-weight:600; color:#0f172a;"><i class="fa-regular fa-clock text-muted"></i> ${c.followUpDate}</div>
          </td>
          <td>
            <span class="portal-badge ${caseBadge}" style="font-weight:700; font-size:0.75rem;">${c.caseStatus}</span>
          </td>
          <td style="text-align: center; white-space: nowrap;">
            <div style="display:flex; gap:4px; justify-content:center;">
              <button class="btn btn-secondary btn-sm" onclick="portalApp.openConfidentialCounsellingModal('${c.id}')" title="View Confidential Dossier">
                <i class="fa-solid fa-file-shield text-amber"></i>
              </button>
              ${c.caseStatus !== 'Graduated / Resolved' ? `
                <button class="btn btn-primary btn-sm" onclick="portalApp.closeCounsellingCase('${c.id}')" title="Graduate / Resolve Referral">
                  <i class="fa-solid fa-circle-check"></i>
                </button>
              ` : ''}
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }

  function openNewCounsellingModal() {
    const dateInput = document.getElementById('cnsRefDate');
    if (dateInput) dateInput.value = new Date().toISOString().slice(0, 10);
    const fuInput = document.getElementById('cnsNewFollowUpDate');
    if (fuInput) {
      const fu = new Date();
      fu.setDate(fu.getDate() + 7);
      fuInput.value = fu.toISOString().slice(0, 10);
    }
    openModal('newCounsellingReferralModal');
  }

  function handleNewCounsellingReferralSubmit(e) {
    if (e && e.preventDefault) e.preventDefault();
    const id = document.getElementById('cnsRefId')?.value || 'CNS-2026-04';
    const dt = document.getElementById('cnsRefDate')?.value;
    const raw = document.getElementById('cnsStudentSelect')?.value || 'P. Harsha Vardhan|SV-0065|Class IX-A';
    const [name, adm, cls] = raw.split('|');
    const prof = document.getElementById('cnsProfessional')?.value;
    const appt = document.getElementById('cnsApptStatus')?.value;
    const fuDate = document.getElementById('cnsNewFollowUpDate')?.value;
    const focus = document.getElementById('cnsFocusReason')?.value;
    const notes = document.getElementById('cnsConfidentialNotes')?.value;

    const formattedDate = new Date(dt).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
    const formattedFU = new Date(fuDate).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });

    const newRef = {
      id: id,
      student: name,
      admNo: adm,
      class: cls,
      referralDate: formattedDate,
      assignedProfessional: prof,
      appointmentStatus: appt,
      followUpDate: formattedFU,
      caseStatus: 'Active / Open',
      focusArea: focus,
      confidentialNotes: notes
    };

    state.counsellingReferrals.unshift(newRef);
    renderCounsellingReferrals();
    closeModal('newCounsellingReferralModal');
    showToast(`Confidential referral ${id} created for ${name}. Notes quarantined under safeguarding protocols.`, 'success');
  }

  function openConfidentialCounsellingModal(id) {
    const isLeadership = (state.currentRole === 'principal' || state.currentRole === 'vice-principal');
    if (!isLeadership) {
      showToast('Restricted: Only authorized welfare leadership has access to psychological case records.', 'danger');
      return;
    }

    const c = (state.counsellingReferrals || []).find(x => x.id === id);
    if (!c) return;

    const body = document.getElementById('counsellingDossierBody');
    if (!body) return;

    body.innerHTML = `
      <div style="background:#fffbeb; border:1px solid #fde68a; border-radius:8px; padding:1rem; margin-bottom:1rem;">
        <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:0.5rem;">
          <div>
            <strong style="color:#92400e; font-size:1.1rem; font-family:monospace;">${c.id}</strong>
            <span style="font-weight:700; color:#0f172a; margin-left:8px; font-size:1.05rem;">${c.student} (${c.admNo} &bull; ${c.class})</span>
          </div>
          <div>
            <span class="portal-badge badge-warning">${c.caseStatus}</span>
          </div>
        </div>
        <div style="font-size:0.85rem; color:#78350f; margin-top:6px;">
          <strong>Authorized Specialist:</strong> ${c.assignedProfessional} &bull; <strong>Referral Date:</strong> ${c.referralDate}
        </div>
      </div>

      <div style="margin-bottom:1rem;">
        <h5 style="font-weight:800; color:#0f172a; margin-bottom:4px;">Guidance Focus &amp; Pastoral Objective:</h5>
        <div style="font-size:0.9rem; color:#334155; background:#f8fafc; padding:8px 12px; border-radius:6px; border:1px solid #e2e8f0;">
          ${c.focusArea}
        </div>
      </div>

      <div style="margin-bottom:1.5rem;">
        <h5 style="font-weight:800; color:#92400e; margin-bottom:4px;"><i class="fa-solid fa-lock text-amber mr-1"></i> Quarantined Clinical Notes (Legally Protected):</h5>
        <div style="font-size:0.88rem; line-height:1.6; color:#451a03; background:#fefce8; border:1px solid #fef08a; padding:12px; border-radius:6px;">
          ${c.confidentialNotes}
        </div>
      </div>

      <div style="border-top:1px solid #e2e8f0; padding-top:1rem;">
        <div style="font-size:0.83rem; color:#64748b;">
          <strong>Next Scheduled Session:</strong> ${c.followUpDate} &bull; <strong>Status:</strong> ${c.appointmentStatus}
        </div>
      </div>
    `;

    openModal('confidentialCounsellingDossierModal');
  }

  function closeCounsellingCase(id) {
    const c = (state.counsellingReferrals || []).find(x => x.id === id);
    if (c) {
      c.caseStatus = 'Graduated / Resolved';
      c.appointmentStatus = 'Care Plan Concluded';
      c.confidentialNotes += ' [Case officially graduated. Student achieved behavioral / emotional stability milestone.]';
      renderCounsellingReferrals();
      showToast(`Counselling case ${c.id} successfully graduated and resolved.`, 'success');
    }
  }

  function exportCounsellingLedgerCSV() {
    const isLeadership = (state.currentRole === 'principal' || state.currentRole === 'vice-principal');
    if (!isLeadership) {
      showToast('Unauthorized: Export of confidential counselling logs is restricted to Principal / VP.', 'danger');
      return;
    }
    const headers = ['Referral ID', 'Student', 'Adm No', 'Class', 'Referral Date', 'Assigned Professional', 'Appointment Status', 'Follow-up Date', 'Case Status'];
    const rows = (state.counsellingReferrals || []).map(c => [
      c.id, c.student, c.admNo, c.class, c.referralDate, c.assignedProfessional, c.appointmentStatus, c.followUpDate, c.caseStatus
    ]);
    const csvContent = [headers.join(','), ...rows.map(r => r.map(x => '"' + String(x).replace(/"/g, '""') + '"').join(','))].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `SV_Counselling_Audit_Ledger_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
    showToast('Confidential Counselling Audit Ledger exported securely.', 'success');
  }


